  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Debe seguirse la tramitación ordinaria en todo caso, también en los procedimientos sancionadores.', false), ('B', 'La oposición no produce efectos, porque la decisión corresponde solo a la Administración.', false), ('C', 'La oposición se resuelve como cuestión incidental, suspendiendo el procedimiento.', false), ('D', 'Debe seguirse la tramitación ordinaria, salvo en los procedimientos sancionadores en que haya elementos para calificar la infracción como leve.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
