  select 'Según el artículo 32.3 de la Ley 39/2015, sobre la ampliación de plazos, señale la afirmación correcta:', 'El art. 32.3 LPAC exige que la petición y la decisión se produzcan antes del vencimiento, prohíbe ampliar un plazo vencido y declara irrecurribles los acuerdos sobre ampliación.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 32.3 LPAC', 'En ningún caso podrá ser objeto de ampliación un plazo ya vencido.', null, '60fb3b5b712383095a92581740bedb94be08d7d014391d0bc34670c6c07af152', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '60fb3b5b712383095a92581740bedb94be08d7d014391d0bc34670c6c07af152')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En ningún caso podrá ser objeto de ampliación un plazo ya vencido.', true), ('B', 'Puede ampliarse un plazo vencido si el interesado lo solicita dentro de los tres días siguientes.', false), ('C', 'Los acuerdos de ampliación o su denegación son recurribles en alzada.', false), ('D', 'La petición de ampliación puede presentarse después del vencimiento si se justifica la causa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
