  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 111 de la Ley 39/2015, en la Administración General del Estado, ¿quién es competente para la revisión de oficio de un acto nulo dictado por un Secretario de Estado?', 'El art. 111.b).1.º LPAC atribuye a los Ministros la revisión de los actos de los Secretarios de Estado; los Secretarios de Estado revisan los de sus órganos directivos dependientes, y el Consejo de Ministros los suyos y los de los Ministros.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 111 LPAC', 'Los Ministros, respecto de los actos y disposiciones de los Secretarios de Estado y de los dictados por órganos directivos de su Departamento no dependientes de una Secretaría de Estado.', null, '2e519b2cbbe8dca6100fcf20144b6d3f69c4c6b29fb73c47038c0273de8bfbef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2e519b2cbbe8dca6100fcf20144b6d3f69c4c6b29fb73c47038c0273de8bfbef')
  returning id
