)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una resolución de concesión de una ayuda contiene un error aritmético en la suma del importe. Según el artículo 109.2 de la Ley 39/2015, la Administración podrá rectificarlo:', 'El art. 109.2 LPAC permite rectificar en cualquier momento, de oficio o a instancia de parte, los errores materiales, de hecho o aritméticos.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 109.2 LPAC', 'Las Administraciones Públicas podrán, asimismo, rectificar en cualquier momento, de oficio o a instancia de los interesados, los errores materiales, de hecho o aritméticos existentes en sus actos.', null, 'a67b6fd457a6066097f001e2984e2707b99ef85f04913bef8364dc99f97b640c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a67b6fd457a6066097f001e2984e2707b99ef85f04913bef8364dc99f97b640c')
