with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una aspirante a un proceso selectivo del Cuerpo General Administrativo quiere impugnar un acuerdo del tribunal calificador. Según el artículo 121.1 de la Ley 39/2015, a efectos del recurso de alzada el tribunal se considera dependiente:', 'El art. 121.1 LPAC considera que los tribunales y órganos de selección dependen del órgano al que estén adscritos o, en su defecto, del que nombró al presidente, que resuelve la alzada.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 121.1 LPAC', 'los Tribunales y órganos de selección del personal al servicio de las Administraciones Públicas y cualesquiera otros que, en el seno de éstas, actúen con autonomía funcional, se considerarán dependientes del órgano al que estén adscritos o, en su defecto, del que haya nombrado al presidente de los mismos.', null, '5925e8105421da976e97d96aec4772cf1c281b356bae1938db43ec3de1c45e22', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5925e8105421da976e97d96aec4772cf1c281b356bae1938db43ec3de1c45e22')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del Consejo de Ministros, en todo caso.', false), ('B', 'De ningún órgano, por lo que su acuerdo pone fin a la vía administrativa.', false), ('C', 'Del órgano al que esté adscrito o, en su defecto, del que haya nombrado a su presidente.', true), ('D', 'Del Ministerio en el que preste servicios la mayoría de sus miembros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un interesado presenta su recurso de alzada ante la Subdirección que dictó el acto, en lugar de ante la Dirección General competente para resolverlo. De acuerdo con el artículo 121.2 de la Ley 39/2015, la Subdirección:', 'El art. 121.2 LPAC permite interponer la alzada ante el órgano que dictó el acto o ante el competente; si se presenta ante el primero, debe remitirlo en diez días con informe y copia del expediente.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 121.2 LPAC', 'Si el recurso se hubiera interpuesto ante el órgano que dictó el acto impugnado, éste deberá remitirlo al competente en el plazo de diez días, con su informe y con una copia completa y ordenada del expediente.', null, '2049a2f819707c49fbedf8c958d07452e7964388842dba11c747763cfc195dac', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2049a2f819707c49fbedf8c958d07452e7964388842dba11c747763cfc195dac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deberá inadmitirlo por haberse presentado ante órgano no competente.', false), ('B', 'Deberá remitirlo al órgano competente en el plazo de diez días, con su informe y una copia completa y ordenada del expediente.', true), ('C', 'Deberá devolverlo al interesado para que lo presente ante la Dirección General.', false), ('D', 'Deberá resolverlo ella misma, por haber dictado el acto.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 122.2 de la Ley 39/2015, el plazo máximo para dictar y notificar la resolución del recurso de alzada es de:', 'El art. 122.2 LPAC fija tres meses para resolver la alzada; pasado ese plazo puede entenderse desestimado, salvo el supuesto del art. 24.1, tercer párrafo.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 122.2 LPAC', 'El plazo máximo para dictar y notificar la resolución será de tres meses.', null, 'e2cc3a9ad0e3b3419c0f88166ab0c2e7a10b336fd53894f127a618ac6c8d7af5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e2cc3a9ad0e3b3419c0f88166ab0c2e7a10b336fd53894f127a618ac6c8d7af5')
  returning id
