  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres meses.', true), ('B', 'Un mes.', false), ('C', 'Dos meses.', false), ('D', 'Seis meses.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 119.3 de la Ley 39/2015, al resolver un recurso administrativo, el órgano competente:', 'El art. 119.3 LPAC permite resolver cuestiones no alegadas, previa audiencia, pero exige congruencia y prohíbe la reformatio in peius.', 'age_adm_33_procedimiento_revision', (select id from public.topics where slug = 'age-adm-33-procedimiento-revision'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 119.3 LPAC', 'El órgano que resuelva el recurso decidirá cuantas cuestiones, tanto de forma como de fondo, plantee el procedimiento, hayan sido o no alegadas por los interesados. En este último caso se les oirá previamente. No obstante, la resolución será congruente con las peticiones formuladas por el recurrente, sin que en ningún caso pueda agravarse su situación inicial.', null, '670a71eaa1144a54193dfc9c2572e71660e954f7ea77c28c13a91afba804fd8c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '670a71eaa1144a54193dfc9c2572e71660e954f7ea77c28c13a91afba804fd8c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo puede pronunciarse sobre las cuestiones expresamente alegadas por el recurrente.', false), ('B', 'Puede agravar la situación del recurrente si advierte nuevos incumplimientos.', false), ('C', 'Debe ordenar siempre la retroacción del procedimiento cuando aprecie cualquier vicio.', false), ('D', 'Decidirá todas las cuestiones de forma y de fondo que plantee el procedimiento, oyendo previamente a los interesados en las no alegadas, sin que en ningún caso pueda agravarse la situación inicial del recurrente.', true)) as v(label, body, ok)
)
