insert into public.topics (slug, title) values ('age-adm-44-situaciones-administrativas', 'IV.4 Situaciones administrativas de los funcionarios: supuestos y efectos (TREBEP y RD 365/1995)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-44-situaciones-administrativas' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del Reglamento de Situaciones Administrativas aprobado por el Real Decreto 365/1995, un funcionario de la Administración General del Estado que se encuentra en comisión de servicios está en situación de:', 'El art. 3.c) del RD 365/1995 incluye expresamente en el servicio activo a quienes se encuentren en comisión de servicios. La comisión no cambia la situación administrativa del funcionario.', 'age_adm_44_situaciones_administrativas', (select id from public.topics where slug = 'age-adm-44-situaciones-administrativas'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 3.c) RD 365/1995', 'Los funcionarios se hallan en situación de servicio activo: […] c) Cuando se encuentren en comisión de servicios.', null, '7d2ab504f8643e315381b1590a1b0a648abcf68c574ef1b045889905a639675f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7d2ab504f8643e315381b1590a1b0a648abcf68c574ef1b045889905a639675f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Servicios especiales.', false), ('B', 'Servicio en otras Administraciones Públicas.', false), ('C', 'Excedencia voluntaria por prestación de servicios en el sector público.', false), ('D', 'Servicio activo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Doña Elena cesa el 2 de marzo en su puesto de una Delegación del Gobierno porque ha obtenido otro puesto por concurso en un Ministerio, y aún no ha tomado posesión del nuevo. De acuerdo con el artículo 3 del Real Decreto 365/1995, durante el plazo posesorio se encuentra en situación de:', 'El art. 3.i) del RD 365/1995 considera en servicio activo a quienes cesan en un puesto por haber obtenido otro mediante procedimientos de provisión, durante el plazo posesorio.', 'age_adm_44_situaciones_administrativas', (select id from public.topics where slug = 'age-adm-44-situaciones-administrativas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 3.i) RD 365/1995', 'i) Cuando cesen en un puesto de trabajo por haber obtenido otro mediante procedimientos de provisión de puestos de trabajo, durante el plazo posesorio.', null, '27928db11d87d393fcd2fac9ed98a2c25f2795ab8fe9a70e0776d50c52a5bab5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '27928db11d87d393fcd2fac9ed98a2c25f2795ab8fe9a70e0776d50c52a5bab5')
  returning id
