  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 87.2 del TREBEP, quienes se encuentren en situación de servicios especiales percibirán:', 'El art. 87.2 del TREBEP fija que se cobra por el puesto o cargo efectivo, no como funcionario de carrera, pero se conserva el derecho a los trienios reconocidos.', 'age_adm_44_situaciones_administrativas', (select id from public.topics where slug = 'age-adm-44-situaciones-administrativas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 87.2 TREBEP', 'Quienes se encuentren en situación de servicios especiales percibirán las retribuciones del puesto o cargo que desempeñen y no las que les correspondan como funcionarios de carrera, sin perjuicio del derecho a percibir los trienios que tengan reconocidos en cada momento.', null, '3890bd453e4fda8d58499c2f0cae45d95754afa2c7145e7335e7ccdddbbaff57', false
