with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 89.4 del TREBEP, los funcionarios de carrera tienen derecho a un período de excedencia para atender al cuidado de cada hijo de duración:', 'El art. 89.4 del TREBEP limita la excedencia por cuidado de hijos a tres años por cada hijo, contados desde el nacimiento o la resolución judicial o administrativa.', 'age_adm_44_situaciones_administrativas', (select id from public.topics where slug = 'age-adm-44-situaciones-administrativas'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 89.4 TREBEP', 'Los funcionarios de carrera tendrán derecho a un período de excedencia de duración no superior a tres años para atender al cuidado de cada hijo', null, 'e3f70c666b211f280817e3eff3c71e661fb15ad2dac3d8360259d4fa03c085d8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e3f70c666b211f280817e3eff3c71e661fb15ad2dac3d8360259d4fa03c085d8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No superior a dos años, a contar desde la fecha de la solicitud.', false), ('B', 'No superior a cinco años, a contar desde la fecha de nacimiento.', false), ('C', 'No superior a tres años, a contar desde la fecha de nacimiento o, en su caso, de la resolución judicial o administrativa.', true), ('D', 'Indefinida, mientras el hijo sea menor de edad.', false)) as v(label, body, ok)
)
