with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Doña Marta lleva dos años y medio en excedencia por cuidado de su hija. Según el artículo 89.4 del TREBEP, ¿qué reserva de puesto le corresponde en este momento?', 'El art. 89.4 del TREBEP reserva el puesto desempeñado al menos durante dos años; después, la reserva es a un puesto en la misma localidad y de igual retribución.', 'age_adm_44_situaciones_administrativas', (select id from public.topics where slug = 'age-adm-44-situaciones-administrativas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 89.4 TREBEP', 'El puesto de trabajo desempeñado se reservará, al menos, durante dos años. Transcurrido este periodo, dicha reserva lo será a un puesto en la misma localidad y de igual retribución.', null, '09c8fab21bfc4f2515deecb6cdcc1534f45e6399b86f4555abe57cee4dd9b011', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '09c8fab21bfc4f2515deecb6cdcc1534f45e6399b86f4555abe57cee4dd9b011')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La reserva de un puesto en la misma localidad y de igual retribución, porque la reserva del puesto que desempeñaba se garantiza, al menos, durante dos años.', true), ('B', 'La reserva del mismo puesto que desempeñaba, que se mantiene durante los tres años.', false), ('C', 'Ninguna, porque la excedencia por cuidado de hijos no da derecho a reserva de puesto.', false), ('D', 'La reserva de un puesto en cualquier localidad del mismo Ministerio, sin garantía retributiva.', false)) as v(label, body, ok)
)
