with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La abuela de una funcionaria es hospitalizada. Según el artículo 48.a) del TREBEP, ¿de qué permiso dispone la funcionaria por este motivo?', 'La abuela es pariente de segundo grado por consanguinidad; el art. 48.a) concede cuatro días hábiles por hospitalización de un familiar de segundo grado (cinco si es cónyuge, pareja de hecho o pariente de primer grado).', 'age_adm_45_permisos_vacaciones', (select id from public.topics where slug = 'age-adm-45-permisos-vacaciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 48.a) TREBEP', 'Cuando se trate de accidente o enfermedad graves, hospitalización o intervención quirúrgica sin hospitalización que precise de reposo domiciliario, de un familiar dentro del segundo grado de consanguinidad o afinidad, el permiso será de cuatro días hábiles.', null, '5f8dcee63f93874fae070896e0421e50cb75e68f4110a986cf82268fd77ad717', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5f8dcee63f93874fae070896e0421e50cb75e68f4110a986cf82268fd77ad717')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinco días hábiles, por tratarse de un familiar de primer grado.', false), ('B', 'Cuatro días hábiles, por tratarse de un familiar dentro del segundo grado de consanguinidad.', true), ('C', 'Dos días hábiles, por tratarse de un familiar de segundo grado en la misma localidad.', false), ('D', 'Ninguno, porque el permiso solo cubre a familiares de primer grado.', false)) as v(label, body, ok)
)
