  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 48.f) del TREBEP, por lactancia de un hijo menor de doce meses el funcionario tiene derecho a:', 'El art. 48.f) reconoce una hora de ausencia divisible en dos fracciones, sustituible por una reducción de media hora al inicio y al final de la jornada o de una hora al inicio o al final.', 'age_adm_45_permisos_vacaciones', (select id from public.topics where slug = 'age-adm-45-permisos-vacaciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 48.f) TREBEP', 'f) Por lactancia de un hijo menor de doce meses tendrán derecho a una hora de ausencia del trabajo que podrá dividir en dos fracciones.', null, 'b1008b6623c3cae1b674647579caa0d1124e7eb54cbfdf6bb7c10bf63c4d7f2b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b1008b6623c3cae1b674647579caa0d1124e7eb54cbfdf6bb7c10bf63c4d7f2b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
