)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria quiere acumular en jornadas completas el tiempo del permiso de lactancia. Según el artículo 48.f) del TREBEP:', 'El art. 48.f) permite acumular la lactancia en jornadas completas a partir del fin del permiso por nacimiento, adopción, guarda, acogimiento o del progenitor diferente de la madre biológica, y lo configura como derecho individual intransferible.', 'age_adm_45_permisos_vacaciones', (select id from public.topics where slug = 'age-adm-45-permisos-vacaciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 48.f) TREBEP', 'El permiso contemplado en este apartado constituye un derecho individual de los funcionarios, sin que pueda transferirse su ejercicio al otro progenitor, adoptante, guardador o acogedor. Se podrá solicitar la sustitución del tiempo de lactancia por un permiso retribuido que acumule en jornadas completas el tiempo correspondiente. Esta modalidad se podrá disfrutar únicamente a partir de la finalización del permiso por nacimiento', null, 'f515149102cea728806b2ad2c97cbaba920e533381199e444eb6344cd7e02fbc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f515149102cea728806b2ad2c97cbaba920e533381199e444eb6344cd7e02fbc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Puede hacerlo en cualquier momento, incluso durante el permiso por nacimiento, y puede cederlo al otro progenitor.', false), ('B', 'No puede hacerlo, porque la lactancia solo admite la ausencia de una hora diaria.', false), ('C', 'Puede hacerlo solo si el otro progenitor renuncia expresamente a su propio permiso.', false), ('D', 'Puede hacerlo, pero esta modalidad solo se disfruta a partir de la finalización del permiso por nacimiento, y el permiso de lactancia no puede transferirse al otro progenitor.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
