  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El hijo de un funcionario nace prematuro y debe permanecer hospitalizado tras el parto. De acuerdo con el artículo 48.g) del TREBEP, el funcionario tiene derecho a ausentarse del trabajo:', 'El art. 48.g) concede hasta dos horas diarias de ausencia con retribuciones íntegras; además permite reducir la jornada hasta dos horas con disminución proporcional de retribuciones.', 'age_adm_45_permisos_vacaciones', (select id from public.topics where slug = 'age-adm-45-permisos-vacaciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 48.g) TREBEP', 'g) Por nacimiento de hijos prematuros o que por cualquier otra causa deban permanecer hospitalizados a continuación del parto, la funcionaria o el funcionario tendrá derecho a ausentarse del trabajo durante un máximo de dos horas diarias percibiendo las retribuciones íntegras.', null, '04d34cc0d795558f34f7aa004e45bd712efc84a5e3c6b0d502e8088ac14e5330', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '04d34cc0d795558f34f7aa004e45bd712efc84a5e3c6b0d502e8088ac14e5330')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Durante un máximo de dos horas diarias, percibiendo las retribuciones íntegras.', true), ('B', 'Durante un máximo de una hora diaria, con disminución proporcional de retribuciones.', false), ('C', 'Durante toda la jornada mientras dure la hospitalización, sin retribución.', false), ('D', 'Durante un máximo de dos horas diarias, con disminución proporcional de retribuciones.', false)) as v(label, body, ok)
)
