  select 'Un funcionario tiene el cuidado directo de su hija de nueve años y pide reducir su jornada. Según el artículo 48.h) del TREBEP:', 'El art. 48.h) reconoce la reducción de jornada por guarda legal de menores de doce años, personas mayores que requieran especial dedicación o personas con discapacidad sin actividad retribuida, con la disminución de retribuciones que corresponda.', 'age_adm_45_permisos_vacaciones', (select id from public.topics where slug = 'age-adm-45-permisos-vacaciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 48.h) TREBEP', 'h) Por razones de guarda legal, cuando el funcionario tenga el cuidado directo de algún menor de doce años, de persona mayor que requiera especial dedicación, o de una persona con discapacidad que no desempeñe actividad retribuida, tendrá derecho a la reducción de su jornada de trabajo, con la disminución de sus retribuciones que corresponda.', null, '753cd3a3d97357cf757006ace35e9b098f38a60c74511564f7471331e65a0f01', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '753cd3a3d97357cf757006ace35e9b098f38a60c74511564f7471331e65a0f01')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tiene derecho a la reducción de jornada sin disminución de retribuciones.', false), ('B', 'Tiene derecho a la reducción de jornada por guarda legal, con la disminución de retribuciones que corresponda.', true), ('C', 'No tiene derecho, porque la reducción por guarda legal solo alcanza a menores de seis años.', false), ('D', 'Solo tiene derecho si el otro progenitor no trabaja.', false)) as v(label, body, ok)
)
