with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 50.3 del TREBEP, el período de vacaciones anuales retribuidas de los funcionarios públicos:', 'El art. 50.3 prohíbe sustituir las vacaciones por dinero; solo cabe compensación económica cuando la relación de servicios termina por causas ajenas a la voluntad del funcionario (por ejemplo, jubilación por incapacidad permanente o fallecimiento).', 'age_adm_45_permisos_vacaciones', (select id from public.topics where slug = 'age-adm-45-permisos-vacaciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 50.3 TREBEP', 'El período de vacaciones anuales retribuidas de los funcionarios públicos no puede ser sustituido por una cuantía económica.', null, '291e0671908d4a62cca4ebf2b8acee1ccab5dfa6783ee7bca36659a1ec16a4bd', false
