with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El control horario muestra que un funcionario ha incumplido injustificadamente su jornada en un total de once horas durante el mes de marzo. De acuerdo con el artículo 7 del Real Decreto 33/1986, esta conducta constituye:', 'El art. 7.1.l) del RD 33/1986 tipifica como grave el incumplimiento injustificado de la jornada que, acumulado, suponga un mínimo de diez horas al mes; por debajo de ese umbral, el incumplimiento del horario es leve (art. 8.a).', 'age_adm_46_regimen_disciplinario', (select id from public.topics where slug = 'age-adm-46-regimen-disciplinario'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216'), 'Art. 7.1.l) RD 33/1986', 'l) El incumplimiento injustificado de la jornada de trabajo que acumulado suponga un mínimo de diez horas al mes.', null, '114c7ce0326ce4a5c40a6c925539eead8a3eac22976a14927b31795f21449d22', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '114c7ce0326ce4a5c40a6c925539eead8a3eac22976a14927b31795f21449d22')
