with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 16 del Real Decreto 33/1986, el funcionario sancionado con traslado con cambio de residencia por una falta grave no podrá obtener nuevo destino, por ningún procedimiento, en la localidad desde la que fue trasladado durante:', 'El art. 16 del RD 33/1986 fija la prohibición en tres años si la sanción es por falta muy grave y en un año si es por falta grave, contados desde que se efectuó el traslado.', 'age_adm_46_regimen_disciplinario', (select id from public.topics where slug = 'age-adm-46-regimen-disciplinario'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216'), 'Art. 16 RD 33/1986', 'Los funcionarios sancionados con traslado con cambio de residencia, no podrán obtener nuevo destino por ningún procedimiento en la localidad desde la que fueron trasladados, durante tres años, cuando hubiere sido impuesta por falta muy grave, y durante uno cuando hubiere correspondido a la comisión de una falta grave. Dicho plazo se computará desde el momento en que se efectuó el traslado.', null, '3054432dd223780a090c023974ab6fdb2dc95a59ab10c91c2d996dcb54b9eac2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3054432dd223780a090c023974ab6fdb2dc95a59ab10c91c2d996dcb54b9eac2')
