with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una trabajadora laboral fija obtuvo hace un año un puesto con carácter definitivo en un Ministerio y quiere participar en el concurso abierto y permanente para un puesto de otro Ministerio. Según el artículo 36.1 del IV Convenio único:', 'El art. 36.1 exige dos años en el último destino definitivo para participar, salvo que se pidan puestos de la misma Secretaría de Estado o del mismo Departamento u organismo.', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 36.1 IV Convenio único', 'Para poder participar en el concurso abierto y permanente el personal laboral fijo interesado deberá haber permanecido en el último puesto obtenido con carácter definitivo un mínimo de dos años, salvo en el caso que soliciten un puesto ubicado en la misma Secretaría de Estado en la que tenga su destino definitivo', null, '6b7a130dcd0bcd64c3b7f8618e553b3516b567333ae9de757570fedad79105ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6b7a130dcd0bcd64c3b7f8618e553b3516b567333ae9de757570fedad79105ce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Puede participar sin limitación, porque el concurso es abierto y permanente.', false), ('B', 'Puede participar, porque basta con haber superado el período de prueba.', false), ('C', 'No puede, porque debe haber permanecido un mínimo de dos años en el último puesto obtenido con carácter definitivo, salvo que solicite un puesto en la misma Secretaría de Estado o, en su defecto, en el mismo Departamento u organismo.', true), ('D', 'No puede, porque debe haber permanecido un mínimo de tres años en el último puesto.', false)) as v(label, body, ok)
)
