  select 'Por una necesidad imprevisible del servicio, la Subsecretaría encomienda a un trabajador del grupo E2 el desempeño de un puesto del grupo E1. De acuerdo con el artículo 48 del IV Convenio único:', 'En la encomienda de funciones de grupo inferior se mantiene la retribución de origen (art. 48.2) y la duración total no puede superar un mes en un año (art. 48.3). La movilidad nunca modifica el grupo profesional (art. 48.7).', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 48.2 y 48.3 IV Convenio único', 'salvo en los casos de encomienda de funciones de grupo inferior en los que mantendrán la retribución de origen. […] no pudiendo ser su duración en su totalidad superior a un mes en un período de un año.', null, '849d4520a61c5e92fe8077caa2afba892b34f052c3783f7add355ad8185c255d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '849d4520a61c5e92fe8077caa2afba892b34f052c3783f7add355ad8185c255d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Percibirá la retribución del puesto de grupo inferior durante un máximo de ocho meses.', false), ('B', 'Mantendrá su retribución de origen y la encomienda podrá durar hasta seis meses al año.', false), ('C', 'Mantendrá su retribución de origen y la encomienda no podrá superar en total un mes en un período de un año.', true), ('D', 'Pasará a integrarse en el grupo E1 si la encomienda dura más de un mes.', false)) as v(label, body, ok)
)
