with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una trabajadora laboral fija del IV Convenio único acaba de cumplir veinte años de servicios. Según el artículo 73.1 del Convenio, ¿cuántos días hábiles de vacaciones anuales le corresponden?', 'El art. 73.1 fija 22 días hábiles por año completo y los aumenta por antigüedad: 23 con quince años, 24 con veinte, 25 con veinticinco y 26 con treinta o más.', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 73.1 IV Convenio único', 'Veinte años de servicios: Veinticuatro días hábiles.', null, '8cc3d04d804dd779da34faa504660b8c1506e65831e9e83b6aa6939f8ac79def', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8cc3d04d804dd779da34faa504660b8c1506e65831e9e83b6aa6939f8ac79def')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Veintidós días hábiles.', false), ('B', 'Veintitrés días hábiles.', false), ('C', 'Veinticinco días hábiles.', false), ('D', 'Veinticuatro días hábiles.', true)) as v(label, body, ok)
)
