  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 75 del IV Convenio único, el personal laboral tiene derecho, por asuntos particulares, a:', 'El art. 75.o) reconoce hasta seis días al año por asuntos particulares (más días adicionales por trienios a partir del sexto); si no pueden disfrutarse por necesidades del servicio, se disfrutan antes del 31 de enero siguiente.', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 75.o) IV Convenio único', 'o) Hasta seis días cada año natural, por asuntos particulares no incluidos en los puntos anteriores.', null, '82cc5fff624c0578bfb481f6644a3e0c1192f1595417ae2922702b3059b2abe2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '82cc5fff624c0578bfb481f6644a3e0c1192f1595417ae2922702b3059b2abe2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
