with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 95.1 del IV Convenio único, la excedencia voluntaria por interés particular del personal laboral fijo requiere una antigüedad continuada e inmediatamente anterior de, al menos:', 'El art. 95.1 exige un año de antigüedad continuada en la AGE dentro del Convenio, fija una permanencia mínima de cuatro meses y una duración máxima indefinida. Para los funcionarios, el art. 89.2 TREBEP exige cinco años de servicios.', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 95.1 IV Convenio único', 'con, al menos, un año de antigüedad continuada e inmediatamente anterior a la fecha de la solicitud […] Una vez concedida, la duración mínima de permanencia en la misma es de cuatro meses y su duración máxima será indefinida.', null, 'c73d90c412d6de6054edc75e27b24f42fd8675407d7806e4ed2b3c0464663a46', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c73d90c412d6de6054edc75e27b24f42fd8675407d7806e4ed2b3c0464663a46')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
