with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 95.3 del IV Convenio único, en la excedencia voluntaria por agrupación familiar del personal laboral fijo:', 'El art. 95.3 permite la agrupación familiar sin tiempo mínimo de servicios, con permanencia mínima de dos años y duración máxima indefinida; no computa a efectos de antigüedad ni promoción.', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 95.3 IV Convenio único', 'Podrá concederse excedencia voluntaria por agrupación familiar sin el requisito de haber prestado un tiempo mínimo de servicios efectivos […] El tiempo mínimo de permanencia en dicha situación es de dos años y su duración máxima es indefinida.', null, 'cc39a88c4bd90097d7e39f6030a7cb425fe4f0696e5ee2a837e9d37d0ea5664e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cc39a88c4bd90097d7e39f6030a7cb425fe4f0696e5ee2a837e9d37d0ea5664e')
  returning id
), o as (
