with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes NO figura entre las sanciones que pueden imponerse al personal laboral según el artículo 105 del IV Convenio único?', 'El art. 105 prevé despido disciplinario, suspensión de empleo y sueldo, traslado forzoso, demérito y apercibimiento escrito. La separación del servicio es una sanción propia de los funcionarios.', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 105 IV Convenio único', 'Por la comisión de faltas disciplinarias se pueden imponer las siguientes sanciones: a) Despido disciplinario. b) Suspensión de empleo y sueldo. c) Traslado forzoso, con o sin cambio de localidad de residencia del trabajador o trabajadora, y sin derecho a indemnización. d) Demérito', null, '454ba055ffe06f8f426040a224be66e072ad7a9ea8a3c5a369cd2b820ccb07e3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '454ba055ffe06f8f426040a224be66e072ad7a9ea8a3c5a369cd2b820ccb07e3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La separación del servicio.', true), ('B', 'El despido disciplinario.', false), ('C', 'La suspensión de empleo y sueldo.', false), ('D', 'El demérito.', false)) as v(label, body, ok)
)
