with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 112.1 del IV Convenio único, las infracciones del personal laboral prescriben:', 'El art. 112.1 fija 3 años, 2 años y 6 meses, los mismos plazos que el art. 97 del TREBEP. Las sanciones prescriben a los 3 años, 2 años y 1 año (art. 112.3).', 'age_adm_48_convenio_unico', (select id from public.topics where slug = 'age-adm-48-convenio-unico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'Art. 112.1 IV Convenio único', 'Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses.', null, 'e9fd48fa993a0edb341d163f83131cf6929f90394a656a3e73666707ef59f333', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e9fd48fa993a0edb341d163f83131cf6929f90394a656a3e73666707ef59f333')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las muy graves a los seis años, las graves a los dos años y las leves al mes.', false), ('B', 'Las muy graves a los dos años, las graves al año y las leves a los tres meses.', false), ('C', 'Las muy graves a los tres años, las graves al año y las leves al mes.', false), ('D', 'Las muy graves a los tres años, las graves a los dos años y las leves a los seis meses.', true)) as v(label, body, ok)
)
