with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario viaja en comisión de servicios y se le abonan dietas. Según el código de la clasificación económica de los gastos (Resolución de 20 de enero de 2014 de la Dirección General de Presupuestos), ¿a qué concepto se imputan?', 'El capítulo 1 excluye expresamente las indemnizaciones por razón del servicio, que van al artículo 23 del capítulo 2: concepto 230 dietas, 231 locomoción, 232 traslado y 233 otras indemnizaciones.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-879'), 'Anexo IV, art. 23 (Resolución DGP 20/01/2014)', 'No se incluyen en este capítulo las indemnizaciones por razón del servicio. […] Artículo 23. Indemnizaciones por razón del servicio. […] Concepto 230. Dietas.', null, '5ee0e3f914878abb68e30feb92e722f5ca0e0e3dc151087822111be70f90d067', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5ee0e3f914878abb68e30feb92e722f5ca0e0e3dc151087822111be70f90d067')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al concepto 121 «Retribuciones complementarias», del capítulo 1.', false), ('B', 'Al concepto 162 «Gastos sociales del personal», del capítulo 1.', false), ('C', 'Al concepto 230 «Dietas», del artículo 23 «Indemnizaciones por razón del servicio» del capítulo 2.', true), ('D', 'Al concepto 226 «Gastos diversos», del capítulo 2.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
