with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Ministerio adjudica a una empresa externa el servicio de limpieza de su sede. Según el código de la clasificación económica de los gastos, ¿dónde se imputa el gasto?', 'El concepto 227 recoge las actividades que, siendo competencia del organismo, se ejecutan mediante contrato con empresas externas o profesionales; la limpieza es el subconcepto 00 y la seguridad el 01.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-879'), 'Anexo IV, concepto 227 (Resolución DGP 20/01/2014)', 'Concepto 227. Trabajos realizados por otras empresas y profesionales Se incluirán aquellos gastos que correspondan a actividades que siendo de la competencia de los organismos públicos se ejecuten mediante contrato con empresas externas o profesionales independientes. • Subconcepto 00. Limpieza y aseo.', null, 'a8f73adbb8c08ca19fad65f566c02f2f8bf6adab430c50d438d8a69c8feb6d7c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a8f73adbb8c08ca19fad65f566c02f2f8bf6adab430c50d438d8a69c8feb6d7c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el concepto 212 «Edificios y otras construcciones», de reparaciones, mantenimiento y conservación.', false), ('B', 'En el subconcepto 227.00 «Limpieza y aseo», del concepto 227 «Trabajos realizados por otras empresas y profesionales».', true), ('C', 'En el concepto 620 «Inversión nueva asociada al funcionamiento operativo de los servicios».', false), ('D', 'En el subconcepto 226.99 «Otros» de gastos diversos.', false)) as v(label, body, ok)
)
