with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la nómina de una funcionaria del Cuerpo General Administrativo (subgrupo C1), ¿a qué subconcepto de la clasificación económica se imputa su sueldo?', 'El concepto 120 «Retribuciones básicas» del artículo 12 «Funcionarios» abre un subconcepto por grupo: 00 A1, 01 A2, 02 C1, 03 C2 y 04 agrupaciones profesionales; los trienios van al 05 y las pagas extraordinarias al 06.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-879'), 'Anexo IV, concepto 120 (Resolución DGP 20/01/2014)', 'Concepto 120. Retribuciones básicas. […] • Subconcepto 02. Sueldos del grupo C1 y grupo C.', 'La Resolución de 2014 advierte que las órdenes anuales de elaboración de los PGE pueden actualizar tácitamente la clasificación económica; conviene contrastar los códigos con la orden vigente.', '8e7b68acb15a5634b68c8572db856fb902fd0c7706881ef81b963544487b2f0d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8e7b68acb15a5634b68c8572db856fb902fd0c7706881ef81b963544487b2f0d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al subconcepto 120.05 «Trienios».', false), ('B', 'Al subconcepto 121.00 «Complemento de destino».', false), ('C', 'Al subconcepto 130.00 «Retribuciones básicas» del personal laboral fijo.', false), ('D', 'Al subconcepto 120.02 «Sueldos del grupo C1 y grupo C».', true)) as v(label, body, ok)
)
