with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 40.1.c) de la Ley 47/2003, General Presupuestaria, ¿cuál de los siguientes créditos NO forma parte de los créditos para operaciones corrientes?', 'El art. 40.1.c) LGP distingue en operaciones corrientes los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes; las inversiones reales son operaciones de capital, junto con las transferencias de capital.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 40.1.c) LGP', 'En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital.', null, 'b9ad32aad7f0d71efe1b7b02355e91001845eda70386bc3caa207989a813d7aa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b9ad32aad7f0d71efe1b7b02355e91001845eda70386bc3caa207989a813d7aa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los gastos de personal.', false), ('B', 'Los gastos financieros.', false), ('C', 'Las inversiones reales.', true), ('D', 'Las transferencias corrientes.', false)) as v(label, body, ok)
)
