with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 40.1.c) de la Ley General Presupuestaria, en la clasificación económica del gasto los capítulos se desglosan en:', 'El art. 40.1.c) LGP fija la jerarquía de la clasificación económica: capítulo, artículo, concepto y subconcepto. Secciones y servicios son la clasificación orgánica; los programas, la clasificación por programas.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 40.1.c) LGP', 'Los capítulos se desglosarán en artículos y estos, a su vez, en conceptos que podrán dividirse en subconceptos.', null, 'b0a9ab9851a07ccc009f1061626f52af6bf2a7e531e7463f75cc4a7ff3a4866d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b0a9ab9851a07ccc009f1061626f52af6bf2a7e531e7463f75cc4a7ff3a4866d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Secciones, y estas en servicios.', false), ('B', 'Artículos, y estos, a su vez, en conceptos que podrán dividirse en subconceptos.', true), ('C', 'Programas, y estos en subprogramas.', false), ('D', 'Conceptos, y estos en partidas que podrán dividirse en artículos.', false)) as v(label, body, ok)
)
