with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 42 de la Ley General Presupuestaria, los créditos para gastos se destinarán exclusivamente:', 'El art. 42 LGP recoge el principio de especialidad cualitativa: cada crédito solo puede destinarse a la finalidad autorizada o a la que resulte de una modificación aprobada conforme a la LGP.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 42 LGP', 'Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley.', null, '6f7caa92e3c8db38882e19f107375a388c3d544f572bab25cef7606fe20a5eee', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6f7caa92e3c8db38882e19f107375a388c3d544f572bab25cef7606fe20a5eee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esa ley.', true), ('B', 'A la finalidad que determine en cada momento el centro gestor, dentro de su sección presupuestaria.', false), ('C', 'A cualquier gasto del mismo capítulo, aunque sea de distinto programa.', false), ('D', 'A la finalidad que autorice el Interventor Delegado del departamento.', false)) as v(label, body, ok)
)
