with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 43.2 de la Ley General Presupuestaria, en el presupuesto del Estado se especificarán al nivel que corresponda conforme a su concreta clasificación económica, entre otros, los créditos destinados a:', 'El art. 43.2 LGP exceptúa de la regla general de vinculación (concepto, artículo o capítulo según el tipo de gasto) a ciertos créditos, como las atenciones protocolarias y representativas, los gastos reservados, los arrendamientos de edificios, los ampliables y los extraordinarios.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 43.2 LGP', 'No obstante, se especificarán al nivel que corresponda conforme a su concreta clasificación económica, los siguientes créditos: a) Los destinados a atenciones protocolarias y representativas y los gastos reservados.', null, 'b2fb63935429176390099e727c573e4cd4d817ffd9521c5439a835e5a41ed227', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b2fb63935429176390099e727c573e4cd4d817ffd9521c5439a835e5a41ed227')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Gastos de personal funcionario.', false), ('B', 'Material de oficina no inventariable.', false), ('C', 'Inversiones de reposición asociadas al funcionamiento de los servicios.', false), ('D', 'Atenciones protocolarias y representativas y gastos reservados.', true)) as v(label, body, ok)
)
