with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Subsecretaría de un Ministerio pretende financiar un gasto con una transferencia de crédito procedente de un crédito de otro Ministerio, sin que medie reorganización administrativa ni convenio. Según el artículo 52.1 de la Ley General Presupuestaria:', 'El art. 52.1.b) LGP prohíbe las transferencias entre distintas secciones presupuestarias (salvo el programa de contratación centralizada y los casos del art. 52.2, como reorganizaciones o convenios).', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 52.1.b) LGP', 'b) No podrán realizarse entre créditos de distintas secciones presupuestarias. Esta restricción no afectará a los créditos del programa de contratación centralizada.', null, 'a1dd2a776a12f4cea694c4aaee696e48bb765c93ff5c3e97d4e59a295f8d8a11', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a1dd2a776a12f4cea694c4aaee696e48bb765c93ff5c3e97d4e59a295f8d8a11')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es posible si ambos créditos son del mismo capítulo.', false), ('B', 'No es posible, porque las transferencias no podrán realizarse entre créditos de distintas secciones presupuestarias.', true), ('C', 'Es posible con autorización del Ministro de Hacienda, sin más requisitos.', false), ('D', 'Es posible si el crédito de origen es de operaciones de capital y el de destino de operaciones corrientes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En mayo se aprobó un suplemento de crédito en el concepto 227 de un servicio. En octubre, el mismo servicio quiere dar de baja parte de ese crédito para financiar una transferencia a otro concepto. De acuerdo con el artículo 52.1 de la Ley General Presupuestaria:', 'El art. 52.1.c) LGP impide que las transferencias minoren créditos extraordinarios o créditos suplementados o ampliados en el ejercicio (con las salvedades de la Seguridad Social y de la sección 06).', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 52.1.c) LGP', 'c) No minorarán créditos extraordinarios o créditos que se hayan suplementado o ampliado en el ejercicio.', null, 'b19d3e025a373888b1c30fc77378e1e64cfdbc0fa11a9500f7a838351c12d686', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b19d3e025a373888b1c30fc77378e1e64cfdbc0fa11a9500f7a838351c12d686')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es posible, porque las transferencias no minorarán créditos que se hayan suplementado en el ejercicio.', true), ('B', 'Es posible, porque se trata del mismo servicio presupuestario.', false), ('C', 'Es posible siempre que el crédito de destino sea de operaciones corrientes.', false), ('D', 'Es posible solo si lo autoriza el Consejo de Ministros.', false)) as v(label, body, ok)
)
