with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 52.3 de la Ley General Presupuestaria, las transferencias de crédito destinadas a crear o aumentar subvenciones nominativas:', 'El art. 52.3 LGP prohíbe, con carácter general, crear o aumentar subvenciones nominativas mediante transferencias, salvo que se ajusten a la LGS o se destinen a otros entes del sector público.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 52.3 LGP', 'En ningún caso las transferencias podrán crear créditos destinados a subvenciones nominativas o aumentar los ya existentes salvo que sean conformes con lo dispuesto en la Ley General de Subvenciones o se trate de subvenciones o aportaciones a otros entes del sector público.', null, 'de3087d2ef52f4df966d0ae660b189a42b4167a55df2a4b4b3b3442e477004a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'de3087d2ef52f4df966d0ae660b189a42b4167a55df2a4b4b3b3442e477004a5')
  returning id
), o as (
