with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Ministerio debe atender en este ejercicio un gasto corriente inaplazable para el que no existe crédito en su presupuesto, y no cabe atenderlo con transferencia, generación ni ampliación. Según el artículo 55.1 de la Ley General Presupuestaria, procede tramitar:', 'Si no existe crédito adecuado se tramita un crédito extraordinario (si es insuficiente, un suplemento). Para operaciones no financieras se financia con el Fondo de Contingencia u otros créditos no financieros; la Deuda Pública se reserva a las operaciones financieras (art. 55.1 LGP).', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 55.1 LGP', 'a) Si la necesidad surgiera en operaciones no financieras del presupuesto, el crédito extraordinario o suplementario se financiará mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados.', null, '9a0803e84c051b15b8cf089a65c784cb57fddf8042c30a7e163f18004348508b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9a0803e84c051b15b8cf089a65c784cb57fddf8042c30a7e163f18004348508b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un suplemento de crédito, financiado con Deuda Pública.', false), ('B', 'Un crédito extraordinario, financiado mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados.', true), ('C', 'Un crédito extraordinario, financiado con Deuda Pública o con baja en créditos de operaciones financieras.', false), ('D', 'Una incorporación de crédito, financiada con el remanente de tesorería.', false)) as v(label, body, ok)
)
