  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el concepto 221 «Suministros», subconcepto «Productos farmacéuticos y material sanitario», del capítulo 2.', false), ('B', 'En el concepto 162 «Gastos sociales del personal» (subconcepto 09 «Otros»), del capítulo 1.', true), ('C', 'En el concepto 227 «Trabajos realizados por otras empresas y profesionales», subconcepto «Estudios y trabajos técnicos».', false), ('D', 'En el capítulo 4 «Transferencias corrientes», artículo 48 «A familias e instituciones sin fines de lucro».', false)) as v(label, body, ok)
)
