  select 'Una Dirección General quiere dar de baja crédito del capítulo 6 «Inversiones reales» para reforzar el capítulo 2 «Gastos corrientes en bienes y servicios» del mismo programa. Según el artículo 52.1 de la Ley General Presupuestaria:', 'El art. 52.1.a) LGP prohíbe las transferencias desde operaciones financieras al resto y desde operaciones de capital a operaciones corrientes; la operación inversa (de corrientes a capital) sí es posible.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 52.1.a) LGP', 'a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes.', null, '04957cc45ae40a85242521e481ff06530c75c195d8afb5c34614a28da6d99cd0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '04957cc45ae40a85242521e481ff06530c75c195d8afb5c34614a28da6d99cd0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es posible, porque ambos créditos pertenecen al mismo programa.', false), ('B', 'Es posible con autorización del titular del departamento, previo informe de la Intervención Delegada.', false), ('C', 'No es posible, porque las transferencias no pueden realizarse desde créditos para operaciones de capital a créditos para operaciones corrientes.', true), ('D', 'Es posible solo si el importe no supera el 10 % del crédito inicial.', false)) as v(label, body, ok)
