with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A una ciudadana se le notifica una orden ministerial expresa que pone fin a la vía administrativa y decide no interponer recurso de reposición. Según el artículo 46.1 de la Ley 29/1998, el plazo para interponer recurso contencioso-administrativo es de:', 'El art. 46.1 LJCA fija dos meses para recurrir actos expresos que ponen fin a la vía administrativa; seis meses si el acto es presunto.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 46.1 LJCA', 'El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.', null, '5f5fc72dc0b10b03995e82d452ddf6640d5e865b8dabacd4455bafde28d7060f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5f5fc72dc0b10b03995e82d452ddf6640d5e865b8dabacd4455bafde28d7060f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes, contado desde el día siguiente al de la notificación.', false), ('B', 'Seis meses, contados desde la fecha de la orden.', false), ('C', 'Tres meses, contados desde el día de la notificación.', false), ('D', 'Dos meses, contados desde el día siguiente al de la notificación.', true)) as v(label, body, ok)
)
