insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-60-supuesto-practico' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Doña Rosa solicita a una Confederación Hidrográfica una autorización sin aportar un plano preceptivo. El viernes 2 de octubre de 2026 se le notifica el requerimiento de subsanación del artículo 68.1 de la Ley 39/2015. Teniendo en cuenta que el lunes 12 de octubre es fiesta nacional y que no hay otros festivos, ¿cuál es el último día del plazo?', 'El plazo de subsanación es de diez días (art. 68.1 LPAC) y son hábiles (art. 30.2): se cuentan desde el lunes 5 de octubre, excluyendo sábados, domingos y el festivo del 12. Días: 5, 6, 7, 8, 9, 13, 14, 15, 16 y 19 de octubre.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Arts. 68.1 y 30.2 LPAC', 'se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición', null, '990959185c6d6de8c969f5f0eb5629410d985da3639590fac903c2a8fa391f48', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '990959185c6d6de8c969f5f0eb5629410d985da3639590fac903c2a8fa391f48')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El viernes 16 de octubre de 2026.', false), ('B', 'El lunes 19 de octubre de 2026.', true), ('C', 'El lunes 12 de octubre de 2026.', false), ('D', 'El martes 20 de octubre de 2026.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el caso de la solicitud de autorización a la Confederación Hidrográfica, doña Rosa deja pasar el plazo de subsanación sin aportar el plano. Según el artículo 68.1 de la Ley 39/2015, ¿qué consecuencia tiene?', 'El art. 68.1 LPAC advierte de que, si no se subsana, se tiene al interesado por desistido, mediante resolución que declara esa circunstancia (art. 21.1).', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 68.1 LPAC', 'con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.', null, '86be8897d296faebf60a4ec22d7b79671c79a61c42be037de798000efe8f561a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '86be8897d296faebf60a4ec22d7b79671c79a61c42be037de798000efe8f561a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Su solicitud se entenderá estimada por silencio administrativo.', false), ('B', 'La Confederación continuará el procedimiento y resolverá con la documentación disponible.', false), ('C', 'Se le tendrá por desistida de su petición, previa resolución que deberá dictarse en los términos del artículo 21.', true), ('D', 'Se le impondrá una sanción por falta de colaboración con la Administración.', false)) as v(label, body, ok)
)
