select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Subdirector General dicta una resolución desfavorable a un ciudadano, que no pone fin a la vía administrativa. De acuerdo con los artículos 121 y 122 de la Ley 39/2015, el interesado podrá interponer:', 'Los actos que no ponen fin a la vía administrativa se recurren en alzada ante el superior jerárquico (art. 121.1 LPAC), en el plazo de un mes si el acto es expreso (art. 122.1).', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Arts. 121.1 y 122.1 LPAC', 'Las resoluciones y actos a que se refiere el artículo 112.1, cuando no pongan fin a la vía administrativa, podrán ser recurridos en alzada ante el órgano superior jerárquico del que los dictó. […] El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso.', null, '429eb093377c166a1d92bcb19b8945d65211f6cd97483d9b42356fad2d5d8a4c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '429eb093377c166a1d92bcb19b8945d65211f6cd97483d9b42356fad2d5d8a4c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Recurso de alzada ante el órgano superior jerárquico del que dictó el acto, en el plazo de un mes.', true), ('B', 'Recurso potestativo de reposición ante el mismo Subdirector General, en el plazo de un mes.', false), ('C', 'Recurso contencioso-administrativo directamente, en el plazo de dos meses.', false), ('D', 'Recurso extraordinario de revisión, en el plazo de tres meses.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Directora General de un Ministerio, en ejercicio de sus competencias en materia de personal, deniega a un funcionario una reducción de jornada. Según los artículos 114.2 y 123.1 de la Ley 39/2015, frente a esa resolución el funcionario podrá:', 'En el ámbito estatal ponen fin a la vía administrativa los actos de los órganos directivos con nivel de Director general o superior en materia de personal (art. 114.2.c); contra ellos cabe reposición potestativa o contencioso (art. 123.1).', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Arts. 114.2.c) y 123.1 LPAC', 'c) Los emanados de los órganos directivos con nivel de Director general o superior, en relación con las competencias que tengan atribuidas en materia de personal. […] Los actos administrativos que pongan fin a la vía administrativa podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo.', null, 'ded6dd11f069871af7551b73442924b827be0fdb7335d5d454976ece1c46a518', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ded6dd11f069871af7551b73442924b827be0fdb7335d5d454976ece1c46a518')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Interponer únicamente recurso de alzada ante el Subsecretario.', false), ('B', 'Interponer recurso de alzada ante el Ministro y, después, recurso de reposición.', false), ('C', 'Interponer recurso extraordinario de revisión ante el Consejo de Ministros.', false), ('D', 'Interponer potestativamente recurso de reposición ante la misma Directora General o acudir directamente a la vía contencioso-administrativa.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una empresa presentó una solicitud ante una Dirección General; ha vencido el plazo máximo para resolver sin notificación y, por norma con rango de ley, el silencio es desestimatorio. Según el artículo 122.1 de la Ley 39/2015, ¿cuándo puede interponer recurso de alzada?', 'Si el acto no es expreso, el art. 122.1 LPAC permite interponer la alzada en cualquier momento desde el día siguiente a la producción de los efectos del silencio.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 122.1 LPAC', 'Si el acto no fuera expreso el solicitante y otros posibles interesados podrán interponer recurso de alzada en cualquier momento a partir del día siguiente a aquel en que, de acuerdo con su normativa específica, se produzcan los efectos del silencio administrativo.', null, '8f54ccd51cd63a9b32bf54b282f942515259ed152f2905d560ab31bf08320058', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8f54ccd51cd63a9b32bf54b282f942515259ed152f2905d560ab31bf08320058')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo de un mes desde el vencimiento del plazo para resolver.', false), ('B', 'En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio administrativo.', true), ('C', 'En el plazo de tres meses desde la presentación de la solicitud.', false), ('D', 'Solo cuando la Administración dicte resolución expresa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ciudadano titula su escrito «recurso de reposición» contra un acto de un Subdirector General que no pone fin a la vía administrativa. De acuerdo con el artículo 115.2 de la Ley 39/2015:', 'El art. 115.2 LPAC establece que el error o la ausencia de calificación del recurso no impide tramitarlo si se deduce su verdadero carácter.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 115.2 LPAC', 'El error o la ausencia de la calificación del recurso por parte del recurrente no será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter.', null, '4807c9f4abc080850de911e464fde31c7439b47ffb8fd7a2a316c7da16a288c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4807c9f4abc080850de911e464fde31c7439b47ffb8fd7a2a316c7da16a288c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El error en la calificación no impide su tramitación, siempre que se deduzca su verdadero carácter, por lo que se tramitará como recurso de alzada.', true), ('B', 'Debe inadmitirse, porque el recurso de reposición solo cabe contra actos que ponen fin a la vía administrativa.', false), ('C', 'Debe tramitarse como recurso de reposición y resolverlo el propio Subdirector General.', false), ('D', 'Debe devolverse al ciudadano para que lo califique correctamente en el plazo de diez días.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un interesado dirige a un Ministerio un recurso de alzada contra un acto dictado por una consejería de una comunidad autónoma. Según el artículo 116 de la Ley 39/2015:', 'El art. 116.a) LPAC considera causa de inadmisión que el órgano sea incompetente cuando el competente pertenezca a otra Administración, pero obliga a remitir el recurso al órgano competente (art. 14.1 LRJSP).', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 116.a) LPAC', 'a) Ser incompetente el órgano administrativo, cuando el competente perteneciera a otra Administración Pública. El recurso deberá remitirse al órgano competente', null, 'd54199b1412db0dcb5053fb1a8c807ffa2731d78e064b0e1e7b2465f4bd7579c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd54199b1412db0dcb5053fb1a8c807ffa2731d78e064b0e1e7b2465f4bd7579c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministerio deberá resolverlo, porque el recurso de alzada puede presentarse ante cualquier Administración.', false), ('B', 'Es causa de inadmisión, y el Ministerio debe archivarlo sin más trámite.', false), ('C', 'Es causa de inadmisión por incompetencia del órgano, y el recurso deberá remitirse al órgano competente.', true), ('D', 'El Ministerio debe suspender el acto y requerir a la comunidad autónoma el expediente.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un interesado interpone recurso de alzada y pide en él la suspensión de la ejecución del acto. Ha pasado un mes desde que la solicitud de suspensión entró en el registro electrónico del órgano competente para resolver, sin que se haya dictado y notificado resolución sobre ella. Según el artículo 117.3 de la Ley 39/2015:', 'El art. 117.3 LPAC establece un silencio positivo específico: si en un mes no se resuelve la solicitud de suspensión, la ejecución se entiende suspendida.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 117.3 LPAC', 'La ejecución del acto impugnado se entenderá suspendida si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico de la Administración u Organismo competente para decidir sobre la misma, el órgano a quien competa resolver el recurso no ha dictado y notificado resolución expresa al respecto.', null, 'fbfb628f557756200f5d74bdf329802b14cb40353778e6742eb12f40c966a782', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fbfb628f557756200f5d74bdf329802b14cb40353778e6742eb12f40c966a782')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La solicitud de suspensión se entenderá desestimada.', false), ('B', 'El recurso de alzada se entenderá estimado.', false), ('C', 'El interesado deberá esperar a que transcurran tres meses para entender suspendido el acto.', false), ('D', 'La ejecución del acto impugnado se entenderá suspendida.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario interpone recurso potestativo de reposición contra una resolución del Subsecretario que pone fin a la vía administrativa y, a los pocos días, quiere presentar también recurso contencioso-administrativo. Según el artículo 123.2 de la Ley 39/2015:', 'El art. 123.2 LPAC impide acudir al contencioso mientras no se resuelva la reposición o se produzca su desestimación presunta (un mes, art. 124.2).', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 123.2 LPAC', 'No se podrá interponer recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido la desestimación presunta del recurso de reposición interpuesto.', null, '3720ebfd678f9eeb243fce0a9ec86ff2b04eeeabb7b439bbbe82fdb6c7f3495e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3720ebfd678f9eeb243fce0a9ec86ff2b04eeeabb7b439bbbe82fdb6c7f3495e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrá interponerlo hasta que la reposición se resuelva expresamente o se produzca su desestimación presunta.', true), ('B', 'Puede interponerlo de inmediato, porque ambos recursos son compatibles.', false), ('C', 'Debe desistir primero de la reposición, sin más requisitos.', false), ('D', 'Puede interponerlo solo si han pasado diez días desde la reposición.', false)) as v(label, body, ok)
)
