insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-60-supuesto-practico' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Don Javier, funcionario del Cuerpo General Administrativo, supera unas oposiciones a un cuerpo de funcionarios de una comunidad autónoma, toma posesión y pasa a servicio activo en ese nuevo cuerpo sin obtener compatibilidad. Según el artículo 15 del Real Decreto 365/1995, en el Cuerpo General Administrativo será declarado en:', 'El art. 15.1 del RD 365/1995 declara en esta excedencia a los funcionarios de carrera que estén en servicio activo en otro cuerpo o escala de cualquier Administración, salvo que hayan obtenido la compatibilidad. El servicio en otras Administraciones es para quien obtiene destino por transferencia o provisión de puestos.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 15.1 RD 365/1995', 'Procederá declarar, de oficio o a instancia de parte, en la situación regulada en este artículo a los funcionarios de carrera que se encuentren en servicio activo en otro cuerpo o escala de cualquiera de las Administraciones públicas, salvo que hubieran obtenido la oportuna compatibilidad', null, '0ea196a92795e3deb5b4f7302047161909d8db8f905afe687b189717222410bc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0ea196a92795e3deb5b4f7302047161909d8db8f905afe687b189717222410bc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Servicio en otras Administraciones Públicas.', false), ('B', 'Excedencia voluntaria por interés particular.', false), ('C', 'Excedencia voluntaria por prestación de servicios en el sector público.', true), ('D', 'Servicios especiales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria es Senadora y se encuentra en servicios especiales. Las Cortes Generales se disuelven por convocatoria de elecciones y ella no se presenta. De acuerdo con el artículo 9.2 del Real Decreto 365/1995:', 'El art. 9.2 del RD 365/1995 (y el art. 87.1.e del TREBEP) permite a los parlamentarios que pierden la condición por disolución o fin del mandato seguir en servicios especiales hasta la nueva constitución de las Cámaras.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 9.2 RD 365/1995', 'Los Diputados, Senadores, miembros de las Asambleas Legislativas de las Comunidades Autónomas o del Parlamento Europeo que pierdan dicha condición por disolución de las correspondientes Cámaras o terminación del mandato de las mismas podrán permanecer en situación de servicios especiales hasta su nueva constitución.', null, 'b68b2ec773c15106383886e727c3353bb068e9a9cbd6fca0fb76072af6c704ac', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b68b2ec773c15106383886e727c3353bb068e9a9cbd6fca0fb76072af6c704ac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrá permanecer en situación de servicios especiales hasta la nueva constitución de las Cámaras.', true), ('B', 'Debe solicitar el reingreso al servicio activo el mismo día de la disolución.', false), ('C', 'Pasa automáticamente a excedencia voluntaria por interés particular.', false), ('D', 'Pasa a la situación de expectativa de destino.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario que perdió su puesto por una suspensión firme de dos años solicita en plazo el reingreso al servicio activo, pero transcurren seis meses sin que se le conceda. Según el artículo 22.5 del Real Decreto 365/1995:', 'El art. 22.5 del RD 365/1995 protege al funcionario que pide el reingreso a tiempo: si no se le concede en seis meses, pasa de oficio a excedencia forzosa (con derecho a retribuciones básicas, art. 13.6), con efectos desde la extinción de la responsabilidad.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 22.5 RD 365/1995', 'Si una vez solicitado el reingreso al servicio activo no se concede en el plazo de seis meses, el funcionario será declarado, de oficio, en la situación de excedencia forzosa prevista en el artículo 13.1.b) con efectos de la fecha de extinción de la responsabilidad penal o disciplinaria.', 'La excedencia forzosa no figura en el art. 85.1 del TREBEP; se mantiene en la AGE por el RD 365/1995 al amparo del art. 85.2. Conviene confirmar que se sigue aplicando así.', 'a88f28ee221aed2774d2f45de89a6dc884eae4ada6be1999ce91facee83cb9b7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a88f28ee221aed2774d2f45de89a6dc884eae4ada6be1999ce91facee83cb9b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Será declarado de oficio en excedencia voluntaria por interés particular.', false), ('B', 'Se entenderá reingresado por silencio administrativo en su antiguo puesto.', false), ('C', 'Será declarado de oficio en excedencia forzosa, con efectos de la fecha de extinción de la responsabilidad disciplinaria.', true), ('D', 'Permanecerá en suspensión de funciones hasta que se le asigne puesto.', false)) as v(label, body, ok)
)
