with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario de una Delegación del Gobierno quiere dejar temporalmente de trabajar para cuidar a su madre, que por razón de edad no puede valerse por sí misma y no tiene actividad retribuida. Según el artículo 89.4 del TREBEP, puede solicitar:', 'El art. 89.4 del TREBEP reconoce una excedencia de hasta tres años para cuidar a un familiar a cargo hasta el segundo grado que no pueda valerse por sí mismo y no desempeñe actividad retribuida.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 89.4 TREBEP', 'También tendrán derecho a un período de excedencia de duración no superior a tres años, para atender al cuidado de un familiar que se encuentre a su cargo, hasta el segundo grado inclusive de consanguinidad o afinidad que por razones de edad, accidente, enfermedad o discapacidad no pueda valerse por sí mismo y no desempeñe actividad retribuida.', null, 'c881e594b46c72c810fbe805596753f67a5782dd53785f29e38adb2a2235d503', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c881e594b46c72c810fbe805596753f67a5782dd53785f29e38adb2a2235d503')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una excedencia voluntaria por agrupación familiar de dos años como mínimo.', false), ('B', 'Una excedencia por cuidado de familiares de duración no superior a tres años.', true), ('C', 'Un permiso retribuido de hasta un mes.', false), ('D', 'Una situación de servicios especiales.', false)) as v(label, body, ok)
)
