with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria del Cuerpo General Administrativo es nombrada alto cargo de la Administración General del Estado. Según el artículo 87.1 del TREBEP, pasará a la situación de:', 'El art. 87.1.a) del TREBEP declara en servicios especiales a quienes sean nombrados altos cargos de las Administraciones Públicas.', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 87.1.a) TREBEP', 'a) Cuando sean designados miembros del Gobierno o de los órganos de gobierno de las comunidades autónomas y ciudades de Ceuta y Melilla, miembros de las Instituciones de la Unión Europea o de las organizaciones internacionales, o sean nombrados altos cargos de las citadas Administraciones Públicas o Instituciones.', null, '98b7e190700e9512ed07efefc0ca6628132ebeb326a5461feaf3723503a589c1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '98b7e190700e9512ed07efefc0ca6628132ebeb326a5461feaf3723503a589c1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Servicios especiales.', true), ('B', 'Servicio activo, con reserva de su puesto.', false), ('C', 'Excedencia voluntaria por interés particular.', false), ('D', 'Servicio en otras Administraciones Públicas.', false)) as v(label, body, ok)
)
