with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 76 del Real Decreto 364/1995, para participar en pruebas de promoción interna los funcionarios deberán tener una antigüedad en el Cuerpo o Escala a que pertenezcan de, al menos:', 'El art. 76 del Reglamento aprobado por el RD 364/1995 exige una antigüedad de al menos dos años en el Cuerpo o Escala de pertenencia, referida al día en que termina el plazo de presentación de solicitudes, además de la titulación y los demás requisitos generales del Cuerpo al que se aspira.', 'age_aux_b1_13_funcion_publica', (select id from public.topics where slug = 'age-aux-b1-13-funcion-publica'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 76 RD 364/1995', 'Para participar en pruebas de promoción interna los funcionarios deberán tener una antigüedad de, al menos, dos años en el Cuerpo o Escala a que pertenezcan el día de la finalización del plazo de presentación de solicitudes de participación', null, '28987ce855ea9a4481d469035d57ec628f19304cccabfcfa7443463b016ce9e9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '28987ce855ea9a4481d469035d57ec628f19304cccabfcfa7443463b016ce9e9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres años, el día de la publicación de la convocatoria.', false), ('B', 'Un año, el día de la finalización del plazo de presentación de solicitudes.', false), ('C', 'Dos años, el día de la finalización del plazo de presentación de solicitudes.', true), ('D', 'Dos años, el día de la toma de posesión en el nuevo Cuerpo o Escala.', false)) as v(label, body, ok)
)
