  select 'De acuerdo con el Reglamento del Registro Central de Personal, el número de identificación personal que asigna el Registro a los ciudadanos españoles:', 'El art. 9.1 lo basa en el DNI y lo mantiene durante toda la vida administrativa. Lo que se multiplica con cada nombramiento o contrato es el número de registro de personal (art. 8.3).', 'age_aux_b1_13_funcion_publica', (select id from public.topics where slug = 'age-aux-b1-13-funcion-publica'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-1007'), 'Art. 9.1 Reglamento RCP (RD 2073/1999)', 'El Registro Central de Personal asignará un número de identificación personal, que estará basado en el número del documento nacional de identidad cuando inscriba ciudadanos españoles. Este número será el mismo durante toda la vida administrativa de los interesados', null, '869b604dee14a75bcabe7da4400721f20e17f1621ec4c80aea561672ed9fc102', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '869b604dee14a75bcabe7da4400721f20e17f1621ec4c80aea561672ed9fc102')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Está basado en el número del documento nacional de identidad y será el mismo durante toda la vida administrativa.', true), ('B', 'Cambia con cada nuevo nombramiento o contrato laboral.', false), ('C', 'Se asigna por el órgano de personal de cada Ministerio.', false), ('D', 'Puede reutilizarse cuando la persona anterior ya no esté de alta en el Registro.', false)) as v(label, body, ok)
)
