  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento del Registro Central de Personal, las anotaciones provisionales solo podrán mantenerse durante el plazo de:', 'El art. 14.4 fija noventa días naturales; transcurridos sin comunicación formal, el Registro la requiere y prorroga otros noventa días, tras los cuales la anotación se cancela.', 'age_aux_b1_13_funcion_publica', (select id from public.topics where slug = 'age-aux-b1-13-funcion-publica'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-1007'), 'Art. 14.4 Reglamento RCP (RD 2073/1999)', 'Las anotaciones provisionales sólo podrán mantenerse durante el plazo de noventa días naturales. Transcurrido dicho plazo sin que se hubiera recibido la comunicación formal, el Registro Central de Personal requerirá su remisión al órgano correspondiente, prorrogando el plazo en otros noventa días naturales.', null, 'f45396d4c184d0a684ccd776fd6fd9c4a9ca534937c5430131b343cc89e1640e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f45396d4c184d0a684ccd776fd6fd9c4a9ca534937c5430131b343cc89e1640e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Noventa días naturales, prorrogable en otros noventa tras requerir la comunicación formal.', true), ('B', 'Treinta días hábiles, sin prórroga.', false), ('C', 'Seis meses, prorrogables por otros seis.', false), ('D', 'Noventa días hábiles, sin prórroga.', false)) as v(label, body, ok)
)
