with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 10 de la Ley 53/1984, de Incompatibilidades, quien acceda a un nuevo puesto del sector público incompatible con el que venía desempeñando y no ejerza la opción en el plazo de toma de posesión:', 'El art. 10 obliga a optar dentro del plazo de toma de posesión; a falta de opción se entiende que se opta por el nuevo puesto y se pasa a excedencia voluntaria en el anterior.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 10 Ley 53/1984', 'A falta de opción en el plazo señalado se entenderá que optan por el nuevo puesto, pasando a la situación de excedencia voluntaria en los que vinieran desempeñando.', null, '67c6769d6729a765e778daa9a0252f02765cb75ed5e49ca31ce87f1abd4fe5df', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '67c6769d6729a765e778daa9a0252f02765cb75ed5e49ca31ce87f1abd4fe5df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se entenderá que opta por el puesto que venía desempeñando, decayendo en el nuevo nombramiento.', false), ('B', 'Pasará a la situación de suspensión de funciones en ambos puestos.', false), ('C', 'Podrá seguir desempeñando ambos puestos hasta que se resuelva un expediente de compatibilidad.', false), ('D', 'Se entenderá que opta por el nuevo puesto, pasando a excedencia voluntaria en el que venía desempeñando.', true)) as v(label, body, ok)
)
