  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 14 de la Ley 53/1984, la resolución motivada que reconozca la compatibilidad para actividades privadas o declare la incompatibilidad se dictará en el plazo de:', 'El art. 14 fija un plazo de dos meses para resolver; el reconocimiento de compatibilidad no puede modificar la jornada ni el horario y queda sin efecto si se cambia de puesto en el sector público.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 14 Ley 53/1984', 'La resolución motivada reconociendo la compatibilidad o declarando la incompatibilidad, que se dictará en el plazo de dos meses', null, 'bfe3f0911db6437ed32948cff325efaa765070800c91b7d5264cc4caa52b7527', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bfe3f0911db6437ed32948cff325efaa765070800c91b7d5264cc4caa52b7527')
