with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 de la Ley 53/1984, el personal que, en representación del sector público, pertenezca a Consejos de Administración u órganos de gobierno de entidades o empresas no podrá pertenecer, salvo autorización excepcional, a más de:', 'El art. 8 limita la pertenencia a dos Consejos u órganos de gobierno, salvo autorización excepcional del Gobierno, del órgano autonómico competente o del Pleno de la Corporación Local; solo se perciben las dietas o indemnizaciones por asistencia.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 8 Ley 53/1984', 'No se podrá pertenecer a más de dos Consejos de Administración u órganos de gobierno a que se refiere el apartado anterior', null, 'e81fed46f0f76e2826982d2a50e740e4a4f50e383f11e46aa4a6a08d11340415', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e81fed46f0f76e2826982d2a50e740e4a4f50e383f11e46aa4a6a08d11340415')
