  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes actividades está exceptuada del régimen de incompatibilidades según el artículo 19 de la Ley 53/1984?', 'El art. 19 exceptúa, entre otras, la participación en tribunales calificadores, la creación literaria, artística o científica y la colaboración ocasional en congresos o cursos. Las otras opciones requieren autorización o están prohibidas (arts. 3 y 12).', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 19.c) Ley 53/1984', 'Quedan exceptuadas del régimen de incompatibilidades de la presente Ley las actividades siguientes: […] c) La participación en Tribunales calificadores de pruebas selectivas para ingreso en las Administraciones Públicas.', null, 'b7569ed6324ac880544ea5e22f81f0c5013656a992c8cc8310750163f3418290', false
