with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 9 del Real Decreto 462/2002, la cantidad que se devenga diariamente para satisfacer los gastos que origina la estancia fuera de la residencia oficial en las comisiones de servicio ordinarias se denomina:', 'El art. 9.1 la denomina «dieta» (o «plus» si la comisión la desempeña personal de las Fuerzas Armadas o de Seguridad formando unidad). La residencia eventual se aplica a las comisiones de los arts. 6 y 7.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 9.1 RD 462/2002', '«Dieta» es la cantidad que se devenga diariamente para satisfacer los gastos que origina la estancia fuera de la residencia oficial en los casos previstos en el artículo 5 del presente Real Decreto.', null, 'c0d0ed7e0e5dd6ba0355399f6ef7e1306468599a40b3a85c147193b93c356520', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c0d0ed7e0e5dd6ba0355399f6ef7e1306468599a40b3a85c147193b93c356520')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Indemnización de residencia eventual.', false), ('B', 'Gastos de viaje.', false), ('C', 'Asistencia.', false), ('D', 'Dieta.', true)) as v(label, body, ok)
)
