with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 19 del Real Decreto 462/2002, el personal al que se encomiende una comisión de servicio:', 'El art. 19.1 reconoce el derecho a percibir por adelantado el importe aproximado de dietas, pluses, residencia eventual y gastos de viaje, sin perjuicio de devolver lo que proceda al terminar la comisión.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 19.1 RD 462/2002', 'El personal a quien se encomiende una comisión de servicio de las reguladas en el artículo 3 del presente Real Decreto tendrá derecho a percibir por adelantado el importe aproximado de las dietas, pluses, residencia eventual y gastos de viaje', null, '4418ddf542e4604f42a4b7b22c5ed26974cc8e4412be0ee8deddaff1a67d0da7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4418ddf542e4604f42a4b7b22c5ed26974cc8e4412be0ee8deddaff1a67d0da7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tiene derecho a percibir por adelantado el importe aproximado de las dietas y gastos de viaje.', true), ('B', 'Solo puede cobrar las dietas una vez justificada la comisión, sin anticipo.', false), ('C', 'Tiene derecho a un anticipo únicamente si la comisión se desarrolla en el extranjero.', false), ('D', 'Debe adelantar los gastos y solicitar su reintegro en el plazo de un mes.', false)) as v(label, body, ok)
