with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento (UE) 2024/1689 de inteligencia artificial, un «sistema de IA» es un sistema basado en una máquina que:', 'El art. 3.1) lo define como sistema basado en una máquina, con distintos niveles de autonomía y posible capacidad de adaptación, que infiere de las entradas cómo generar resultados de salida que pueden influir en entornos físicos o virtuales.', 'age_aux_b2_05_informatica_basica', (select id from public.topics where slug = 'age-aux-b2-05-informatica-basica'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:32024R1689'), 'Reglamento (UE) 2024/1689, art. 3.1)', '«sistema de IA»: un sistema basado en una máquina que está diseñado para funcionar con distintos niveles de autonomía y que puede mostrar capacidad de adaptación tras el despliegue, y que, para objetivos explícitos o implícitos, infiere de la información de entrada que recibe la manera de generar resultados de salida, como predicciones, contenidos, recomendaciones o decisiones', null, '91fa29038508941dfab29dcba11e343bb23f69919ac31550b1cac1f86a3892ba', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '91fa29038508941dfab29dcba11e343bb23f69919ac31550b1cac1f86a3892ba')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ejecuta siempre instrucciones fijas programadas previamente, sin ninguna autonomía.', false), ('B', 'Solo puede generar texto a partir de las instrucciones de un usuario.', false), ('C', 'Infiere de la información de entrada que recibe la manera de generar resultados de salida, como predicciones, contenidos, recomendaciones o decisiones.', true), ('D', 'Está diseñado exclusivamente para funcionar sin conexión a Internet.', false)) as v(label, body, ok)
)
