select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxiliar-administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El Reglamento (UE) 2024/1689 llama «ultrasuplantación» (deepfake) a:', 'El art. 3.60) define la ultrasuplantación como contenido de imagen, audio o vídeo generado o manipulado por IA que parece real y puede inducir a error sobre su autenticidad.', 'age_aux_b2_05_informatica_basica', (select id from public.topics where slug = 'age-aux-b2-05-informatica-basica'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:32024R1689'), 'Reglamento (UE) 2024/1689, art. 3.60)', '«ultrasuplantación»: un contenido de imagen, audio o vídeo generado o manipulado por una IA que se asemeja a personas, objetos, lugares, entidades o sucesos reales y que puede inducir a una persona a pensar erróneamente que son auténticos o verídicos', null, '1b7723d8fe857bae783fa670237ca60b318bf940ca12d0f181950e98855714f5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1b7723d8fe857bae783fa670237ca60b318bf940ca12d0f181950e98855714f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un contenido de imagen, audio o vídeo generado o manipulado por una IA que se asemeja a personas, objetos, lugares, entidades o sucesos reales y puede inducir a pensar que son auténticos.', true), ('B', 'El acceso a un sistema informático con la identidad de otro usuario mediante su contraseña.', false), ('C', 'La suplantación de una página web legítima para obtener credenciales.', false), ('D', 'Cualquier texto generado por un modelo de IA de uso general.', false)) as v(label, body, ok)
)
