  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Norma Técnica de Interoperabilidad de Digitalización de Documentos, el nivel de resolución mínimo para las imágenes electrónicas será de:', 'El apartado IV.2 de la NTI fija una resolución mínima de 200 píxeles por pulgada para cualquier imagen (blanco y negro, color o escala de grises).', 'age_aux_b2_05_informatica_basica', (select id from public.topics where slug = 'age-aux-b2-05-informatica-basica'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-13168'), 'NTI de Digitalización de Documentos · IV.2', 'El nivel de resolución mínimo para imágenes electrónicas será de 200 píxeles por pulgada, tanto para imágenes obtenidas en blanco y negro, color o escala de grises.', null, 'e65f111b8c6082eb26817311560f800422e5a0a616cfb335a16a3cafba8335db', false
