with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 2032/2009, de unidades legales de medida, un kilobit representa:', 'La nota (a) de la tabla de prefijos SI aclara que estos representan potencias de 10 y que no deben usarse para potencias de 2: un kilobit son 1000 bits, no 1024.', 'age_aux_b2_05_informatica_basica', (select id from public.topics where slug = 'age-aux-b2-05-informatica-basica'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-927'), 'RD 2032/2009 · Anexo, tabla 5, nota (a)', 'Los prefijos SI representan estrictamente potencias de 10. No deben utilizarse para expresar potencias de 2 (por ejemplo, un kilobit representa 1000 bits y no 1024 bits).', null, '6be2cc220e82c6fad6cdd7502e91866941300b50e2a48a5d35fa8df1c1785198', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6be2cc220e82c6fad6cdd7502e91866941300b50e2a48a5d35fa8df1c1785198')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '1024 bits, porque en informática los prefijos SI expresan potencias de 2.', false), ('B', '1000 bytes, porque el prefijo kilo se aplica al octeto.', false), ('C', '8000 bits, porque cada byte tiene ocho bits.', false), ('D', '1000 bits, porque los prefijos SI representan estrictamente potencias de 10.', true)) as v(label, body, ok)
)
