with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 2 de la Ley Orgánica 3/1981, en la primera propuesta será designado Defensor del Pueblo quien obtenga una votación favorable de:', 'El art. 2.4 LO 3/1981 exige tres quintos del Congreso y ratificación por la misma mayoría del Senado en veinte días; solo en propuestas sucesivas basta la mayoría absoluta del Senado una vez obtenidos los tres quintos del Congreso (art. 2.5).', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 2.4 LO 3/1981', 'Será designado quien obtuviese una votación favorable de las tres quintas partes de los miembros del Congreso y posteriormente, en un plazo máximo de veinte días, fuese ratificado por esta misma mayoría del Senado.', null, 'c94ae60111ea315e0637c94720518fb9d3e76d1b3b057a4919c542073e81f42e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c94ae60111ea315e0637c94720518fb9d3e76d1b3b057a4919c542073e81f42e')
  returning id
