with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 7 de la Ley Orgánica 3/1981, el Defensor del Pueblo deberá cesar en toda situación de incompatibilidad dentro de:', 'El art. 7.2 LO 3/1981 fija diez días desde el nombramiento y antes de la toma de posesión; si la incompatibilidad es sobrevenida, se entiende que renuncia (art. 7.3).', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 7.2 LO 3/1981', 'El Defensor del Pueblo deberá cesar, dentro de los diez días siguientes a su nombramiento y antes de tomar posesión, en toda situación de incompatibilidad que pudiera afectarle, entendiéndose en caso contrario que no acepta el nombramiento.', null, '75f1205ababeec4a2660893e8643840f1ddc59bc21d6b90afdc11476b94cb10c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '75f1205ababeec4a2660893e8643840f1ddc59bc21d6b90afdc11476b94cb10c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los diez días siguientes a su nombramiento y antes de tomar posesión; si no, se entiende que no acepta el nombramiento.', true), ('B', 'El mes siguiente a su toma de posesión; si no, cesa automáticamente.', false), ('C', 'Los quince días siguientes a su nombramiento; si no, lo cesa el Presidente del Congreso.', false), ('D', 'Los tres días siguientes a su elección; si no, la Comisión Mixta propone otro candidato.', false)) as v(label, body, ok)
)
