with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley Orgánica 1/1982, el derecho al honor, a la intimidad personal y familiar y a la propia imagen es:', 'El art. 1.3 LO 1/1982 lo declara irrenunciable, inalienable e imprescriptible, y nula la renuncia a la protección legal.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-11196'), 'Art. 1.3 LO 1/1982', 'El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.', null, 'cd6da55a8dad85f7351edfa4447c2ea3d805605ea9583cca875b5d0977a4ab23', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cd6da55a8dad85f7351edfa4447c2ea3d805605ea9583cca875b5d0977a4ab23')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Renunciable, pero inalienable e imprescriptible.', false), ('B', 'Irrenunciable, pero prescribe a los cuatro años.', false), ('C', 'Transmisible por herencia a los descendientes.', false), ('D', 'Irrenunciable, inalienable e imprescriptible.', true)) as v(label, body, ok)
)
