  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 de la Ley Orgánica 1/1982, el derecho a la propia imagen no impedirá su captación cuando se trate de personas que ejerzan un cargo público y la imagen se capte:', 'El art. 8.2.a) LO 1/1982 permite captar la imagen de cargos públicos o personas con proyección pública durante actos públicos o en lugares abiertos al público; no se aplica a quienes necesitan el anonimato por su función.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-11196'), 'Art. 8.2.a) LO 1/1982', 'a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público.', null, 'ca297f87f6f9b97c9db9813193daadb7152974d0da5af2abfc5e1f1cd29c6d1a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ca297f87f6f9b97c9db9813193daadb7152974d0da5af2abfc5e1f1cd29c6d1a')
  returning id
), o as (
