  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el momento en que el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar.', true), ('B', 'En el momento en que se produce el resultado.', false), ('C', 'En el momento en que se descubre el hecho por la autoridad.', false), ('D', 'En el momento en que se presenta la denuncia o querella.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
