  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 8 del Código Penal, cuando unos hechos sean susceptibles de ser calificados con arreglo a dos o más preceptos, la primera regla establece que:', 'El art. 8 CP ordena las reglas del concurso de normas: 1.ª especialidad, 2.ª subsidiariedad, 3.ª consunción y 4.ª, en defecto de las anteriores, alternatividad (precepto más grave).', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 8 CP', '1.ª El precepto especial se aplicará con preferencia al general.', null, '4a33be17ec4b764636e4b59e6c00a0cf7eaa58126ba2a572d914f147bf916a44', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4a33be17ec4b764636e4b59e6c00a0cf7eaa58126ba2a572d914f147bf916a44')
