  select 'Según el artículo 20.5.º del Código Penal, ¿cuál de los siguientes es un requisito del estado de necesidad?', 'El estado de necesidad exige que el mal causado no sea mayor que el evitado, que la situación no se haya provocado intencionadamente y que el necesitado no tenga obligación de sacrificarse. La agresión ilegítima es requisito de la legítima defensa.', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.5.º CP', 'Primero. Que el mal causado no sea mayor que el que se trate de evitar.', null, 'c9d3cd1b84c960f2a8de7e7932c42b91302d4df9ce0599dd081bf8b7bd5ac1ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c9d3cd1b84c960f2a8de7e7932c42b91302d4df9ce0599dd081bf8b7bd5ac1ce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que exista una agresión ilegítima previa.', false), ('B', 'Que el sujeto haya provocado la situación de necesidad.', false), ('C', 'Que el mal causado no sea mayor que el que se trate de evitar.', true), ('D', 'Que el necesitado tenga, por su oficio, obligación de sacrificarse.', false)) as v(label, body, ok)
)
