  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos penales, según el artículo 24.2 del Código Penal, se considerará funcionario público:', 'El concepto penal de funcionario (art. 24.2 CP) es amplio: participar en funciones públicas por ley, elección o nombramiento. Tener mando o jurisdicción propia define a la autoridad (art. 24.1).', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 24.2 CP', '2. Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas.', null, 'c6e40f3db060dfc6368717223209bad1acde5d0ec600ab3da01776073d67f9f5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c6e40f3db060dfc6368717223209bad1acde5d0ec600ab3da01776073d67f9f5')
  returning id
), o as (
