  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 140 del Código Penal, el asesinato será castigado con prisión permanente revisable, entre otros casos, cuando la víctima sea menor de:', 'El art. 140.1.1.ª CP impone la prisión permanente revisable cuando la víctima sea menor de dieciséis años o persona especialmente vulnerable por edad, enfermedad o discapacidad.', 'gc_08b_penal_especial', (select id from public.topics where slug = 'gc-08b-penal-especial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 140.1 CP', '1.ª Que la víctima sea menor de dieciséis años de edad, o se trate de una persona especialmente vulnerable por razón de su edad, enfermedad o discapacidad.', null, '0bbd71fed7c1a4c68b6d5dbb2d850fbcc287411cd2732b38f6459bae0b4d78f4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0bbd71fed7c1a4c68b6d5dbb2d850fbcc287411cd2732b38f6459bae0b4d78f4')
