with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 15 de la Ley de Enjuiciamiento Criminal, cuando no conste el lugar en que se haya cometido el delito y se suscite competencia entre varios jueces, ¿cuál tiene preferencia en primer lugar?', 'El art. 15 LECrim enumera cuatro fueros subsidiarios (pruebas materiales, aprehensión, residencia del reo y noticia del delito) y ordena que la competencia se decida dando preferencia por ese mismo orden, por lo que prima el lugar donde se descubrieron pruebas materiales.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 15 LECrim', '1.º El del término municipal, partido o circunscripción en que se hayan descubierto pruebas materiales del delito. […] Si se suscitase competencia entre estos Jueces o Tribunales, se decidirá dando la preferencia por el orden con que están expresados en los números que preceden.', null, 'ee80483d733a38b4a5c4892984fabc669ee52d9f65145ee00823bb95fd6b9b29', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee80483d733a38b4a5c4892984fabc669ee52d9f65145ee00823bb95fd6b9b29')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El del término municipal, partido o circunscripción en que se hayan descubierto pruebas materiales del delito.', true), ('B', 'El del término municipal, partido o circunscripción en que el presunto reo haya sido aprehendido.', false), ('C', 'El de la residencia del reo presunto.', false), ('D', 'Cualquiera que hubiese tenido noticia del delito.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
