with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, ¿qué documentos deberán ser traducidos en todo caso al imputado o acusado que no hable o entienda el castellano o la lengua oficial de la actuación?', 'El art. 123.1.d) LECrim reconoce el derecho a la traducción escrita de los documentos esenciales para la defensa y precisa que siempre deben traducirse las resoluciones que acuerden la prisión, el escrito de acusación y la sentencia.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 123.1.d) LECrim', 'Deberán ser traducidos, en todo caso, las resoluciones que acuerden la prisión del imputado, el escrito de acusación y la sentencia.', null, '57a03f63fa113b6b976c741dbc2e0e059aa4df3ed48497aef3eba0f838776753', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '57a03f63fa113b6b976c741dbc2e0e059aa4df3ed48497aef3eba0f838776753')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La denuncia, el atestado policial y la sentencia.', false), ('B', 'La querella, el auto de procesamiento y la citación a juicio.', false), ('C', 'Únicamente la sentencia firme.', false), ('D', 'Las resoluciones que acuerden la prisión del imputado, el escrito de acusación y la sentencia.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 126 de la Ley de Enjuiciamiento Criminal, ¿qué derechos del artículo 123.1 no podrán ser renunciados en ningún caso por el imputado o acusado?', 'El art. 126 LECrim admite la renuncia expresa, libre e informada a los derechos del art. 123, salvo los de las letras a) (intérprete en todas las actuaciones en que sea necesaria su presencia) y c) (interpretación de todo el juicio oral), que son irrenunciables.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 126 LECrim', 'En todo caso, los derechos a los que se refieren las letras a) y c) del apartado 1 del artículo 123 no podrán ser renunciados.', null, '7d38a27e802afb77b9fdf0d291b2b2ef44aed56360ddc37fc6359b488eaa86b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7d38a27e802afb77b9fdf0d291b2b2ef44aed56360ddc37fc6359b488eaa86b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El de ser asistido por un intérprete en las actuaciones en que sea necesaria su presencia y el de interpretación de todas las actuaciones del juicio oral.', true), ('B', 'El de traducción escrita de los documentos esenciales y el de presentar una solicitud motivada para que se considere esencial un documento.', false), ('C', 'El de servirse de intérprete en las conversaciones con su abogado y el de traducción escrita de la sentencia.', false), ('D', 'Todos ellos pueden renunciarse, siempre que la renuncia sea expresa y libre.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 261 de la Ley de Enjuiciamiento Criminal, con carácter general no están obligados a denunciar los parientes colaterales del delincuente:', 'El art. 261 LECrim exime de la obligación de denunciar al cónyuge o persona en análoga relación de afectividad, a ascendientes y descendientes y a los colaterales hasta el segundo grado inclusive, salvo en los delitos graves contra menores o personas con discapacidad necesitadas de especial protección que el propio artículo enumera.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 261 LECrim', '2.º Quienes sean ascendientes y descendientes del delincuente y sus parientes colaterales hasta el segundo grado inclusive.', null, 'a3e561fffed2aabc2ebaa097ce3561fe5945df7db567cdd359811cc28a4b0a63', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a3e561fffed2aabc2ebaa097ce3561fe5945df7db567cdd359811cc28a4b0a63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hasta el tercer grado inclusive.', false), ('B', 'Hasta el segundo grado inclusive.', true), ('C', 'Hasta el cuarto grado inclusive.', false), ('D', 'Hasta el cuarto grado por consanguinidad y el segundo por afinidad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 266 de la Ley de Enjuiciamiento Criminal, ¿en cuál de los siguientes casos no se podrá presentar la denuncia por vía telemática?', 'El art. 266 LECrim excluye la denuncia telemática si el hecho se cometió con violencia o intimidación, si tiene autor conocido, si hay testigos, si el denunciante es menor de edad, si hay delito flagrante o si los hechos son de naturaleza violenta o sexual; la denuncia telemática se firma con firma electrónica.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 266 LECrim', 'No se podrán denunciar por vía telemática aquellos hechos que se hayan producido con violencia o intimidación, ni si tienen autor conocido, ni si existen testigos, ni si el denunciante es menor de edad, ni si se ha cometido delito flagrante, ni aquellos hechos de naturaleza violenta o sexual.', null, '6b9e456555840229dfa6f26acee8cc93a6218df6caef6669e0f2aa7cf15f0dc8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6b9e456555840229dfa6f26acee8cc93a6218df6caef6669e0f2aa7cf15f0dc8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando se trate de un hecho sin autor conocido ni testigos, cometido sin violencia ni intimidación.', false), ('B', 'Cuando la denuncia se firme con firma electrónica.', false), ('C', 'Cuando el denunciante sea menor de edad.', true), ('D', 'Cuando el denunciante resida fuera del partido judicial en que se cometió el hecho.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 277 de la Ley de Enjuiciamiento Criminal, la querella se presentará siempre:', 'A diferencia de la denuncia, la querella exige postulación: el art. 277 LECrim impone su presentación por Procurador con poder bastante y la firma de Letrado.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 277 LECrim', 'La querella se presentará siempre por medio de Procurador con poder bastante y suscrita por Letrado.', null, '8b57a6ef9e68819fbd2590338c5d21af0cf9597bc5e6fc4f853603f244df031d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8b57a6ef9e68819fbd2590338c5d21af0cf9597bc5e6fc4f853603f244df031d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Personalmente por el querellante, sin necesidad de Procurador ni de Letrado.', false), ('B', 'Por medio de Procurador con poder bastante y suscrita por Letrado.', true), ('C', 'Por medio de Letrado, sin que sea necesaria la intervención de Procurador.', false), ('D', 'Por medio de Procurador, sin que sea necesaria la firma de Letrado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 283 de la Ley de Enjuiciamiento Criminal, ¿quiénes de los siguientes constituyen la Policía judicial?', 'El art. 283 LECrim enumera quiénes constituyen la Policía judicial como auxiliares de jueces, tribunales y Ministerio Fiscal; su apartado cuarto incluye a los Jefes, Oficiales e individuos de la Guardia Civil.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 283 LECrim', 'Cuarto. Los Jefes, Oficiales e individuos de la Guardia Civil o de cualquier otra fuerza destinada a la persecución de malhechores.', null, '2dda3d3d7a75c525099e0aa424bdcfa7d18f92ec45755a913360703dd9f2c1b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2dda3d3d7a75c525099e0aa424bdcfa7d18f92ec45755a913360703dd9f2c1b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los Jefes, Oficiales e individuos de la Guardia Civil.', true), ('B', 'Los Notarios y Registradores de la Propiedad.', false), ('C', 'Los Procuradores de los Tribunales.', false), ('D', 'Los Abogados del Estado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 284.2 de la Ley de Enjuiciamiento Criminal, cuando no exista autor conocido del delito, la Policía Judicial conservará el atestado sin enviarlo a la autoridad judicial ni al Ministerio Fiscal, salvo, entre otros casos:', 'El art. 284.2 LECrim exceptúa de la conservación del atestado sin autor conocido los delitos contra la vida, la integridad física, la libertad e indemnidad sexuales y los relacionados con la corrupción, los casos en que se practique una diligencia con resultado pasadas setenta y dos horas y aquellos en que el Fiscal o el juez soliciten la remisión.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 284.2 LECrim', 'a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;', null, 'f2813048824ee9db430d0064414d2247068a82c18fe486dfca39d463ce5c5b26', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f2813048824ee9db430d0064414d2247068a82c18fe486dfca39d463ce5c5b26')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que se trate de delitos contra el patrimonio cometidos sin violencia ni intimidación.', false), ('B', 'Que hayan transcurrido veinticuatro horas desde la apertura del atestado.', false), ('C', 'Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción.', true), ('D', 'Que el denunciante lo solicite por escrito.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 295 de la Ley de Enjuiciamiento Criminal, salvo fuerza mayor y el supuesto del artículo 284.2, los funcionarios de Policía Judicial no podrán dejar transcurrir sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias practicadas más de:', 'El art. 295 LECrim fija en veinticuatro horas el plazo máximo para dar conocimiento de las diligencias practicadas, y castiga disciplinariamente tanto su superación como la demora innecesaria dentro de ese plazo.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 295 LECrim', 'En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias que hubieran practicado, salvo en los supuestos de fuerza mayor y en el previsto en el apartado 2 del artículo 284.', null, '3ba1967ffe3fabd1f7ebeadd530f6a55c558049fa2866db7e9221d4385ac98a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3ba1967ffe3fabd1f7ebeadd530f6a55c558049fa2866db7e9221d4385ac98a5')
