  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 492 de la Ley de Enjuiciamiento Criminal, la Autoridad o agente de Policía judicial tendrá obligación de detener a quien aún no esté procesado cuando tenga motivos racionalmente bastantes para creer:', 'El art. 492.4.º LECrim exige dos circunstancias: motivos racionalmente bastantes sobre la existencia de un hecho con caracteres de delito y sobre la participación en él de la persona a detener.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 492.4.º LECrim', '1.ª Que la Autoridad o agente tenga motivos racionalmente bastantes para creer en la existencia de un hecho que presente los caracteres de delito. 2.ª Que los tenga también bastantes para creer que la persona a quien intente detener tuvo participación en él.', null, '372f96d49a9adbb57cdad4670e56a67b9d1922012f6d6bba01730dfd28af540a', false
