with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 6 de la Ley 4/2015, del Estatuto de la víctima del delito, en el momento de presentar su denuncia toda víctima tiene derecho:', 'El art. 6 de la Ley 4/2015 reconoce a la víctima denunciante el derecho a una copia certificada de la denuncia y a la asistencia lingüística gratuita y traducción escrita de esa copia si no entiende las lenguas oficiales del lugar.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 6 Ley 4/2015', 'a) A obtener una copia de la denuncia, debidamente certificada.', null, 'a0743b2edbf7de7e2ec7fb1b4aa468b36de9b68e96ca769af41f88fb3f360dc2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a0743b2edbf7de7e2ec7fb1b4aa468b36de9b68e96ca769af41f88fb3f360dc2')
  returning id
