with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 de la Ley 4/2015, los abogados y procuradores no podrán dirigirse a las víctimas de catástrofes, calamidades públicas u otros sucesos con un número elevado de víctimas que puedan constituir delito para ofrecerles sus servicios profesionales, salvo que la víctima los haya solicitado expresamente, hasta transcurridos:', 'El art. 8 de la Ley 4/2015 establece un periodo de reflexión de 45 días; su incumplimiento es infracción disciplinaria muy grave.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 8.1 Ley 4/2015', 'para ofrecerles sus servicios profesionales hasta transcurridos 45 días desde el hecho.', null, '02aa427151795b7396a821b9160de9688940cba7d1ca5283b98f997a5f8ad060', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '02aa427151795b7396a821b9160de9688940cba7d1ca5283b98f997a5f8ad060')
  returning id
), o as (
