  select q.id, v.label, v.body, v.ok from q, (values ('A', '15 días desde el hecho.', false), ('B', '45 días desde el hecho.', true), ('C', '30 días desde el hecho.', false), ('D', '60 días desde el hecho.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 12 de la Ley 4/2015, del Estatuto de la víctima del delito, ¿puede la víctima recurrir la resolución de sobreseimiento?', 'El art. 12.2 de la Ley 4/2015 permite a la víctima recurrir el sobreseimiento sin necesidad de personación previa, y el art. 12.1 obliga a comunicárselo.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 12.2 Ley 4/2015', 'La víctima podrá recurrir la resolución de sobreseimiento conforme a lo dispuesto en la Ley de Enjuiciamiento Criminal, sin que sea necesario para ello que se haya personado anteriormente en el proceso.', null, '0e6a625c0fb17f41a866472f5a293ecb96d9f8ab4fb006395822e0196706fc8d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0e6a625c0fb17f41a866472f5a293ecb96d9f8ab4fb006395822e0196706fc8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo si se hubiera personado como acusación particular antes de dictarse el sobreseimiento.', false), ('B', 'No; únicamente el Ministerio Fiscal puede recurrir el sobreseimiento.', false), ('C', 'Solo cuando se trate de delitos de violencia de género o contra la libertad sexual.', false), ('D', 'Sí, conforme a la Ley de Enjuiciamiento Criminal, sin que sea necesario que se haya personado anteriormente en el proceso.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 21 de la Ley 4/2015, las autoridades y funcionarios encargados de la investigación penal velarán por que, en la medida en que no perjudique la eficacia del proceso, se reciba declaración a las víctimas:', 'El art. 21 de la Ley 4/2015 busca evitar la victimización secundaria: declaraciones sin dilaciones, el menor número de veces posible, con acompañamiento y con los reconocimientos médicos imprescindibles.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 21.b) Ley 4/2015', 'b) Se reciba declaración a las víctimas el menor número de veces posible, y únicamente cuando resulte estrictamente necesario para los fines de la investigación penal.', null, 'e0b43b5a9c4e1e4da4721d321bf26449b2a5ef504d8b5c0b8c178aeb3fcbbc3b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e0b43b5a9c4e1e4da4721d321bf26449b2a5ef504d8b5c0b8c178aeb3fcbbc3b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
