  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 542.3 de la Ley Orgánica del Poder Judicial, respecto de los hechos o noticias que conozcan por razón de su actuación profesional, los abogados:', 'El art. 542.3 LOPJ impone a los abogados el deber de secreto profesional sobre todos los hechos o noticias conocidos por razón de su actuación profesional, sin que puedan ser obligados a declarar sobre ellos.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 542.3 LOPJ', 'Los abogados deberán guardar secreto de todos los hechos o noticias de que conozcan por razón de cualquiera de las modalidades de su actuación profesional, no pudiendo ser obligados a declarar sobre los mismos.', null, '6bb4e55c3003d9651c482b6ec80258563b9e5c5bc1d36e7627d32c40a441c8f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6bb4e55c3003d9651c482b6ec80258563b9e5c5bc1d36e7627d32c40a441c8f2')
