  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 547 de la Ley Orgánica del Poder Judicial, la función de la Policía Judicial competerá, cuando fueren requeridos para prestarla:', 'El art. 547 LOPJ define la función de Policía Judicial como auxilio a juzgados, tribunales y Ministerio Fiscal en la averiguación de delitos y aseguramiento de delincuentes, y la atribuye, cuando sean requeridos, a todos los miembros de las Fuerzas y Cuerpos de Seguridad, estatales, autonómicos o locales.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 547 LOPJ', 'Esta función competerá, cuando fueren requeridos para prestarla, a todos los miembros de las Fuerzas y Cuerpos de Seguridad, tanto si dependen del Gobierno central como de las comunidades autónomas o de los entes locales, dentro del ámbito de sus respectivas competencias.', null, '411419e4465828707e269b13b7c260f7ea9b41f8fcbef0b461bba0fe1dab6e23', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '411419e4465828707e269b13b7c260f7ea9b41f8fcbef0b461bba0fe1dab6e23')
  returning id
), o as (
