select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 550.2 de la Ley Orgánica del Poder Judicial, los funcionarios de Policía Judicial a quienes se hubiera encomendado una investigación concreta no podrán ser removidos o apartados hasta que finalice la misma o la fase del procedimiento judicial que la originó, salvo:', 'El art. 550.2 LOPJ (reproducido en el art. 16 del RD 769/1987) garantiza la inamovilidad del funcionario de Policía Judicial en la investigación encomendada, que solo puede cesar por decisión o con autorización del juez o fiscal competente.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 550.2 LOPJ', 'no podrán ser removidos o apartados hasta que finalice la misma o, en todo caso, la fase del procedimiento judicial que la originó, si no es por decisión o con la autorización del juez o fiscal competente.', null, 'acf7d471909910ffda759d753a8aac26353ac703bf3bb4e2be31a05001b9ed03', false
