with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 4 del Real Decreto 769/1987, todos los componentes de las Fuerzas y Cuerpos de Seguridad, así que tengan noticia de la perpetración de un hecho presuntamente delictivo, practicarán por su propia iniciativa:', 'El art. 4 RD 769/1987 obliga a todos los miembros de las FCS a practicar las primeras diligencias de prevención y aseguramiento y a ocupar y custodiar los objetos del delito, dando cuenta a la Autoridad Judicial o Fiscal.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-14578'), 'Art. 4 RD 769/1987', 'practicarán por su propia iniciativa y según sus respectivas atribuciones, las primeras diligencias de prevención y aseguramiento así que tengan noticia de la perpetración del hecho presuntamente delictivo, y la ocupación y custodia de los objetos que provinieren del delito o estuvieren relacionados con su ejecución', null, '9753a95e46772a927f431bf2ec619402d21804f4c59d28473c4784d174811bbc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9753a95e46772a927f431bf2ec619402d21804f4c59d28473c4784d174811bbc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La instrucción completa del sumario.', false), ('B', 'Las primeras diligencias de prevención y aseguramiento, y la ocupación y custodia de los objetos relacionados con el delito.', true), ('C', 'Únicamente la comunicación del hecho al Juez, sin otra actuación.', false), ('D', 'La entrada y registro en el domicilio del sospechoso.', false)) as v(label, body, ok)
)
