  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11 del Real Decreto 769/1987, los funcionarios policiales comisionados por la Autoridad Judicial o Fiscal para una concreta investigación, respecto de las instrucciones técnicas de sus superiores policiales inmediatos:', 'El art. 11 RD 769/1987 da prevalencia a las órdenes y directrices de la Autoridad Judicial o Fiscal: las instrucciones técnicas de los superiores policiales no pueden contradecirlas.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-14578'), 'Art. 11 RD 769/1987', 'se atendrán en el desarrollo de ésta a las órdenes y directrices que hubieren recibido, sin que las instrucciones de carácter técnico que obtuvieren de sus superiores policiales inmediatos puedan contradecir las primeras.', null, 'bf0f300f805b512649f0e228bdd3e2e706edf100080a28c0b55ac3fcc6a3e8a6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bf0f300f805b512649f0e228bdd3e2e706edf100080a28c0b55ac3fcc6a3e8a6')
  returning id
), o as (
