  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 14.2 de la Ley 39/2015, ¿quiénes de los siguientes están obligados en todo caso a relacionarse a través de medios electrónicos con las Administraciones Públicas?', 'El art. 14 LPAC permite a las personas físicas elegir el medio de comunicación, salvo obligación, y obliga a relacionarse electrónicamente, entre otros, a las personas jurídicas, las entidades sin personalidad, los profesionales colegiados en su actividad, sus representantes y los empleados públicos por razón de su condición.', 'gc_10a_procedimiento_administrativo', (select id from public.topics where slug = 'gc-10a-procedimiento-administrativo'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 14.2 LPAC', 'En todo caso, estarán obligados a relacionarse a través de medios electrónicos con las Administraciones Públicas para la realización de cualquier trámite de un procedimiento administrativo, al menos, los siguientes sujetos: a) Las personas jurídicas.', null, 'dca5217a9e942ba3a0daab70f1e91b0c2395e120ffe623a904338642cfbb0724', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dca5217a9e942ba3a0daab70f1e91b0c2395e120ffe623a904338642cfbb0724')
  returning id
), o as (
