with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 30 de la Ley 39/2015, siempre que por ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días se entiende que son hábiles, excluyéndose del cómputo:', 'El art. 30.2 LPAC establece que los plazos por días son hábiles y excluye sábados, domingos y festivos; los días naturales solo se aplican si lo declara una ley o el Derecho de la UE.', 'gc_10a_procedimiento_administrativo', (select id from public.topics where slug = 'gc-10a-procedimiento-administrativo'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.2 LPAC', 'cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.', null, 'c11bbeb45172d747a9481b624a675d93ee2d77e9cffdcd3fa9876c863818940e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c11bbeb45172d747a9481b624a675d93ee2d77e9cffdcd3fa9876c863818940e')
  returning id
), o as (
