with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 47 de la Ley 39/2015, son nulos de pleno derecho los actos de las Administraciones Públicas:', 'El art. 47.1.b) LPAC sanciona con nulidad la incompetencia manifiesta por razón de la materia o del territorio; la infracción del ordenamiento con carácter general determina la anulabilidad (art. 48.1) y la actuación fuera de plazo solo invalida si lo impone la naturaleza del término (art. 48.3).', 'gc_10a_procedimiento_administrativo', (select id from public.topics where slug = 'gc-10a-procedimiento-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 47.1.b) LPAC', 'b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio.', null, '56af5f75ecd5aee776722b29a59539880064c2a229f227f895db714a7d848423', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '56af5f75ecd5aee776722b29a59539880064c2a229f227f895db714a7d848423')
  returning id
), o as (
