with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 de la Ley Orgánica 4/2015, de protección de la seguridad ciudadana, el Documento Nacional de Identidad:', 'El art. 8.1 LO 4/2015 configura el DNI como documento público y oficial y como el único con suficiente valor por sí solo para acreditar, a todos los efectos, la identidad y los datos personales de su titular.', 'gc_13_seguridad_publica_privada', (select id from public.topics where slug = 'gc-13-seguridad-publica-privada'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Art. 8.1 LOPSC', 'El Documento Nacional de Identidad es un documento público y oficial y tendrá la protección que a estos otorgan las leyes. Es el único documento con suficiente valor por sí solo para la acreditación, a todos los efectos, de la identidad y los datos personales de su titular.', null, 'c9254e66dcc63e1d5e5c695766d558b008da793866ff41197c264d21a3f8be39', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c9254e66dcc63e1d5e5c695766d558b008da793866ff41197c264d21a3f8be39')
  returning id
), o as (
