  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comparte con el pasaporte y el permiso de conducción el mismo valor para acreditar por sí solo la identidad a todos los efectos.', false), ('B', 'Es el único documento con suficiente valor por sí solo para la acreditación, a todos los efectos, de la identidad y los datos personales de su titular.', true), ('C', 'Es un documento privado de carácter oficial que solo acredita la nacionalidad de su titular.', false), ('D', 'Acredita la identidad de su titular solo cuando se acompaña del certificado de empadronamiento.', false)) as v(label, body, ok)
)
