with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad, la Seguridad Pública es:', 'El art. 1.1 LO 2/1986 declara la Seguridad Pública competencia exclusiva del Estado y atribuye su mantenimiento al Gobierno de la Nación; CCAA y Corporaciones Locales solo participan en él.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 1.1 LO 2/1986', '1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.', null, 'c8fb217c16dd30e29c0f68ac673028080259db5ba35a5919191dc7eae80dd52e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c8fb217c16dd30e29c0f68ac673028080259db5ba35a5919191dc7eae80dd52e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Competencia exclusiva del Estado, y su mantenimiento corresponde al Gobierno de la Nación.', true), ('B', 'Competencia compartida entre el Estado y las Comunidades Autónomas, y su mantenimiento corresponde al Ministerio del Interior.', false), ('C', 'Competencia exclusiva del Estado, y su mantenimiento corresponde a las Cortes Generales.', false), ('D', 'Competencia de las Comunidades Autónomas, y su mantenimiento corresponde a sus Cuerpos de Policía.', false)) as v(label, body, ok)
)
