with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 2 de la Ley Orgánica 2/1986, son Fuerzas y Cuerpos de Seguridad:', 'El art. 2 LO 2/1986 enumera tres grupos: las FCSE dependientes del Gobierno de la Nación, los Cuerpos de Policía de las Comunidades Autónomas y los de las Corporaciones Locales.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 2 LO 2/1986', 'Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales.', null, '66fcd7b42375fded091674c254d549324005e2a02da97209de6ca4de73473088', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '66fcd7b42375fded091674c254d549324005e2a02da97209de6ca4de73473088')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación.', false), ('B', 'Las Fuerzas y Cuerpos de Seguridad del Estado y los Cuerpos de Policía de las Comunidades Autónomas, pero no las Policías Locales.', false), ('C', 'Las Fuerzas y Cuerpos de Seguridad del Estado, los Cuerpos de Policía dependientes de las Comunidades Autónomas y los dependientes de las Corporaciones Locales.', true), ('D', 'Las Fuerzas y Cuerpos de Seguridad del Estado, las Policías Locales y el personal de seguridad privada.', false)) as v(label, body, ok)
)
