with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 de la Ley Orgánica 2/1986, en el ejercicio de sus funciones los miembros de las Fuerzas y Cuerpos de Seguridad se regirán, en la utilización de los medios a su alcance, por los principios de:', 'El art. 5.2.c) LO 2/1986 exige actuar con la decisión necesaria y sin demora cuando se trate de evitar un daño grave, inmediato e irreparable, rigiéndose por los principios de congruencia, oportunidad y proporcionalidad.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 5.2.c LO 2/1986', 'c) En el ejercicio de sus funciones deberán actuar con la decisión necesaria, y sin demora cuando de ello dependa evitar un daño grave, inmediato e irreparable; rigiéndose al hacerlo por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance.', null, '2f638af62c4f718af9361be69981f4687e566404bbe9dadde3c71b1a8e5e8f75', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2f638af62c4f718af9361be69981f4687e566404bbe9dadde3c71b1a8e5e8f75')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Jerarquía, subordinación y disciplina.', false), ('B', 'Eficacia, eficiencia y economía.', false), ('C', 'Necesidad, legalidad e igualdad.', false), ('D', 'Congruencia, oportunidad y proporcionalidad.', true)) as v(label, body, ok)
)
