with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 de la Ley Orgánica 2/1986, en el tratamiento de detenidos, los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales:', 'El art. 5.3.a) LO 2/1986 obliga a identificarse debidamente como miembro de las Fuerzas y Cuerpos de Seguridad en el momento de efectuar la detención.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 5.3.a LO 2/1986', 'a) Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales en el momento de efectuar una detención.', null, 'afd0f054a7c4ad2d621dadb81ce37d2be2358d291afdcd8257bea1591683286e', false
