with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 8 de la Ley Orgánica 2/1986, el cumplimiento de la prisión preventiva y de las penas privativas de libertad por los miembros de las Fuerzas y Cuerpos de Seguridad se realizará:', 'El art. 8.2 LO 2/1986 establece que lo cumplirán en establecimientos penitenciarios ordinarios, pero separados del resto de detenidos o presos.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 8.2 LO 2/1986', '2. El cumplimiento de la prisión preventiva y de las penas privativas de libertad por los miembros de las Fuerzas y Cuerpos de Seguridad, se realizarán en establecimientos penitenciarios ordinarios, con separación del resto de detenidos o presos.', null, '9f82ad2fa49709b1cea728f9794c01e3ccb77525a35df91dab5fcfe94b7c64c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9f82ad2fa49709b1cea728f9794c01e3ccb77525a35df91dab5fcfe94b7c64c4')
  returning id
), o as (
