insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-15b-personal-guardia-civil' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 5 de la Ley Orgánica 11/2007, reguladora de los derechos y deberes de los miembros de la Guardia Civil, a efectos del derecho a la inviolabilidad del domicilio, el pabellón que el guardia civil tuviera asignado en su unidad:', 'El art. 5.1 LO 11/2007 garantiza la intimidad, la inviolabilidad del domicilio y el secreto de las comunicaciones y precisa que el pabellón asignado en la unidad se considera domicilio habitual.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 5.1 LO 11/2007', 'A estos efectos el pabellón que tuviera asignado el Guardia Civil en su unidad se considerará domicilio habitual.', null, '1f328db01c4aa3cbefdcd48ebd9b6257d80dc22d0c110fac94484f54797e9975', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1f328db01c4aa3cbefdcd48ebd9b6257d80dc22d0c110fac94484f54797e9975')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No tendrá la consideración de domicilio, por tratarse de una dependencia oficial.', false), ('B', 'Se considerará domicilio solo cuando el guardia civil conviva en él con su familia.', false), ('C', 'Se considerará domicilio habitual.', true), ('D', 'Se considerará domicilio temporal, sujeto a registro por orden del jefe de la unidad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 de la Ley Orgánica 11/2007, el registro personal o de los efectos y pertenencias de un guardia civil en la unidad, cuando lo exija la investigación de un hecho delictivo:', 'El art. 5.2 LO 11/2007 atribuye la autorización al jefe de la unidad, centro u órgano, de forma expresamente motivada, y exige la asistencia del interesado y al menos un testigo.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 5.2 LO 11/2007', '2. El jefe de la unidad, centro u órgano donde el Guardia Civil preste sus servicios podrá autorizar, de forma expresamente motivada, el registro personal o de los efectos y pertenencias que estuvieren en los mismos, cuando lo exija la investigación de un hecho delictivo. El registro se realizará con la asistencia del interesado y en presencia de, al menos, un testigo.', null, 'd558435af48269dbc035c17f66053893592bae16d3e0c789876285d0fb225754', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd558435af48269dbc035c17f66053893592bae16d3e0c789876285d0fb225754')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo podrá autorizarlo el Juez de Instrucción, y se realizará en presencia del Secretario judicial.', false), ('B', 'Podrá autorizarlo verbalmente cualquier superior jerárquico, sin necesidad de testigos.', false), ('C', 'Podrá autorizarlo el jefe de la unidad, y se realizará en presencia de, al menos, dos testigos, aunque no asista el interesado.', false), ('D', 'Podrá autorizarlo el jefe de la unidad, centro u órgano de forma expresamente motivada, y se realizará con asistencia del interesado y en presencia de, al menos, un testigo.', true)) as v(label, body, ok)
)
