with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 6 de la Ley Orgánica 11/2007, los desplazamientos de los guardias civiles al extranjero:', 'El art. 6.2 LO 11/2007 exige comunicación previa a los superiores y aplica a esos desplazamientos las mismas limitaciones que a los realizados por territorio nacional.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 6.2 LO 11/2007', '2. Los Guardias Civiles deberán comunicar previamente a sus superiores los desplazamientos al extranjero, a los que se aplicarán las mismas limitaciones que a los desplazamientos por territorio nacional.', null, '5b2e922e55da313affdcdf20b8fcafadab64b7e815b8769aa5247134df6fbbdd', false
