with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 29/2014, de Régimen del Personal de la Guardia Civil, por la naturaleza militar del Instituto en el que se integran, los guardias civiles son:', 'El art. 3.1 de la Ley 29/2014 define a los guardias civiles como españoles vinculados por una relación de servicios profesionales permanente que, por la naturaleza militar del Instituto, son militares de carrera de la Guardia Civil.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 3.1 Ley 29/2014', '1. Son guardias civiles los españoles vinculados al Cuerpo de la Guardia Civil por una relación de servicios profesionales de carácter permanente como miembros de las Fuerzas y Cuerpos de Seguridad del Estado y que, por la naturaleza militar del Instituto en el que se integran, son militares de carrera de la Guardia Civil.', null, '2de5fee701342238eb3731681d5f349e5988bd988306ac5a129fb53a87cfc6f9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2de5fee701342238eb3731681d5f349e5988bd988306ac5a129fb53a87cfc6f9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Militares de carrera de la Guardia Civil.', true), ('B', 'Funcionarios civiles del Ministerio del Interior.', false), ('C', 'Militares de complemento.', false), ('D', 'Personal laboral de las Fuerzas Armadas.', false)) as v(label, body, ok)
)
