  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley 29/2014, los principios y normas de aplicación general al personal de la Administración General del Estado, establecidos de acuerdo con el Estatuto Básico del Empleado Público:', 'El art. 2.2 de la Ley 29/2014 incorpora los principios y normas generales del personal de la AGE al régimen de la Guardia Civil, siempre que no contradigan su legislación específica.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 2.2 Ley 29/2014', 'se incorporarán al régimen del personal de la Guardia Civil, siempre que no contradigan su legislación específica.', null, 'b838b9e3c59cbd9971d5d3a33a077bd565d153fb819c3ce6e8a20bcf519888c8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b838b9e3c59cbd9971d5d3a33a077bd565d153fb819c3ce6e8a20bcf519888c8')
  returning id
), o as (
