  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 21 de la Ley 29/2014, si la precedencia no está fijada en normas reglamentarias por el cargo o destino, se basará:', 'El art. 21.3 de la Ley 29/2014 ordena la precedencia por cargo o destino si está reglamentada; si no, por empleo, antigüedad en él y posición en el escalafón.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 21.3 Ley 29/2014', 'si no lo está, se basará en el empleo; a igualdad de empleo, en la antigüedad en el mismo y a igualdad de ésta se resolverá en función de la posición en el escalafón.', null, 'e155231f1f40792eb03a73b4e7a39cde1c4ef4e8acf0fcbe6cd5fff24da0d463', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e155231f1f40792eb03a73b4e7a39cde1c4ef4e8acf0fcbe6cd5fff24da0d463')
