with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 15 de la Ley 29/2014, la acción de mando:', 'El art. 15 de la Ley 29/2014 distingue acciones directivas (que incluyen las de mando), de gestión y ejecutivas; la de mando corresponde por razón de cargo, destino o servicio.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 15.3 Ley 29/2014', '3. La acción de mando es una acción directiva que se refiere al ejercicio de la autoridad y a la asunción de la consiguiente responsabilidad, y corresponde al guardia civil en razón de su cargo, destino o servicio.', null, '3d82356b8635bb57da309e53129d70c7ac8c2f1dfe640beddf6afdf1658668c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3d82356b8635bb57da309e53129d70c7ac8c2f1dfe640beddf6afdf1658668c4')
