  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 19 de la Ley 29/2014, cuando se designe a un guardia civil para un puesto en organizaciones internacionales que corresponda a un empleo superior al suyo, el empleo con carácter eventual podrá concederlo:', 'El art. 19.1 de la Ley 29/2014 atribuye la concesión al Ministro de Defensa a propuesta del Director General; se conceden atribuciones y divisas, pero no las retribuciones del empleo superior, y no genera derecho al ascenso.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 19.1 Ley 29/2014', 'el Ministro de Defensa, a propuesta del Director General de la Guardia Civil, le podrá conceder, con carácter eventual, dicho empleo con sus atribuciones y divisas, excepción hecha de las retribuciones que serán las correspondientes a su empleo efectivo.', null, '2b1ee4a0957a3e147fa3bed8adf20aa7f679fce83f299363a46671c8ec8fd06b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2b1ee4a0957a3e147fa3bed8adf20aa7f679fce83f299363a46671c8ec8fd06b')
