with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 1 de la Carta de Derechos de los Ciudadanos ante la Justicia, para garantizar el derecho a recibir información general y actualizada sobre el funcionamiento de los juzgados y tribunales se impulsará la creación y dotación material de:', 'El apartado 1 de la Carta, dentro de «Una justicia transparente», prevé impulsar Oficinas de Atención al Ciudadano en todo el territorio nacional y situar los horarios de atención al público en lugar visible.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 1 Carta', 'Se impulsará la creación y dotación material de Oficinas de Atención al Ciudadano, asegurando su implantación en todo el territorio nacional.', null, '9791bcd567004accf5689a93888eeeb11fdfad846f421c09bb4b47558b3e7f31', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9791bcd567004accf5689a93888eeeb11fdfad846f421c09bb4b47558b3e7f31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Oficinas de Asistencia a las Víctimas en cada partido judicial.', false), ('B', 'Servicios de Orientación Jurídica en cada Colegio de Abogados.', false), ('C', 'Puntos de información en las Gerencias Territoriales del Ministerio de Justicia.', false), ('D', 'Oficinas de Atención al Ciudadano, asegurando su implantación en todo el territorio nacional.', true)) as v(label, body, ok)
)
