with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Carta de Derechos de los Ciudadanos ante la Justicia, la información transparente sobre el estado, la actividad y los asuntos tramitados y pendientes de todos los órganos jurisdiccionales se canalizará para facilitar su consulta:', 'El apartado 2 de la Carta encomienda al Ministerio de Justicia, a las Comunidades Autónomas con competencias y al CGPJ canalizar esa información en el marco de un plan de transparencia; de ahí nace el Plan de Transparencia Judicial.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 2 Carta', 'El Ministerio de Justicia y las Comunidades Autónomas con competencias en la materia, así como el Consejo General del Poder Judicial canalizarán esta información para facilitar su consulta en el marco de un plan de transparencia.', null, '44acccbc66720ca89386b182136dab4291a561f9a974ccf7d724597598040be1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '44acccbc66720ca89386b182136dab4291a561f9a974ccf7d724597598040be1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el marco de un plan de transparencia.', true), ('B', 'A través de la memoria anual del Tribunal Supremo.', false), ('C', 'Mediante el Boletín Oficial del Estado.', false), ('D', 'Por medio de las Salas de Gobierno de los Tribunales Superiores de Justicia.', false)) as v(label, body, ok)
)
