with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 4 de la Carta de Derechos de los Ciudadanos ante la Justicia, cuando se deniegue el acceso a una información de carácter procesal, las autoridades y funcionarios:', 'La Carta reconoce el acceso de los interesados a documentos, libros, archivos y registros judiciales no reservados y obliga a exponer por escrito, a quien lo pida, los motivos por los que se deniega una información procesal.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 4 Carta', 'Las autoridades y funcionarios expondrán por escrito al ciudadano que lo solicite los motivos por los que se deniega el acceso a una información de carácter procesal.', null, '96cda791f0d731d4a0c05c6da4aad7051c8c9223f9404f6aa5fd214d4a607532', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '96cda791f0d731d4a0c05c6da4aad7051c8c9223f9404f6aa5fd214d4a607532')
