with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Carta de Derechos de los Ciudadanos ante la Justicia, las notificaciones, citaciones, emplazamientos y requerimientos deben:', 'El apartado 5, dentro de «Una justicia comprensible», exige términos sencillos y comprensibles en los actos de comunicación y evitar elementos intimidatorios innecesarios.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 5 Carta', 'El ciudadano tiene derecho a que las notificaciones, citaciones, emplazamientos y requerimientos contengan términos sencillos y comprensibles, evitándose el uso de elementos intimidatorios innecesarios.', null, '1bb5db0bc185b771886df3e03d8e43a09de9f6d68b93ef1dd90a7de4280aff42', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1bb5db0bc185b771886df3e03d8e43a09de9f6d68b93ef1dd90a7de4280aff42')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Redactarse siempre en las dos lenguas oficiales de la Comunidad Autónoma.', false), ('B', 'Contener términos sencillos y comprensibles, evitándose el uso de elementos intimidatorios innecesarios.', true), ('C', 'Ir acompañados de un formulario de respuesta gratuito.', false), ('D', 'Practicarse en todo caso por medios electrónicos.', false)) as v(label, body, ok)
)
