with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 6 de la Carta de Derechos de los Ciudadanos ante la Justicia, ¿quién velará por la salvaguardia del derecho a que en las vistas y comparecencias se utilice un lenguaje comprensible para quienes no son especialistas en derecho?', 'El apartado 6 reconoce el derecho a un lenguaje comprensible en vistas y comparecencias, respetando las exigencias técnicas, y atribuye su salvaguardia a los Jueces y Magistrados que dirigen el acto.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 6 Carta', 'Los Jueces y Magistrados que dirijan los actos procesales velarán por la salvaguardia de este derecho.', null, '1f355292e38729e3624b8e449820a791bae2f604c11fb6411bba6a0d36dd63d9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1f355292e38729e3624b8e449820a791bae2f604c11fb6411bba6a0d36dd63d9')
  returning id
), o as (
