with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al apartado 8 de la Carta de Derechos de los Ciudadanos ante la Justicia, el ciudadano tiene derecho a disponer gratuitamente de los formularios necesarios para el ejercicio de sus derechos ante los tribunales:', 'El apartado 8 limita el derecho a formularios gratuitos a los procedimientos en que no es preceptiva la intervención de Abogado y Procurador.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 8 Carta', 'El ciudadano tiene derecho a disponer gratuitamente de los formularios necesarios para el ejercicio de sus derechos ante los tribunales cuando no sea preceptiva la intervención de Abogado y Procurador.', null, '5f67f3e4886a24a114f3e42d400f9a057a1bf6eb48eb887dc1c78f6cff568353', false
