with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Carta de Derechos de los Ciudadanos ante la Justicia, la suspensión de una actuación procesal a la que estuviera convocado un ciudadano se le comunicará:', 'El apartado 10 (puntualidad) obliga al Juez o al Secretario Judicial (hoy Letrado de la Administración de Justicia) a informar de las razones del retraso o suspensión, y a comunicar esta con antelación suficiente para evitar el desplazamiento, salvo fuerza mayor.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 10 Carta', 'La suspensión se comunicará al ciudadano, salvo causa de fuerza mayor, con antelación suficiente para evitar su desplazamiento.', null, '3994fdb791aba28340eeebdcab54b88a3a852641065db0ead4d68dac6a0c3fc4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3994fdb791aba28340eeebdcab54b88a3a852641065db0ead4d68dac6a0c3fc4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todo caso, con una antelación mínima de cuarenta y ocho horas.', false), ('B', 'Al inicio de la sesión, en la propia sede judicial.', false), ('C', 'Por escrito, dentro de los tres días siguientes a la suspensión.', false), ('D', 'Salvo causa de fuerza mayor, con antelación suficiente para evitar su desplazamiento.', true)) as v(label, body, ok)
)
