with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 13 de la Carta de Derechos de los Ciudadanos ante la Justicia, el derecho a conocer la identidad y categoría de la autoridad o funcionario que atiende al ciudadano:', 'La identidad y categoría deben figurar en lugar visible del puesto y quien atiende por teléfono o vía telemática debe identificarse; la única salvedad son las razones de seguridad en causas criminales.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 13 Carta', 'El ciudadano tiene derecho a conocer la identidad y categoría de la autoridad o funcionario que le atienda, salvo cuando esté justificado por razones de seguridad en causas criminales.', null, '10a419e03ae9da4b541426130dfea65b62c30d81356912bd98261a363cb76aa2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '10a419e03ae9da4b541426130dfea65b62c30d81356912bd98261a363cb76aa2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No alcanza a quien atiende por teléfono o por vía telemática.', false), ('B', 'Solo puede ejercerse por escrito ante el Letrado de la Administración de Justicia.', false), ('C', 'Cede cuando esté justificado por razones de seguridad en causas criminales.', true), ('D', 'Se limita a los Jueces y Magistrados.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Carta de Derechos de los Ciudadanos ante la Justicia reconoce el derecho a ser atendido en horario de mañana y tarde:', 'El apartado 15 no generaliza el horario de tarde: lo vincula a los órganos en que resulte necesario por su naturaleza o volumen de asuntos.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 15 Carta', 'El ciudadano tiene derecho a ser atendido en horario de mañana y tarde en las dependencias judiciales de aquellos órganos en los que, por su naturaleza o volumen de asuntos, resulte necesario y en los términos legalmente previstos.', null, 'ed218bcc3bc61f89f06558ef3f94be816b8cc76d3606ef9aef989f246e3878ff', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ed218bcc3bc61f89f06558ef3f94be816b8cc76d3606ef9aef989f246e3878ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todas las dependencias judiciales sin excepción.', false), ('B', 'Solo en las Oficinas de Atención al Ciudadano y en los Juzgados de Guardia.', false), ('C', 'Únicamente cuando el ciudadano no esté asistido por Abogado.', false), ('D', 'En las dependencias judiciales de aquellos órganos en los que, por su naturaleza o volumen de asuntos, resulte necesario y en los términos legalmente previstos.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Carta de Derechos de los Ciudadanos ante la Justicia, el ciudadano que formule reclamaciones, quejas o sugerencias sobre el incorrecto funcionamiento de la Administración de Justicia tiene derecho a recibir respuesta con la mayor celeridad y, en todo caso:', 'El apartado 17 fija el plazo máximo de respuesta en un mes; el Plan de Transparencia Judicial recuerda ese mismo plazo.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 17 Carta', 'El ciudadano tiene derecho a formular reclamaciones, quejas y sugerencias relativas al incorrecto funcionamiento de la Administración de Justicia, así como a recibir respuesta a las mismas con la mayor celeridad y, en todo caso, dentro del plazo de un mes.', null, 'cdfe05085a4cdd681c6fd06c16e0f93a8999b29e241406ba1b2d73e4386943e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cdfe05085a4cdd681c6fd06c16e0f93a8999b29e241406ba1b2d73e4386943e8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dentro del plazo de quince días.', false), ('B', 'Dentro del plazo de un mes.', true), ('C', 'Dentro del plazo de tres meses.', false), ('D', 'Dentro del plazo de diez días hábiles.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 17 de la Carta de Derechos de los Ciudadanos ante la Justicia, ¿ante cuál de los siguientes NO se menciona expresamente la posibilidad de presentar quejas y sugerencias?', 'La Carta enumera el propio Juzgado o Tribunal, sus órganos de gobierno, las Oficinas de Atención al Ciudadano, el CGPJ, el Ministerio de Justicia y, en su caso, las Administraciones autonómicas. El Defensor del Pueblo no aparece en esa lista.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 17 Carta', 'Podrá presentar las quejas y sugerencias ante el propio Juzgado o Tribunal, sus órganos de gobierno, las Oficinas de Atención al Ciudadano, el Consejo General del Poder Judicial, el Ministerio de Justicia y, en su caso, ante las Administraciones de las Comunidades Autónomas.', null, '05f4a178e29a770d4f7bdd4263c2e08bac6a1a64232a587241a91a99682b60f1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '05f4a178e29a770d4f7bdd4263c2e08bac6a1a64232a587241a91a99682b60f1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Defensor del Pueblo.', true), ('B', 'El propio Juzgado o Tribunal y sus órganos de gobierno.', false), ('C', 'Las Oficinas de Atención al Ciudadano.', false), ('D', 'El Consejo General del Poder Judicial y el Ministerio de Justicia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El apartado 18 de la Carta de Derechos de los Ciudadanos ante la Justicia reconoce el derecho a exigir responsabilidades por:', 'El apartado 18 se refiere al error judicial y al funcionamiento anormal; los daños dan lugar a indemnización conforme a la Ley y las reclamaciones se tramitan con preferencia y celeridad.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 18 Carta', 'El ciudadano tiene derecho a exigir responsabilidades por error judicial o por el funcionamiento anormal de la Administración de Justicia. […] Las reclamaciones indemnizatorias se tramitarán con preferencia y celeridad.', null, 'bdfb871c7deee900fc869949b1023f308a279a281edeeb6deea256156a3c453b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bdfb871c7deee900fc869949b1023f308a279a281edeeb6deea256156a3c453b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Error judicial o funcionamiento anormal de la Administración de Justicia, tramitándose las reclamaciones indemnizatorias con preferencia y celeridad.', true), ('B', 'Cualquier resolución judicial que haya sido revocada en apelación.', false), ('C', 'Las dilaciones causadas por los Abogados y Procuradores de la parte contraria.', false), ('D', 'El retraso en la notificación de cualquier diligencia de ordenación.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Carta de Derechos de los Ciudadanos ante la Justicia, el programa de previsiones con la duración debida de los distintos procedimientos en todos los órdenes jurisdiccionales lo elaborarán:', 'El apartado 19 (tramitación ágil) encarga al Ministerio de Justicia y al CGPJ un programa de previsiones de duración de los procedimientos, con amplia difusión pública.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 19 Carta', 'El Ministerio de Justicia y el Consejo General del Poder Judicial elaborarán un programa de previsiones con la duración debida de los distintos procedimientos en todos los órdenes jurisdiccionales, al cual se dará una amplia difusión pública.', null, '733f398e4f5347fd0f057b2f7e79f5ca4dff1f2d4f7c73d0b47abaec3a301732', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '733f398e4f5347fd0f057b2f7e79f5ca4dff1f2d4f7c73d0b47abaec3a301732')
  returning id
), o as (
