with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al apartado 20 de la Carta de Derechos de los Ciudadanos ante la Justicia, el ciudadano tiene derecho a que no se le exija la aportación de documentos que obren en poder de las Administraciones Públicas:', 'El apartado 20 exime de aportar documentos que ya tengan las Administraciones Públicas, con la única excepción de que lo exijan expresamente las leyes procesales.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 20 Carta', 'El ciudadano tiene derecho a que no se le exija la aportación de documentos que obren en poder de las Administraciones Públicas, salvo que las leyes procesales expresamente lo requieran.', null, '9f669a5f0582f0ba880f06ea3a0e016612638e0f1a4b3cbaebe613f4c6d206de', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9f669a5f0582f0ba880f06ea3a0e016612638e0f1a4b3cbaebe613f4c6d206de')
