)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Carta de Derechos de los Ciudadanos ante la Justicia, para que la comparecencia de la víctima de un delito sea adecuada a su dignidad y preserve su intimidad:', 'El apartado 23 prevé evitar la coincidencia con el agresor en las dependencias judiciales y encarga especial celo en los supuestos de violencia doméstica o de género.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 23 Carta', 'Se adoptarán las medidas necesarias para que la víctima no coincida con el agresor cuando ambos se encuentren en dependencias judiciales a la espera de la práctica de cualquier actuación procesal.', null, '748d1a45b5acb1c20ab16eca32fe2be10d421e0877237c16cabb54f70c73bb6f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '748d1a45b5acb1c20ab16eca32fe2be10d421e0877237c16cabb54f70c73bb6f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La víctima declarará siempre por videoconferencia.', false), ('B', 'Se adoptarán las medidas necesarias para que la víctima no coincida con el agresor cuando ambos esperen en dependencias judiciales.', true), ('C', 'Se celebrarán a puerta cerrada todos los juicios en que intervenga una víctima.', false), ('D', 'La víctima podrá negarse a comparecer en cualquier caso.', false)) as v(label, body, ok)
)
