select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Carta de Derechos de los Ciudadanos ante la Justicia, ¿quién velará por la efectividad del derecho del menor con suficiente juicio a ser oído en todo proceso judicial en que esté directamente implicado?', 'El apartado 27 atribuye al Ministerio Fiscal velar por el derecho del menor a ser oído y prestarle la asistencia que necesite.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 27 Carta', 'El Ministerio Fiscal velará por la efectividad de este derecho, prestando al menor la asistencia que necesite.', null, '71adb732e63c183a24486be017b8bb445146a2615953b88c984a24fb88121d57', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '71adb732e63c183a24486be017b8bb445146a2615953b88c984a24fb88121d57')
