)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 30 de la Carta de Derechos de los Ciudadanos ante la Justicia, cuando el destinatario de un acto de comunicación sea una persona sorda, muda o con discapacidad visual o ceguera:', 'Además del derecho a intérprete de signos o medios tecnológicos, la Carta exige comprobar con especial cuidado el conocimiento efectivo del acto y, si procede, leerlo en voz alta.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 30 Carta', 'Se comprobará con especial cuidado que el acto de comunicación ha llegado a conocimiento efectivo de su destinatario y, en su caso, se procederá a la lectura en voz alta del contenido del acto.', null, '989ddbac905b87994bfd7329cd4e8488e533999c25aad00e896035f791a7a576', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '989ddbac905b87994bfd7329cd4e8488e533999c25aad00e896035f791a7a576')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El acto se practicará necesariamente por edictos.', false), ('B', 'Deberá entenderse siempre con su representante legal.', false), ('C', 'Se suspenderá el acto hasta que comparezca con un intérprete de su elección.', false), ('D', 'Se comprobará con especial cuidado que el acto ha llegado a su conocimiento efectivo y, en su caso, se leerá en voz alta su contenido.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
