with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Carta de Derechos de los Ciudadanos ante la Justicia, para garantizar el derecho a conocer anticipadamente el coste aproximado de la intervención del profesional y la forma de pago, los Abogados y Procuradores están obligados a:', 'El apartado 37 obliga a entregar un presupuesto previo y fomenta las hojas de encargo profesional; además el cliente puede exigir a su Procurador rendición de cuentas.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Apdo. 37 Carta', 'Los Abogados y Procuradores estarán obligados a entregar a su cliente un presupuesto previo que contenga los anteriores extremos.', null, '72965ea4554a90cf03dc9c5f1725ff046d42ef322f837d514bbe766194331742', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '72965ea4554a90cf03dc9c5f1725ff046d42ef322f837d514bbe766194331742')
  returning id
