)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado de «Eficacia de la Carta de Derechos», el seguimiento y evaluación permanente del desarrollo y cumplimiento de la Carta corresponde:', 'La Carta encomienda su seguimiento al Congreso (Comisión de Justicia e Interior), que será informado por el Gobierno y los órganos e instituciones; la memoria anual del CGPJ debe incluir una referencia detallada a quejas, reclamaciones y sugerencias.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Eficacia 3 Carta', 'El Congreso de los Diputados, a través de la Comisión de Justicia e Interior, llevará a cabo un seguimiento y evaluación permanente del desarrollo y cumplimiento de esta Carta', null, 'e7e7d8825dc93af99446d9c595738a83d12ec8c0c5b41c804bf9022ce96fed68', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e7e7d8825dc93af99446d9c595738a83d12ec8c0c5b41c804bf9022ce96fed68')
  returning id
), o as (
