with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, cuando un Juez o Tribunal encomienda la práctica de una diligencia a otro Juez o Tribunal superior en grado, empleará la forma de:', 'El art. 184 LECrim distingue: suplicatorio al superior en grado, exhorto al de igual grado y mandamiento o carta-orden al subordinado.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 184 LECrim', 'Empleará la forma del suplicatorio cuando se dirija a un Juez o Tribunal superior en grado; la de exhorto, cuando se dirija a uno de igual grado, y la de mandamiento o carta-orden, cuando se dirija a un subordinado suyo.', null, '4503ec5af2bfb31b76c5e6a2b4f5cabdc2b3451423790d827d0bf62714db9eed', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4503ec5af2bfb31b76c5e6a2b4f5cabdc2b3451423790d827d0bf62714db9eed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suplicatorio.', true), ('B', 'Exhorto.', false), ('C', 'Mandamiento o carta-orden.', false), ('D', 'Oficio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, los exhortos a Tribunales extranjeros se dirigirán:', 'El art. 193 LECrim ordena la vía diplomática conforme a los tratados o, en su defecto, a las disposiciones generales del Gobierno; en cualquier otro caso rige la reciprocidad.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 193 LECrim', 'Los exhortos a Tribunales extranjeros se dirigirán por la vía diplomática, en la forma establecida en los tratados, y a falta de éstos, en la que determinen las disposiciones generales del Gobierno.', null, '6f081b88b56b58cfc4d931c81b518a67fedc624999df6153b990107a4e7132bd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6f081b88b56b58cfc4d931c81b518a67fedc624999df6153b990107a4e7132bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Directamente al Tribunal extranjero por correo certificado, en todo caso.', false), ('B', 'Por la vía diplomática, en la forma establecida en los tratados y, a falta de estos, en la que determinen las disposiciones generales del Gobierno.', true), ('C', 'Por medio de la parte interesada, que deberá presentarlos en el plazo que se le fije.', false), ('D', 'A través del Consejo General del Poder Judicial, en todo caso.', false)) as v(label, body, ok)
)
