with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 189 de la Ley de Enjuiciamiento Criminal, la persona a quien se entregue un exhorto para su presentación deberá presentarlo, en el término fijado, ante el órgano encargado de cumplirlo y:', 'El art. 189 LECrim obliga al presentante a presentar el despacho en el término fijado y avisar acto continuo al órgano de procedencia.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 189 LECrim', 'La persona que reciba los documentos los presentará, en el término que se le hubiese fijado, al Juez o Tribunal a quien se haya encomendado el cumplimiento, dando aviso, acto continuo, de haberlo hecho así, al Juez o Tribunal de quien procedan.', null, '9cdf66dfe124153c84e7021894233ec9bd0035a716c5211889cd623e5feaa8e3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9cdf66dfe124153c84e7021894233ec9bd0035a716c5211889cd623e5feaa8e3')
