with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 185 de la Ley de Enjuiciamiento Criminal, el Juez o Tribunal que haya ordenado una diligencia y deba practicarse ante un órgano de categoría o grado inferior que no le esté subordinado:', 'El art. 185 LECrim impide dirigirse a órganos inferiores no subordinados; la comunicación debe hacerse con el superior de estos que ejerza jurisdicción en el mismo grado.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 185 LECrim', 'El Juez o Tribunal que haya ordenado la práctica de una diligencia judicial no podrá dirigirse a Jueces o Tribunales de categoría o grado inferior que no le estuvieren subordinados, debiendo entenderse directamente con el superior de éstos que ejerza la jurisdicción en el mismo grado que él.', null, 'e291f391d20cfe511942f106c5427149d6263f9825fd53cef9996a0241f48b51', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e291f391d20cfe511942f106c5427149d6263f9825fd53cef9996a0241f48b51')
  returning id
), o as (
