with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 188 de la Ley de Enjuiciamiento Criminal, los suplicatorios, exhortos o mandamientos en causas por delitos que no sean de los perseguibles solo por querella privada:', 'En las causas por delitos públicos, el despacho se expide de oficio y lo cursa directamente el órgano que lo libra.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 188 LECrim', 'Los suplicatorios, exhortos o mandamientos en causas en que se persigan delitos que no sean de los que sólo por querella privada pueden ser perseguidos, se expedirán de oficio y se cursarán directamente para su cumplimiento por el Juez o Tribunal que los hubiere librado.', null, '8c4f173937de8382561517d81740d2789e56ab9f49dea3f0f0633d45db42a75f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8c4f173937de8382561517d81740d2789e56ab9f49dea3f0f0633d45db42a75f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
