)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Criminal, los exhortos que procedan de causas por delitos que solo pueden ser perseguidos en virtud de querella particular:', 'En los delitos privados, el art. 188 LECrim permite entregar el despacho al interesado o su representante, bajo recibo y con término para presentarlo.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 188 LECrim', 'Los que procedan de causas por delitos que sólo pueden ser perseguidos en virtud de querella particular, podrán entregarse bajo recibo al interesado o a su representante a cuya instancia se libraren, fijándole término para presentarlos a quien deba cumplirlos.', null, '41145a03a34a593688bcbb0f189111d385281f21faaab6a09077de585f43a533', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '41145a03a34a593688bcbb0f189111d385281f21faaab6a09077de585f43a533')
