insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 189 de la Ley de Enjuiciamiento Criminal, cuando el interesado presente el exhorto ante el órgano encargado de cumplirlo, el funcionario correspondiente:', 'El art. 189 LECrim exige diligencia de presentación, recibo al presentante, firma de ambos y dar cuenta al Juez o Tribunal en el mismo día o, si no es posible, en el siguiente.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 189 LECrim', 'Al verificar la presentación, el funcionario correspondiente extenderá diligencia a continuación del suplicatorio, exhorto o carta-orden, expresando la fecha de su entrega y la persona que lo hubiese presentado, a la que dará recibo, firmando ambos la diligencia.', null, '887a675908e32148f806f65f70b0f30fe7f1dadd353f3f126a2732dbedf0715b', false
