with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley reguladora de la jurisdicción social, las resoluciones procesales se notificarán a todos los que sean parte en el juicio:', 'El art. 54.1 LRJS exige notificar el mismo día de la fecha o publicación y, si no es posible, el día hábil siguiente.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 54.1 LRJS', 'Las resoluciones procesales se notificarán en el mismo día de su fecha, o de la publicación en su caso, a todos los que sean parte en el juicio, y no siendo posible en el día hábil siguiente.', null, 'bc941da86de1ddb6140145f041716577aa88bf132e2d05e9b48cba8823cc7b49', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bc941da86de1ddb6140145f041716577aa88bf132e2d05e9b48cba8823cc7b49')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dentro de los tres días hábiles siguientes a su fecha.', false), ('B', 'Dentro de los cinco días siguientes a su firmeza.', false), ('C', 'En el plazo máximo de diez días desde que se dictaron.', false), ('D', 'En el mismo día de su fecha, o de la publicación en su caso, y no siendo posible en el día hábil siguiente.', true)) as v(label, body, ok)
)
