with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 54 de la Ley reguladora de la jurisdicción social, si la notificación inmediata de una medida cautelar, preventiva o ejecutiva pudiera poner en peligro su efectividad, el órgano judicial podrá:', 'El art. 54.3 LRJS permite demorar, de forma motivada y por el tiempo indispensable, la notificación cuando la inmediata pondría en peligro la efectividad de la medida.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 54.3 LRJS', 'el órgano judicial podrá, motivadamente, acordar la demora en la práctica de la notificación durante el tiempo indispensable para lograr dicha efectividad.', null, '294d1d2d72c54edb56cde957890d92b3331c9fa2d5f0e03337937d03b0fa7ddf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '294d1d2d72c54edb56cde957890d92b3331c9fa2d5f0e03337937d03b0fa7ddf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Omitir definitivamente la notificación al afectado.', false), ('B', 'Acordar motivadamente la demora en la práctica de la notificación durante el tiempo indispensable para lograr dicha efectividad.', true), ('C', 'Sustituir la notificación por la publicación de un edicto.', false), ('D', 'Notificarla únicamente al Ministerio Fiscal.', false)) as v(label, body, ok)
)
