with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 55 de la Ley reguladora de la jurisdicción social, las citaciones, notificaciones, emplazamientos y requerimientos a las partes que no actúen representadas se harán:', 'Para las partes no representadas, el art. 55 LRJS prevé la oficina judicial si comparecen y, si no, el domicilio señalado; para los obligados a relacionarse electrónicamente se aplica el art. 162 LEC.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 55 LRJS', 'Las citaciones, notificaciones, emplazamientos y requerimientos a las partes que no actúen representadas en los términos del artículo 18 de esta ley, se harán en el local de la oficina judicial, si allí comparecieren por propia iniciativa los interesados, o por haber sido emplazados para ello y, en otro caso, en el domicilio señalado a estos efectos.', null, '293245b28ff5cd056ede45c54f17d23b963dafd3777560a2e75dfda6019acfdd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '293245b28ff5cd056ede45c54f17d23b963dafd3777560a2e75dfda6019acfdd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre por medios electrónicos a través de la sede judicial electrónica.', false), ('B', 'En el local de la oficina judicial, si allí comparecieren los interesados, y, en otro caso, en el domicilio señalado a estos efectos.', true), ('C', 'Exclusivamente en el domicilio que conste en el padrón municipal.', false), ('D', 'En el domicilio del graduado social o abogado que les asesore.', false)) as v(label, body, ok)
)
