select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley reguladora de la jurisdicción social, las citaciones, notificaciones y emplazamientos que se practiquen fuera de la sede de la oficina judicial se harán, cualquiera que sea el destinatario:', 'El art. 56.1 LRJS establece como regla el correo certificado con acuse de recibo; el secretario (hoy LAJ) da fe del contenido del sobre y se une el acuse a los autos.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 56.1 LRJS', 'Las citaciones, notificaciones y emplazamientos que se practiquen fuera de la sede de la oficina judicial se harán, cualquiera que sea el destinatario, por correo certificado con acuse de recibo, dando fe el secretario en los autos del contenido del sobre remitido', null, '4f2f91c0eccd02c674c58bc099ec928cf1fc7ea7652cf04ff39138e145bfe693', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4f2f91c0eccd02c674c58bc099ec928cf1fc7ea7652cf04ff39138e145bfe693')
  returning id
), o as (
