select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 56 de la Ley reguladora de la jurisdicción social, en el documento de acuse de recibo de la comunicación remitida por correo certificado se hará constar:', 'El acuse de recibo recoge la fecha de entrega y lleva la firma del empleado de Correos y del receptor; si el receptor no es el interesado, se consignan su nombre, documento, domicilio y relación con el destinatario.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 56.3 LRJS', 'En el documento de acuse de recibo se hará constar la fecha de la entrega, y será firmado por el empleado de Correos y el receptor.', null, '01cdbd6f0fb91dcf595661ae38ef1628ae0ed4a9c0cd4fd77218563417dec1d0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '01cdbd6f0fb91dcf595661ae38ef1628ae0ed4a9c0cd4fd77218563417dec1d0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo la firma del receptor.', false), ('B', 'La fecha de la resolución notificada y la firma del Letrado de la Administración de Justicia.', false), ('C', 'La fecha de la entrega, y será firmado por el empleado de Correos y el receptor.', true), ('D', 'La hora de la entrega y el sello de la oficina de Correos, sin firma.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con las personas legalmente obligadas a relacionarse electrónicamente con la Administración de Justicia, el artículo 56.5 de la Ley reguladora de la jurisdicción social establece que:', 'El art. 56.5 LRJS (redacción del RDL 6/2023) remite al art. 162 LEC y prohíbe en el orden social obligar contractualmente al trabajador a relacionarse electrónicamente.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 56.5 LRJS', 'la comunicación se realizará conforme a lo establecido en el artículo 162 de la Ley 1/2000, de 7 de enero, sin que quepa en el orden jurisdiccional social la posibilidad de obligar contractualmente al trabajador a dicha relación electrónica.', null, '8c1caf5781afff03957b0ac46720c3fbdc68353734402e3798c8eac74a5206d1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8c1caf5781afff03957b0ac46720c3fbdc68353734402e3798c8eac74a5206d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La comunicación se realizará conforme al artículo 162 de la LEC, sin que quepa obligar contractualmente al trabajador a dicha relación electrónica.', true), ('B', 'El trabajador podrá ser obligado por contrato a relacionarse electrónicamente con el juzgado.', false), ('C', 'La comunicación electrónica solo será válida si el destinatario la acepta expresamente en el plazo de diez días.', false), ('D', 'Se aplicará supletoriamente la Ley 39/2015, del Procedimiento Administrativo Común.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 57 de la Ley reguladora de la jurisdicción social, si el destinatario de una cédula no fuese hallado en su domicilio, se entregará:', 'El art. 57.1 LRJS permite la entrega a parientes, familiares o empleados mayores de catorce años presentes en el domicilio y, en su defecto, al portero o conserje.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 57.1 LRJS', 'si no fuese hallado se entregará aquélla al pariente más cercano o familiar o empleado, mayores de catorce años, que se hallaren en el domicilio y, en su defecto, a quien desempeñe funciones de portería o conserjería de la finca.', null, 'a1c1b387302ef3eb0cedfe685aa74f03705c67ca7c82fdec117b00f0975b2dae', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a1c1b387302ef3eb0cedfe685aa74f03705c67ca7c82fdec117b00f0975b2dae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A cualquier vecino mayor de edad que se comprometa a entregarla.', false), ('B', 'Al pariente más cercano mayor de dieciocho años, y en su defecto se devolverá al órgano judicial.', false), ('C', 'A la Policía Local del municipio para su entrega posterior.', false), ('D', 'Al pariente más cercano o familiar o empleado, mayores de catorce años, que se hallaren en el domicilio y, en su defecto, a quien desempeñe funciones de portería o conserjería.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario del Cuerpo de Auxilio Judicial entrega una cédula de citación a la hermana del demandado, que se encuentra en el domicilio. Conforme al artículo 57 de la Ley reguladora de la jurisdicción social, se le advertirá de que, si se niega a la recepción o no hace la entrega a la mayor brevedad, puede ser sancionada con multa de:', 'El art. 57.3 LRJS obliga a advertir al receptor de su deber público, de la multa de 20 a 200 euros, de que debe comunicar la imposibilidad de entrega y de su derecho al resarcimiento de gastos.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 57.3 LRJS', 'con advertencia de que puede ser sancionado con multa de veinte a doscientos euros si se niega a la recepción o no hace la entrega a la mayor brevedad', null, 'f6d21629edcc20b6f2122dc708df1cfb6c07a888eeb31977e6346f481b1a8e0e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f6d21629edcc20b6f2122dc708df1cfb6c07a888eeb31977e6346f481b1a8e0e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sesenta a seiscientos euros.', false), ('B', 'Veinte a doscientos euros.', true), ('C', 'Cien a mil euros.', false), ('D', 'Ciento ochenta a seis mil euros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley reguladora de la jurisdicción social, ¿es necesario constituirse en el domicilio del interesado para entregar la copia de la resolución o la cédula a las personas que pueden recibirla en su lugar?', 'El art. 57.2 LRJS permite la entrega sin constituirse en el domicilio a cualquiera de las personas del apartado 1 y a quien, por su relación con el destinatario, garantice el cumplimiento.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 57.2 LRJS', 'Sin necesidad de constituirse en el domicilio del interesado o interesada, se podrá entregar la copia de la resolución o la cédula a cualquiera de las personas antes mencionadas, así como a quien por su relación con el destinatario pueda garantizar el eficaz cumplimiento del acto de comunicación.', null, '00075749a8aa1d096bbf2dfe9ca0bb0f855be29fa9be5e76ca63d9178bff241d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '00075749a8aa1d096bbf2dfe9ca0bb0f855be29fa9be5e76ca63d9178bff241d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, en todo caso, bajo pena de nulidad.', false), ('B', 'Solo es innecesario si el destinatario es una persona jurídica.', false), ('C', 'No; puede entregarse sin necesidad de constituirse en el domicilio, también a quien por su relación con el destinatario pueda garantizar el eficaz cumplimiento del acto.', true), ('D', 'Solo es innecesario con autorización expresa del juez.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes NO es uno de los requisitos que deben contener las cédulas según el artículo 58 de la Ley reguladora de la jurisdicción social?', 'El art. 58.1 LRJS exige: órgano o LAJ que dictó la resolución, fecha y asunto; nombre y apellidos del citado; objeto; lugar, día y hora o plazo; prevención de perjuicio; y fecha de expedición y firma. No interviene la parte contraria.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 58.1 LRJS', 'c) El objeto de la citación o emplazamiento. d) Lugar, día y hora en que deba comparecer el citado, o el plazo dentro del cual deba realizarse la actuación a que se refiera el emplazamiento. e) La prevención de que si no comparece le parará el perjuicio a que hubiere lugar en derecho.', null, '29676cf399212cc9e4e257e12ec73d57d3718c36fc3ae98cd6e7a10fe14ec004', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '29676cf399212cc9e4e257e12ec73d57d3718c36fc3ae98cd6e7a10fe14ec004')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La firma del abogado o graduado social de la parte contraria.', true), ('B', 'El objeto de la citación o emplazamiento.', false), ('C', 'Lugar, día y hora en que deba comparecer el citado, o el plazo de la actuación.', false), ('D', 'La prevención de que si no comparece le parará el perjuicio a que hubiere lugar en derecho.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 58 de la Ley reguladora de la jurisdicción social, la entrega de la copia de la resolución o de la cédula se documentará por medio de:', 'La diligencia de entrega recoge fecha, destinatario, nombre y firma de quien recibe (con su documento, domicilio y relación si no es el interesado) y la firma del funcionario o encargado.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 58.2 LRJS', 'La entrega de la copia de la resolución o de la cédula se documentará por medio de diligencia en la que se hará constar: […] d) Firma del funcionario o encargado de documentar la entrega.', null, '6d9ef573d000fd3c2c1f19bb890fa23c3ca46b07c780e2aa5a7fb0c9ef5c410c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6d9ef573d000fd3c2c1f19bb890fa23c3ca46b07c780e2aa5a7fb0c9ef5c410c')
  returning id
