)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 59 de la Ley reguladora de la jurisdicción social, si resultan infructuosas las averiguaciones del domicilio, el Letrado de la Administración de Justicia podrá dirigirse para comprobar si el demandado consta en él:', 'El art. 59.2 LRJS permite consultar el Registro Central de Rebeldes Civiles; si los datos coinciden, el LAJ acuerda la comunicación edictal por diligencia de ordenación. La comunicación edictal se rige por el art. 164 LEC.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 59.2 LRJS', 'el letrado o letrada de la Administración de Justicia podrá dirigirse al Registro Central de Rebeldes Civiles para comprobar si el demandado consta en dicho Registro y si los datos que en él aparecen son los mismos de que dispone. En tal caso el letrado o letrada de la Administración de Justicia dictará diligencia de ordenación acordando directamente la comunicación edictal del interesado.', null, '9d76d5a002b9e982e540672a6e2f93860af3e57c4728a25e31216b586fd3a346', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d76d5a002b9e982e540672a6e2f93860af3e57c4728a25e31216b586fd3a346')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Registro Central de Penados, y en tal caso dictará decreto acordando la suspensión del proceso.', false), ('B', 'Al Registro Mercantil, y en tal caso dará cuenta al juez para que dicte auto.', false), ('C', 'Al Registro Civil, y en tal caso archivará las actuaciones.', false), ('D', 'Al Registro Central de Rebeldes Civiles, y en tal caso dictará diligencia de ordenación acordando directamente la comunicación edictal.', true)) as v(label, body, ok)
)
