)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 60 de la Ley reguladora de la jurisdicción social, en las notificaciones, citaciones y emplazamientos la respuesta del interesado:', 'El art. 60.1 LRJS distingue: en notificaciones, citaciones y emplazamientos no se admite respuesta (salvo que lo mande la resolución); en los requerimientos sí, de forma sucinta.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 60.1 LRJS', 'En las notificaciones, citaciones y emplazamientos no se admitirá ni consignará respuesta alguna del interesado, a no ser que se hubiera mandado en la resolución. En los requerimientos se admitirá la respuesta que diera el requerido, consignándolo sucintamente en la diligencia.', null, '9ded7a579950f2d2e7e6591893f7318ce4f8c80dcf80a83e4377767712dacd75', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9ded7a579950f2d2e7e6591893f7318ce4f8c80dcf80a83e4377767712dacd75')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No se admitirá ni consignará, a no ser que se hubiera mandado en la resolución; en los requerimientos sí se admitirá, consignándola sucintamente.', true), ('B', 'Se consignará siempre íntegramente en la diligencia.', false), ('C', 'Se admitirá solo si se formula por escrito en el plazo de tres días.', false), ('D', 'Solo se admitirá en los emplazamientos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley reguladora de la jurisdicción social, cuando los actos de comunicación deban entenderse con una persona jurídica se practicarán, en su caso:', 'El art. 60.2 LRJS permite comunicar con la persona jurídica en sus delegaciones, sucursales, representaciones o agencias en la población del órgano judicial.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 60.2 LRJS', 'Cuando los actos de comunicación deban entenderse con una persona jurídica se practicarán, en su caso, en las delegaciones, sucursales, representaciones o agencias establecidas en la población donde radique el juzgado o tribunal que conozca del asunto, aunque carezcan de poder para comparecer en juicio las personas que estén al frente de las mismas.', null, '6480b29cdabad05fa1ab3ad4cb91ff9456b95379eec832d4e606dae30231018d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6480b29cdabad05fa1ab3ad4cb91ff9456b95379eec832d4e606dae30231018d')
