)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 60.3 de la Ley reguladora de la jurisdicción social, los actos de comunicación al Ministerio Fiscal o a la Abogacía del Estado efectuados por los medios y con los requisitos del artículo 162.1 de la LEC se tendrán por realizados:', 'El art. 60.3 LRJS dispone que esas comunicaciones se tienen por realizadas el día siguiente a la fecha de recepción que conste en la diligencia o resguardo.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 60.3 LRJS', 'se tendrán por realizados el día siguiente a la fecha de recepción que conste en la diligencia o en el resguardo acreditativo de su recepción', null, 'db879e9d664362b8b70ad04368b9194d1cdfaeb28a882aa013fc6a137d8c95d7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'db879e9d664362b8b70ad04368b9194d1cdfaeb28a882aa013fc6a137d8c95d7')
  returning id
), o as (
