)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley reguladora de la jurisdicción social, cuando se trate de comités de empresa, los actos de comunicación se entenderán con:', 'El art. 60.4 LRJS dirige las diligencias al presidente o secretario del comité de empresa y, en su defecto, a cualquiera de sus miembros.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 60.4 LRJS', 'Cuando se trate de comités de empresa, las diligencias antedichas se entenderán con su presidente o secretario y, en su defecto, con cualquiera de sus miembros.', null, '70c6932ea8d8e44544a8798eaf33f6b6e058cb3527e63731dbc5369588dde670', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '70c6932ea8d8e44544a8798eaf33f6b6e058cb3527e63731dbc5369588dde670')
