)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 61 de la Ley reguladora de la jurisdicción social, una notificación practicada sin ajustarse a lo dispuesto en la ley es nula; no obstante, surtirá efecto:', 'El art. 61 LRJS sanciona con nulidad las comunicaciones irregulares, pero las convalida desde que el interesado se da por enterado o consta su conocimiento suficiente de los elementos esenciales.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 61 LRJS', 'No obstante, si el interesado se hubiere dado por enterado o constara de forma suficiente su conocimiento procesal o extraprocesal de los elementos esenciales de la resolución, la diligencia surtirá efecto desde ese momento.', null, '13db9584e41f8ba98f3214779ac3656aaab9631b7e22283b25f486d7a923cb63', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '13db9584e41f8ba98f3214779ac3656aaab9631b7e22283b25f486d7a923cb63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
