with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 1 del Real Decreto 937/2003, se consideran documentos judiciales:', 'El concepto es amplio: actuaciones procesales y documentos aportados por partes o terceros, por escrito o por medios electrónicos, cualquiera que sea el soporte.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-15237'), 'Art. 1.4 RD 937/2003', 'Se consideran documentos judiciales tanto las actuaciones procesales como aquellos que hayan sido aportados por las partes o por terceros al proceso por escrito o por medios electrónicos o telemáticos, con independencia de cuál sea el soporte material en que se encuentren recogidos.', null, '9a4064dfbd613bd78bb3655a965e458060035a0c926b607a3ed5db07a7692b3d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9a4064dfbd613bd78bb3655a965e458060035a0c926b607a3ed5db07a7692b3d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo las resoluciones judiciales firmes y sus testimonios.', false), ('B', 'Tanto las actuaciones procesales como los aportados por las partes o por terceros al proceso, con independencia de cuál sea su soporte material.', true), ('C', 'Únicamente los documentos en soporte papel incorporados a los autos.', false), ('D', 'Las actuaciones procesales, con exclusión de los documentos aportados por terceros.', false)) as v(label, body, ok)
)
