with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 937/2003, el procedimiento a través del cual se determina cuándo un documento pierde toda su utilidad o, por el contrario, ha de ser conservado se denomina:', 'El art. 1.3 define el expurgo; su régimen está en el capítulo III del real decreto (Juntas de Expurgo).', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-15237'), 'Art. 1.3 RD 937/2003', 'Se entiende por expurgo el procedimiento a través del cual se determina cuándo un documento pierde toda su utilidad o, por el contrario, ha de ser conservado', null, 'cc0408d1e6d0afa903c618a659d5fdada563df1fc106e1a14b3307f27cc3bdd0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cc0408d1e6d0afa903c618a659d5fdada563df1fc106e1a14b3307f27cc3bdd0')
  returning id
