with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué órgano aprobó el Plan de Transparencia Judicial?', 'El Plan se aprobó por Acuerdo del Consejo de Ministros de 21 de octubre de 2005, a propuesta del Ministro de Justicia, y se publicó por Resolución de la Secretaría de Estado de Justicia de 28 de octubre de 2005. Lo que aprobó el Congreso como Proposición no de Ley fue la Carta de Derechos.', 'justra_09_plan_transparencia', (select id from public.topics where slug = 'justra-09-plan-transparencia'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-17951'), 'Resolución 28/10/2005 PTJ', 'El Consejo de Ministros, en su reunión del día 21 de octubre de 2005, a propuesta del Ministro de Justicia, aprobó mediante Acuerdo el Plan de Transparencia Judicial', null, 'fe83185dc22be1fc37416c6bfb769ca145098d7e52faa95d71cf9d21fa504dbd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fe83185dc22be1fc37416c6bfb769ca145098d7e52faa95d71cf9d21fa504dbd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consejo de Ministros, mediante Acuerdo de 21 de octubre de 2005, a propuesta del Ministro de Justicia.', true), ('B', 'El Pleno del Consejo General del Poder Judicial.', false), ('C', 'El Pleno del Congreso de los Diputados, como Proposición no de Ley.', false), ('D', 'La Comisión Nacional de Estadística Judicial.', false)) as v(label, body, ok)
)
