  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes NO figura entre las finalidades del Plan de Transparencia Judicial enumeradas en el artículo 14.1 de la Ley 15/2003, según recoge el Acuerdo de aprobación del Plan?', 'Las finalidades enumeradas son: programa legislativo procesal; planificación presupuestaria de retribuciones y de recursos humanos y materiales; actualización de la organización judicial; e inspección de juzgados y tribunales. La selección y formación no aparece.', 'justra_09_plan_transparencia', (select id from public.topics where slug = 'justra-09-plan-transparencia'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-17951'), 'Anexo PTJ (Ley 15/2003, art. 14.1)', 'a) El desarrollo del programa legislativo del Estado en materia procesal. […] c) La actualización y modificación de la organización judicial. d) El funcionamiento de los servicios de inspección sobre los juzgados y tribunales.', null, '834d6851643f317b9e2a9278f60f8b950579609872ab8dfb440630574be960f3', false
