with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 249 de la Ley de Enjuiciamiento Civil, se decidirán en el juicio ordinario, cualquiera que sea su cuantía, las demandas:', 'La tutela del honor, intimidad e imagen (y de otros derechos fundamentales) va al ordinario, con intervención del Fiscal y tramitación preferente; la rectificación, las rentas, los alimentos y el precario van al verbal.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 249.1 LEC', '2.º Las que pretendan la tutela del derecho al honor, a la intimidad y a la propia imagen, y las que pidan la tutela judicial civil de cualquier otro derecho fundamental, salvo las que se refieran al derecho de rectificación.', null, '5b67c4cb343ebdd729f210217b6a7c860ca52b2887a410258999776ce4a5284f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5b67c4cb343ebdd729f210217b6a7c860ca52b2887a410258999776ce4a5284f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que pretendan la tutela del derecho al honor, a la intimidad y a la propia imagen, salvo las referidas al derecho de rectificación.', true), ('B', 'Que versen sobre reclamación de rentas impagadas.', false), ('C', 'Que soliciten alimentos debidos por disposición legal.', false), ('D', 'Que pretendan la recuperación de una finca cedida en precario.', false)) as v(label, body, ok)
)
