  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, por razón de la cuantía se decidirán en el juicio ordinario las demandas cuya cuantía:', 'Tras la reforma de la LO 1/2025, el límite entre ordinario y verbal por cuantía es de 15.000 euros (art. 249.2 LEC).', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 249.2 LEC', 'Se decidirán también en el juicio ordinario las demandas cuya cuantía exceda de quince mil euros y aquéllas cuyo interés económico resulte imposible de calcular, ni siquiera de modo relativo.', null, 'f6a79b46471d1f2256359a70b82639a705bc24371fb6e401c29598ed89f1a812', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f6a79b46471d1f2256359a70b82639a705bc24371fb6e401c29598ed89f1a812')
  returning id
), o as (
