  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 405 de la Ley de Enjuiciamiento Civil, en la contestación a la demanda, el silencio o las respuestas evasivas del demandado sobre los hechos aducidos por el actor:', 'El demandado debe admitir o negar los hechos; el tribunal puede valorar su silencio o evasivas como admisión tácita de los perjudiciales.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 405.2 LEC', 'El tribunal podrá considerar el silencio o las respuestas evasivas del demandado como admisión tácita de los hechos que le sean perjudiciales.', null, '87dab8855d6ae4bd786cf922f264c47098dcacb8e2393fe40b6558cc3030004c', false
