  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, si en la audiencia previa las partes no concurren personalmente sino a través de su procurador y no le han otorgado poder para renunciar, allanarse o transigir:', 'A efectos del intento de arreglo, si las partes no van personalmente ni otorgan al procurador poder para renunciar, allanarse o transigir, se les tiene por no comparecidas.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 414.2 LEC', 'Si no concurrieren personalmente ni otorgaren aquel poder, se les tendrá por no comparecidos a la audiencia.', null, 'e2b9c43c9db9076011073098ce4f234840d621449fa29f4d1c395729b212e399', false
