  select 'Conforme a la Ley de Enjuiciamiento Civil, en los juicios verbales que, según la ley, deban finalizar por sentencia sin efectos de cosa juzgada:', 'El art. 438.2 LEC prohíbe la reconvención en los verbales sin cosa juzgada; en los demás, se admite si no hace improcedente el verbal y hay conexión, contestándose en diez días.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 438.2 LEC', 'En ningún caso se admitirá reconvención en los juicios verbales que, según la ley, deban finalizar por sentencia sin efectos de cosa juzgada.', null, 'd8119d2961207ef70cce26ded85e6b2be7711344dbfda92cf546fb02cc48c9d2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd8119d2961207ef70cce26ded85e6b2be7711344dbfda92cf546fb02cc48c9d2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se admitirá reconvención siempre que exista conexión con la demanda.', false), ('B', 'La reconvención se contestará en el plazo de veinte días.', false), ('C', 'Solo se admitirá reconvención si la cuantía no excede de seis mil euros.', false), ('D', 'En ningún caso se admitirá reconvención.', true)) as v(label, body, ok)
)
