with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 442 de la Ley de Enjuiciamiento Civil, si el demandado no comparece a la vista del juicio verbal:', 'La incomparecencia del demandado no impide celebrar el juicio; la del demandante, si el demandado no alega interés legítimo, supone tenerle por desistido con imposición de costas.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 442 LEC', 'Si no compareciere el demandado, se procederá a la celebración del juicio.', null, 'feff446ac24f50742fceac19cdaac9d582c97a7ee750c2de09804a0297d40379', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'feff446ac24f50742fceac19cdaac9d582c97a7ee750c2de09804a0297d40379')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
