  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, si el demandante no asiste a la vista del juicio verbal y el demandado no alega interés legítimo en la continuación del proceso:', 'El art. 442.1 LEC: desistimiento, costas y, si el demandado lo pide y acredita, indemnización de daños y perjuicios.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 442.1 LEC', 'se tendrá en el acto por desistido a aquél de la demanda, se le impondrán las costas causadas y se le condenará a indemnizar al demandado comparecido, si éste lo solicitare y acreditare los daños y perjuicios sufridos.', null, 'd3f04e845d12421604f57de3d598871ec31ab21f8aa47233faa5a3444a8f78df', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd3f04e845d12421604f57de3d598871ec31ab21f8aa47233faa5a3444a8f78df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
