with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley Orgánica 1/2025, de medidas en materia de eficiencia del Servicio Público de Justicia, se entiende por medio adecuado de solución de controversias:', 'El concepto del art. 2 es amplio: cualquier actividad negociadora, de buena fe, para una solución extrajudicial, con o sin tercero neutral.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 2 LO 1/2025', 'se entiende por medio adecuado de solución de controversias cualquier tipo de actividad negociadora, reconocida en esta u otras leyes, estatales o autonómicas, a la que las partes de un conflicto acuden de buena fe con el objeto de encontrar una solución extrajudicial al mismo, ya sea por sí mismas o con la intervención de una tercera persona neutral.', null, '9c7b04faf53c58a1b4565817bece460f75c9e76ffbba99f7c81a786a873a1f93', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9c7b04faf53c58a1b4565817bece460f75c9e76ffbba99f7c81a786a873a1f93')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivamente la mediación regulada en la Ley 5/2012, de mediación en asuntos civiles y mercantiles.', false), ('B', 'El arbitraje de equidad ante una corte arbitral.', false), ('C', 'Cualquier tipo de actividad negociadora, reconocida en esta u otras leyes, a la que las partes acuden de buena fe para encontrar una solución extrajudicial, por sí mismas o con la intervención de una tercera persona neutral.', true), ('D', 'La conciliación celebrada ante el Juez de Paz una vez iniciado el proceso.', false)) as v(label, body, ok)
)
