with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 5 de la Ley Orgánica 1/2025, ¿en cuál de los siguientes procesos civiles NO se exige acudir previamente a un medio adecuado de solución de controversias como requisito de procedibilidad?', 'El art. 5.2 exceptúa, entre otros, la tutela de derechos fundamentales, las medidas del art. 158 CC, las medidas de apoyo a la discapacidad, la filiación, la tutela sumaria de la posesión, la obra ruinosa, ciertos supuestos de menores y el juicio cambiario.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 5.2 LO 1/2025', 'h) el juicio cambiario.', null, 'c133f4a57cf4301a31ba7556f689de02382d9c1df30b6e106a810b4b5af169b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c133f4a57cf4301a31ba7556f689de02382d9c1df30b6e106a810b4b5af169b2')
  returning id
