with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 1/2025, NO será preciso acudir a un medio adecuado de solución de controversias para:', 'El art. 5.3 excluye la demanda ejecutiva, las cautelares previas, las diligencias preliminares y, con excepciones, los expedientes de jurisdicción voluntaria, además del monitorio europeo y el proceso europeo de escasa cuantía.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 5.3 LO 1/2025', 'No será preciso acudir a un medio adecuado de solución de controversias para la interposición de una demanda ejecutiva, la solicitud de medidas cautelares previas a la demanda, la solicitud de diligencias preliminares ni para la iniciación de expedientes de jurisdicción voluntaria', null, '5ac1a52885ac13994d9d9c24a76a47af0d28ce42a2a61404b9023bcc5730ff8a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5ac1a52885ac13994d9d9c24a76a47af0d28ce42a2a61404b9023bcc5730ff8a')
  returning id
