with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 6 de la Ley Orgánica 1/2025, la asistencia letrada a las partes en los medios adecuados de solución de controversias solo es preceptiva cuando se utilice:', 'La regla es la asistencia letrada potestativa; solo es preceptiva en la oferta vinculante, con la excepción de cuantías de hasta 2.000 euros o leyes sectoriales que no la exijan.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 6.2 LO 1/2025', 'Únicamente será preceptiva la asistencia letrada a las partes cuando se utilice como medio adecuado de solución de controversias la formulación de una oferta vinculante, excepto cuando la cuantía del asunto controvertido no supere los dos mil euros', null, '0e7ceeca3bc5e6c7c21e86e611bced99a4a7b8e848fd1d473666fb50f0d86f5a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0e7ceeca3bc5e6c7c21e86e611bced99a4a7b8e848fd1d473666fb50f0d86f5a')
  returning id
