with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica 1/2025, cuando el objeto de la controversia sea una reclamación de cantidad que no exceda de seiscientos euros, la actividad negociadora:', 'El art. 8.2 establece la preferencia por medios telemáticos en reclamaciones de hasta 600 euros.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 8.2 LO 1/2025', 'Cuando el objeto de controversia sea una reclamación de cantidad que no exceda de seiscientos euros se desarrollará preferentemente por medios telemáticos, salvo que el empleo de éstos no sea posible para alguna de las partes.', null, '4674cc4c24018bc3b26bdc92145ba4fa5961fa6abb3165f3d62a9be173b37e0e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4674cc4c24018bc3b26bdc92145ba4fa5961fa6abb3165f3d62a9be173b37e0e')
  returning id
