  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 1/2025, se entenderá que el proceso de negociación ha terminado sin acuerdo si, desde la fecha de recepción de la solicitud inicial por la otra parte, transcurren sin que se mantenga la primera reunión o contacto ni se obtenga respuesta por escrito:', 'El art. 10.4.a) fija treinta días naturales; además, terminan sin acuerdo las negociaciones a los tres meses de la primera reunión sin acuerdo, salvo que las partes continúen.', 'justra_16_masc_declarativos', (select id from public.topics where slug = 'justra-16-masc-declarativos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 10.4 LO 1/2025', 'a) Si transcurrieran treinta días naturales a contar desde la fecha de recepción de la solicitud inicial de negociación por la otra parte y no se mantuviera la primera reunión o contacto dirigido a alcanzar un acuerdo o no se obtenga respuesta por escrito.', null, 'a1397acf4a66e5da37f3cfb2d0f9a029738b2083280f88f54b6a8c44acd49ed6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a1397acf4a66e5da37f3cfb2d0f9a029738b2083280f88f54b6a8c44acd49ed6')
  returning id
