  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quince días hábiles.', false), ('B', 'Treinta días naturales.', true), ('C', 'Dos meses.', false), ('D', 'Tres meses.', false)) as v(label, body, ok)
)
