  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, el ejecutante que quiera tomar parte en la subasta:', 'El ejecutante puede pujar sin consignar; pero no puede mejorar el precio del mejor postor una vez finalizada la subasta.', 'justra_17_ejecucion_cautelares', (select id from public.topics where slug = 'justra-17-ejecucion-cautelares'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 647.2 LEC', 'El ejecutante podrá tomar parte en la subasta, aunque no existan otros licitadores, sin necesidad de consignar cantidad alguna.', null, 'dde209beabdc9b67adc3be2aee9876f52a84c1048b1f678f1e157fdaaa4a108b', false
