  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, salvo que expresamente se disponga otra cosa, el solicitante de una medida cautelar deberá:', 'Además del peligro por la mora procesal y la apariencia de buen derecho, se exige caución, salvo previsión en contrario; la caución es siempre previa al cumplimiento de la medida (art. 737).', 'justra_17_ejecucion_cautelares', (select id from public.topics where slug = 'justra-17-ejecucion-cautelares'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 728.3 LEC', 'Salvo que expresamente se disponga otra cosa, el solicitante de la medida cautelar deberá prestar caución suficiente para responder, de manera rápida y efectiva, de los daños y perjuicios que la adopción de la medida cautelar pudiera causar al patrimonio del demandado.', null, '86be160d3999d59d1a2fe3e30b584cc1e9d183afe15c3f68bf14f881e5f31ef1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '86be160d3999d59d1a2fe3e30b584cc1e9d183afe15c3f68bf14f881e5f31ef1')
