insert into public.topics (slug, title) values ('justra-18-procesos-especiales', 'Tramitación, tema 18. Procesos especiales en la Ley de Enjuiciamiento Civil: matrimoniales, monitorio y juicio cambiario') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('tramitacion-procesal') and t.slug = 'justra-18-procesos-especiales' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 748 de la Ley de Enjuiciamiento Civil, ¿cuál de los siguientes procesos NO está incluido en el ámbito de aplicación del título dedicado a los procesos sobre capacidad, filiación, matrimonio y menores?', 'El desahucio es un juicio verbal por razón de la materia (art. 250 LEC), no uno de los procesos especiales del art. 748.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 748 LEC', '2.º Los de filiación, paternidad y maternidad. […] 3.º Los de nulidad del matrimonio, separación y divorcio y los de modificación de medidas adoptadas en ellos. […] 8.º Los que versen sobre la necesidad de asentimiento en la adopción.', null, '5319b2dadb21db1820e0d45c8282bd5bc64834dbc386a9536b42e98c273c8442', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5319b2dadb21db1820e0d45c8282bd5bc64834dbc386a9536b42e98c273c8442')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los procesos de filiación, paternidad y maternidad.', false), ('B', 'Los procesos de nulidad del matrimonio, separación y divorcio.', false), ('C', 'El proceso de desahucio por falta de pago de rentas.', true), ('D', 'Los que versen sobre la necesidad de asentimiento en la adopción.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 753 de la Ley de Enjuiciamiento Civil, salvo que expresamente se disponga otra cosa, los procesos sobre capacidad, filiación, matrimonio y menores se sustancian por los trámites del:', 'Se tramitan como juicio verbal, pero con contestación escrita en veinte días conforme al art. 405.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 753.1 LEC', 'Salvo que expresamente se disponga otra cosa, los procesos a que se refiere este título se sustanciarán por los trámites del juicio verbal. […] emplazándoles para que la contesten en el plazo de veinte días, conforme a lo establecido en el artículo 405.', null, 'b17a1ebb7ec1aaa722616fead17aa363b695a3d6231b83e22bf84d5e24563d37', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b17a1ebb7ec1aaa722616fead17aa363b695a3d6231b83e22bf84d5e24563d37')
