insert into public.topics (slug, title) values ('justra-19-jurisdiccion-voluntaria', 'Tramitación, tema 19. La jurisdicción voluntaria: naturaleza y clases de procedimientos. Especial referencia a los actos de conciliación') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('tramitacion-procesal') and t.slug = 'justra-19-jurisdiccion-voluntaria' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley 15/2015, de la Jurisdicción Voluntaria, se consideran expedientes de jurisdicción voluntaria todos aquellos que requieran la intervención de un órgano jurisdiccional para la tutela de derechos e intereses en materia de Derecho civil y mercantil:', 'La nota definitoria de la jurisdicción voluntaria es la ausencia de controversia que deba sustanciarse en un proceso contencioso.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 1.2 LJV', 'Se consideran expedientes de jurisdicción voluntaria a los efectos de esta Ley todos aquellos que requieran la intervención de un órgano jurisdiccional para la tutela de derechos e intereses en materia de Derecho civil y mercantil, sin que exista controversia que deba sustanciarse en un proceso contencioso.', null, '928302d9024b7f80c6a360b1a1ba98e0c52c34ec77625c807ab25fc0bfc5b320', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '928302d9024b7f80c6a360b1a1ba98e0c52c34ec77625c807ab25fc0bfc5b320')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que exista oposición de algún interesado.', false), ('B', 'Sin que exista controversia que deba sustanciarse en un proceso contencioso.', true), ('C', 'Cuando la cuantía no exceda de 6.000 euros.', false), ('D', 'Únicamente cuando estén interesados menores de edad.', false)) as v(label, body, ok)
)
