with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de la Jurisdicción Voluntaria, la competencia territorial en los expedientes de jurisdicción voluntaria:', 'El art. 2.2 LJV excluye la sumisión expresa o tácita: rige el fuero que fije el precepto aplicable a cada expediente.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 2.2 LJV', 'En los expedientes de jurisdicción voluntaria la competencia territorial vendrá fijada por el precepto correspondiente en cada caso, sin que quepa modificarla por sumisión expresa o tácita.', null, 'ee8a8b554623eee95c064995ada5a2c1c89bf4dad412421c190087bbc318056d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee8a8b554623eee95c064995ada5a2c1c89bf4dad412421c190087bbc318056d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Puede modificarse por sumisión expresa, pero no tácita.', false), ('B', 'Corresponde siempre al domicilio del solicitante.', false), ('C', 'Vendrá fijada por el precepto correspondiente en cada caso, sin que quepa modificarla por sumisión expresa o tácita.', true), ('D', 'Se determina libremente por el solicitante entre los órganos de la provincia.', false)) as v(label, body, ok)
)
