select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando la Ley de la Jurisdicción Voluntaria no atribuya expresamente la competencia para decidir un expediente, ¿cuál de los siguientes expedientes NO decidirá necesariamente el Juez, según su artículo 2.3?', 'A falta de atribución expresa, el Juez decide los expedientes que afecten al interés público, al estado civil, a normas sustantivas o derechos subjetivos, o a menores y personas con discapacidad con apoyos; el resto los resuelve el Secretario judicial (LAJ).', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 2.3 LJV', 'Cuando no venga atribuida la competencia expresamente a ninguno de ellos, el Juez decidirá los expedientes que afecten al interés público, al estado civil de las personas, los que precisen la tutela de normas sustantivas o puedan deparar actos de disposición, reconocimiento, creación o extinción de derechos subjetivos, así como cuando afecten a los derechos de menores o personas con discapacidad con medidas de apoyo para el ejercicio de su capacidad jurídica. El resto de expedientes serán resueltos por el Secretario judicial.', null, 'bb39779c8c1d4a169d06e6aed8bd9ff8e63aa5515e8050e99b7bc01626428cbc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bb39779c8c1d4a169d06e6aed8bd9ff8e63aa5515e8050e99b7bc01626428cbc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un expediente que afecte al estado civil de las personas.', false), ('B', 'Un expediente que pueda deparar actos de disposición o extinción de derechos subjetivos.', false), ('C', 'Un expediente que afecte a los derechos de un menor.', false), ('D', 'Un expediente que no afecte al interés público, al estado civil, a derechos subjetivos, a menores ni a personas con discapacidad con medidas de apoyo.', true)) as v(label, body, ok)
)
