with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 6 de la Ley de la Jurisdicción Voluntaria, si se acredita la presentación de una demanda en un proceso jurisdiccional sobre el mismo objeto que un expediente de jurisdicción voluntaria en tramitación:', 'El art. 6.2 LJV impide iniciar o continuar un expediente sobre un objeto sustanciado en proceso jurisdiccional: se archiva y se remiten las actuaciones al tribunal. El art. 15.3 prohíbe acumular expedientes a procesos contenciosos.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 6.2 LJV', 'Una vez acreditada la presentación de la correspondiente demanda, se procederá al archivo del expediente, remitiéndose las actuaciones realizadas al tribunal que esté conociendo del proceso jurisdiccional para que lo incorpore a los autos.', null, 'f410c236e9723452413b4b0957e1b7ffee102d926e514e9bb71af3033609f26f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f410c236e9723452413b4b0957e1b7ffee102d926e514e9bb71af3033609f26f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se procederá al archivo del expediente, remitiéndose las actuaciones al tribunal que conozca del proceso para que las incorpore a los autos.', true), ('B', 'Se suspenderá el proceso jurisdiccional hasta que se resuelva el expediente.', false), ('C', 'Se acumularán el expediente y el proceso.', false), ('D', 'Continuarán ambos de forma independiente.', false)) as v(label, body, ok)
)
