  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Era una revolta religiosa contra la Inquisició castellana.', false), ('B', 'Era un alçament patriòtic preparat per la Generalitat de Pau Claris.', false), ('C', 'Era una revolta nobiliària contra el virrei i el Consell d’Aragó.', false), ('D', 'Expressava el malestar popular, sense caràcter patriòtic ni anticastellà.', true)) as v(label, body, ok)
)
