insert into public.topics (slug, title) values ('pn-27-derechos-humanos', 'Tema 27. Derechos Humanos: DUDH, CEDH, Convenio contra la Tortura, Protocolo facultativo y Mecanismo Nacional de Prevención de la Tortura') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-27-derechos-humanos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El artículo 3 del Convenio Europeo de Derechos Humanos lleva por título:', 'El art. 3 CEDH, «Prohibición de la tortura», establece que nadie podrá ser sometido a tortura ni a penas o tratos inhumanos o degradantes. El derecho a la vida es el art. 2 y el derecho a la libertad y a la seguridad, el art. 5.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Art. 3 CEDH', 'Artículo 3. Prohibición de la tortura. Nadie podrá ser sometido a tortura ni a penas o tratos inhumanos o degradantes.', null, '77b9368aaf3336d52cd2886975cdeb3df5ed1464bf0d66eb866c6843e7cf1049', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '77b9368aaf3336d52cd2886975cdeb3df5ed1464bf0d66eb866c6843e7cf1049')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Derecho a la vida.', false), ('B', 'Prohibición de la tortura.', true), ('C', 'Derecho a la libertad y a la seguridad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Para asegurar el respeto de los compromisos del Convenio Europeo de Derechos Humanos, este instituye:', 'El art. 19 CEDH instituye el Tribunal Europeo de Derechos Humanos y dispone que funcionará de manera permanente.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Art. 19 CEDH', 'se instituye un Tribunal Europeo de Derechos Humanos, en lo sucesivo denominado «el Tribunal». Funcionará de manera permanente.', null, '2391c9c9a39a3ab7308e73b5c8ee93fe6368c3a61a16ae66a5f6ce85b6a36360', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2391c9c9a39a3ab7308e73b5c8ee93fe6368c3a61a16ae66a5f6ce85b6a36360')
  returning id
), o as (
