  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Comisión Europea de Derechos Humanos, que se reunirá en sesiones periódicas.', false), ('B', 'El Comité contra la Tortura, compuesto de diez expertos.', false), ('C', 'El Tribunal Europeo de Derechos Humanos, que funcionará de manera permanente.', true)) as v(label, body, ok)
)
