with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el CEDH, la muerte no se considera infligida con infracción del derecho a la vida cuando se produzca como consecuencia de un recurso a la fuerza absolutamente necesario, entre otros casos:', 'El art. 2.2 CEDH recoge tres supuestos: defensa de una persona contra una agresión ilegítima; detener a una persona conforme a derecho o impedir la evasión de un preso o detenido; y reprimir, de acuerdo con la ley, una revuelta o insurrección.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Art. 2.2 CEDH', 'b) Para detener a una persona conforme a derecho o para impedir la evasión de un preso o detenido legalmente.', null, 'e64eb559c64fb3d762b323486ca01637cc90420441fa5cf8f13a4367caeb43c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e64eb559c64fb3d762b323486ca01637cc90420441fa5cf8f13a4367caeb43c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Para identificar a una persona que se niega a mostrar su documentación.', false), ('B', 'Para disolver cualquier reunión no comunicada previamente a la autoridad.', false), ('C', 'Para detener a una persona conforme a derecho o para impedir la evasión de un preso o detenido legalmente.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el CEDH, toda persona detenida preventivamente debe ser informada de los motivos de su detención y de cualquier acusación formulada contra ella:', 'El art. 5.2 CEDH exige informar al detenido «en el más breve plazo y en una lengua que comprenda». No fija un plazo en horas ni exige la presencia de abogado para ello.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Art. 5.2 CEDH', '2\. Toda persona detenida preventivamente debe ser informada, en el más breve plazo y en una lengua que comprenda, de los motivos de su detención y de cualquier acusación formulada contra ella.', null, 'f830307466ba01ac36902e6b4c391d4d05ad4b7a3122fa05e7b3140cd0370828', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f830307466ba01ac36902e6b4c391d4d05ad4b7a3122fa05e7b3140cd0370828')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo máximo de setenta y dos horas y por escrito.', false), ('B', 'Inmediatamente y en presencia de su abogado.', false), ('C', 'En el más breve plazo y en una lengua que comprenda.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
