with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En caso de guerra o de otro peligro público que amenace la vida de la nación, el CEDH NO autoriza ninguna derogación, entre otros, del artículo:', 'El art. 15.2 CEDH no permite derogar el art. 2 (salvo muertes resultantes de actos lícitos de guerra), ni los arts. 3, 4.1 y 7. Los arts. 5 y 6 sí pueden ser objeto de medidas de derogación en la medida estricta en que lo exija la situación.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Art. 15.2 CEDH', '2\. La disposición precedente no autoriza ninguna derogación al artículo 2, salvo para el caso de muertes resultantes de actos lícitos de guerra, y a los artículos 3, 4 (párrafo 1) y 7.', null, '8fc100b929febf4c7ba508dfba1113550cd801c173c3c024406f9a150a6962f0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8fc100b929febf4c7ba508dfba1113550cd801c173c3c024406f9a150a6962f0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '3, que prohíbe la tortura.', true), ('B', '5, que reconoce el derecho a la libertad y a la seguridad.', false), ('C', '6, que reconoce el derecho a un proceso equitativo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
