with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el CEDH, al Tribunal Europeo de Derechos Humanos solo podrá recurrirse después de agotar las vías de recursos internas y en el plazo de:', 'El art. 35.1 CEDH, en su redacción vigente, fija el plazo de cuatro meses desde la resolución interna definitiva (antes eran seis meses).', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Art. 35.1 CEDH', '1\. Al Tribunal no podrá recurrirse sino después de agotar las vías de recursos internas, tal como se entiende según los principios de derecho internacional generalmente reconocidos y en el plazo de cuatro meses a partir de la fecha de la resolución interna definitiva.', null, 'ed6d70820c33be7cbf11cc91cbcdef7f223a7ca9f252ba201224f14c0149f6a3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ed6d70820c33be7cbf11cc91cbcdef7f223a7ca9f252ba201224f14c0149f6a3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seis meses a partir de la fecha de la resolución interna definitiva.', false), ('B', 'Cuatro meses a partir de la fecha de la resolución interna definitiva.', true), ('C', 'Tres meses a partir de la notificación de la sentencia de primera instancia.', false)) as v(label, body, ok)
)
