with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Convención de la ONU contra la tortura, para que exista tortura los dolores o sufrimientos graves deben ser infligidos:', 'El art. 1.1 de la Convención exige la intervención (directa, por instigación, consentimiento o aquiescencia) de un funcionario público u otra persona en el ejercicio de funciones públicas. No son tortura los dolores o sufrimientos que sean consecuencia únicamente de sanciones legítimas.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Art. 1 Convención contra la Tortura', 'CUANDO DICHOS DOLORES O SUFRIMIENTOS SEAN INFLIGIDOS POR UN FUNCIONARIO PUBLICO U OTRA PERSONA EN EL EJERCICIO DE FUNCIONES PUBLICAS, A INSTIGACION SUYA, O CON SU CONSENTIMIENTO O AQUIESCENCIA.', null, '957dabfa0915a97a4021cb70352cac44a6ac12103c5035715bdfb7c4a466f76e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '957dabfa0915a97a4021cb70352cac44a6ac12103c5035715bdfb7c4a466f76e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por cualquier persona, sea o no funcionario, siempre que actúe con la finalidad de obtener una confesión.', false), ('B', 'Exclusivamente por un funcionario público encargado de la custodia de personas privadas de libertad.', false), ('C', 'Por un funcionario público u otra persona en el ejercicio de funciones públicas, a instigación suya, o con su consentimiento o aquiescencia.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Convención contra la tortura, NO se consideran torturas los dolores o sufrimientos que:', 'El art. 1.1 incluye en la tortura tanto los dolores o sufrimientos físicos como los mentales, y entre sus fines está el de castigar a la persona por un acto que haya cometido o se sospeche que ha cometido. Solo quedan fuera los derivados únicamente de sanciones legítimas.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Art. 1 Convención contra la Tortura', 'NO SE CONSIDERARAN TORTURAS LOS DOLORES O SUFRIMIENTOS QUE SEAN CONSECUENCIA UNICAMENTE DE SANCIONES LEGITIMAS, O QUE SEAN INHERENTES O INCIDENTALES A ESTAS.', null, 'ef4d82f0673dacd95262b0047af2b1a19267cd0e2700c874d6938ef85161e9c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ef4d82f0673dacd95262b0047af2b1a19267cd0e2700c874d6938ef85161e9c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sean solo mentales, sin ningún daño físico.', false), ('B', 'Sean consecuencia únicamente de sanciones legítimas, o que sean inherentes o incidentales a estas.', true), ('C', 'Se inflijan para castigar a una persona por un acto que se sospecha que ha cometido.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Convención contra la tortura, la orden de un funcionario superior o de una autoridad pública:', 'El art. 2.3 de la Convención prohíbe invocar la orden de un superior o de una autoridad pública como justificación de la tortura, y el art. 2.2 añade que tampoco pueden invocarse circunstancias excepcionales como el estado de guerra.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Art. 2.3 Convención contra la Tortura', '3. NO PODRA INVOCARSE UNA ORDEN DE UN FUNCIONARIO SUPERIOR O DE UNA AUTORIDAD PUBLICA COMO JUSTIFICACION DE LA TORTURA.', null, '0c082f01d96aa1c55ba25aed70524f67f7a93bb7c12e747bee16fe242a10f955', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0c082f01d96aa1c55ba25aed70524f67f7a93bb7c12e747bee16fe242a10f955')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrá invocarse como justificación de la tortura.', true), ('B', 'Podrá invocarse como justificación de la tortura solo en estado de guerra.', false), ('C', 'Excluirá la responsabilidad del subordinado que la cumpla, pero no la del superior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Convención contra la tortura, ningún Estado Parte procederá a la expulsión, devolución o extradición de una persona a otro Estado cuando:', 'El art. 3.1 de la Convención impide expulsar, devolver o extraditar a una persona a otro Estado cuando haya razones fundadas para creer que estaría en peligro de ser sometida a tortura.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Art. 3.1 Convención contra la Tortura', '1. NINGUN ESTADO PARTE PROCEDERA A LA EXPULSION, DEVOLUCION O EXTRADICION DE UNA PERSONA A OTRO ESTADO CUANDO HAYA RAZONES FUNDADAS PARA CREER QUE ESTARIA EN PELIGRO DE SER SOMETIDA A TORTURA.', null, 'edde0f7283caddc6adfc74ef4bfeb2d2fa30c2c04dd361e1f1b10b6b09b6a2c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'edde0f7283caddc6adfc74ef4bfeb2d2fa30c2c04dd361e1f1b10b6b09b6a2c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Esa persona haya solicitado asilo en cualquier Estado Parte.', false), ('B', 'El otro Estado no haya ratificado la Convención.', false), ('C', 'Haya razones fundadas para creer que estaría en peligro de ser sometida a tortura.', true)) as v(label, body, ok)
)
