with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Convención contra la tortura, una declaración que se demuestre que ha sido hecha como resultado de tortura:', 'El art. 15 de la Convención excluye como prueba las declaraciones obtenidas mediante tortura, con la única salvedad de usarlas contra el acusado de tortura para probar que la declaración se formuló.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Art. 15 Convención contra la Tortura', 'NINGUNA DECLARACION QUE SE DEMUESTRE QUE HA SIDO HECHA COMO RESULTADO DE TORTURA PUEDA SER INVOCADA COMO PRUEBA EN NINGUN PROCEDIMIENTO, SALVO EN CONTRA DE UNA PERSONA ACUSADA DE TORTURA COMO PRUEBA DE QUE SE HA FORMULADO LA DECLARACION.', null, '5eef8d7190c0ed6621a592507bd6e4b36ebc8945e99ab7ae47802a1e44be53b1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5eef8d7190c0ed6621a592507bd6e4b36ebc8945e99ab7ae47802a1e44be53b1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrá invocarse como prueba en ningún procedimiento, salvo en contra de una persona acusada de tortura como prueba de que se ha formulado la declaración.', true), ('B', 'Podrá invocarse como prueba si es ratificada después ante la autoridad judicial.', false), ('C', 'Solo podrá invocarse como prueba en procedimientos administrativos.', false)) as v(label, body, ok)
)
