with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El Comité contra la Tortura que constituye la Convención de Naciones Unidas está compuesto de:', 'El art. 17.1 de la Convención fija en diez los expertos del Comité contra la Tortura, que ejercen sus funciones a título personal. Sus miembros son elegidos por cuatro años (art. 17.5).', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Art. 17.1 Convención contra la Tortura', 'EL COMITE ESTARA COMPUESTO DE DIEZ EXPERTOS DE GRAN INTEGRIDAD MORAL Y RECONOCIDA COMPETENCIA EN MATERIA DE DERECHOS HUMANOS, QUE EJERCERAN SUS FUNCIONES A TITULO PERSONAL.', null, '558514274b2cf90a81f8875bbe94cbc21947294ad4a0fa9bff7355428283e9d5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '558514274b2cf90a81f8875bbe94cbc21947294ad4a0fa9bff7355428283e9d5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Veinticinco expertos elegidos por la Asamblea General de las Naciones Unidas.', false), ('B', 'Diez expertos de gran integridad moral y reconocida competencia en materia de derechos humanos.', true), ('C', 'Un número de miembros igual al de los Estados Partes.', false)) as v(label, body, ok)
)
