with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Declaración Universal de los Derechos Humanos fue proclamada por la Asamblea General de las Naciones Unidas en:', 'Según la página oficial de la ONU, la Declaración fue proclamada por la Asamblea General en París el 10 de diciembre de 1948, mediante la Resolución 217 A (III), como ideal común para todos los pueblos y naciones.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 1, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/universal-declaration-of-human-rights'), 'Introducción DUDH', 'la Declaración fue proclamada por la Asamblea General de las Naciones Unidas en París, el 10 de diciembre de 1948 en su (Resolución 217 A (III)) como un ideal común para todos los pueblos y naciones.', null, '366f943c4e6a2bd46a91074552bb009c58bb8cdf04d3afdb75d15eea8e2afa25', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '366f943c4e6a2bd46a91074552bb009c58bb8cdf04d3afdb75d15eea8e2afa25')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Nueva York, el 10 de diciembre de 1948.', false), ('B', 'París, el 10 de diciembre de 1948.', true), ('C', 'Ginebra, el 24 de octubre de 1945.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Declaración Universal de los Derechos Humanos, todos los seres humanos nacen libres e iguales en:', 'El art. 1 DUDH dice que todos los seres humanos nacen libres e iguales en dignidad y derechos y que, dotados de razón y conciencia, deben comportarse fraternalmente los unos con los otros.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 1, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/universal-declaration-of-human-rights'), 'Art. 1 DUDH', 'Todos los seres humanos nacen libres e iguales en dignidad y derechos y, dotados como están de razón y conciencia, deben comportarse fraternalmente los unos con los otros.', null, '22c7755f9b541d871589b5132ce5ab30aa94b0c62990610f93ee4c0fed7b5f9f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '22c7755f9b541d871589b5132ce5ab30aa94b0c62990610f93ee4c0fed7b5f9f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dignidad y derechos.', true), ('B', 'Derechos y deberes.', false), ('C', 'Libertad y oportunidades.', false)) as v(label, body, ok)
)
