with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Declaración Universal de los Derechos Humanos, nadie podrá ser arbitrariamente:', 'El art. 9 DUDH prohíbe la detención, la prisión y el destierro arbitrarios.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 1, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/universal-declaration-of-human-rights'), 'Art. 9 DUDH', 'Nadie podrá ser arbitrariamente detenido, preso ni desterrado.', null, 'd81de90365584bbdba5308a7cefd1f3b49a1ed4ad8814f761b11877321d1cabe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd81de90365584bbdba5308a7cefd1f3b49a1ed4ad8814f761b11877321d1cabe')
