insert into public.sources (title, url, kind, publisher, published_on) values ('Protocolo facultativo de la Convención contra la tortura y otros tratos o penas crueles, inhumanos o degradantes (Nueva York, 18 de diciembre de 2002). Instrumento de ratificación, BOE núm. 148, de 22 de junio de 2006', 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128', 'web_oficial'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado (BOE-A-2006-11128)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-27-derechos-humanos', 'Tema 27. Derechos Humanos: DUDH, CEDH, Convenio contra la Tortura, Protocolo facultativo y Mecanismo Nacional de Prevención de la Tortura') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-27-derechos-humanos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según su artículo 1, el objetivo del Protocolo facultativo de la Convención contra la tortura es establecer:', 'El art. 1 del Protocolo facultativo (Nueva York, 2002) fija como objetivo un sistema de visitas periódicas por órganos internacionales y nacionales independientes, con el fin de prevenir la tortura.', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Art. 1 Protocolo facultativo', 'El objetivo del presente Protocolo es establecer un sistema de visitas periódicas a cargo de órganos internacionales y nacionales independientes a los lugares en que se encuentren personas privadas de su libertad, con el fin de prevenir la tortura', null, '9116da5b836092f0e6cba88b9849ad1dc0f6a80fbd8b77b9b9c7867c691712da', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9116da5b836092f0e6cba88b9849ad1dc0f6a80fbd8b77b9b9c7867c691712da')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un procedimiento de denuncias individuales ante el Tribunal Europeo de Derechos Humanos.', false), ('B', 'Un sistema de visitas periódicas a cargo de órganos internacionales y nacionales independientes a los lugares en que se encuentren personas privadas de su libertad.', true), ('C', 'Un régimen de sanciones penales comunes para los funcionarios que cometan tortura.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El Protocolo facultativo de la Convención contra la tortura denomina «mecanismo nacional de prevención» a:', 'El art. 3 del Protocolo obliga a cada Estado Parte a establecer, designar o mantener a nivel nacional uno o varios órganos de visitas, denominados mecanismo nacional de prevención. El Subcomité para la Prevención es el órgano internacional (art. 2).', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Art. 3 Protocolo facultativo', 'Cada Estado Parte establecerá, designará o mantendrá, a nivel nacional, uno o varios órganos de visitas para la prevención de la tortura y otros tratos o penas crueles, inhumanos o degradantes (en adelante denominado el mecanismo nacional de prevención).', null, 'e47b402418f391d3f0d074d6aa73cdb59cf7ff1854b3fff1d7186b8ccab4d7ca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e47b402418f391d3f0d074d6aa73cdb59cf7ff1854b3fff1d7186b8ccab4d7ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Uno o varios órganos de visitas para la prevención de la tortura que cada Estado Parte establece, designa o mantiene a nivel nacional.', true), ('B', 'El Subcomité para la Prevención de la Tortura del Comité contra la Tortura.', false), ('C', 'El conjunto de jueces encargados del control de la detención en cada Estado Parte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Protocolo facultativo de la Convención contra la tortura, el Subcomité para la Prevención, compuesto inicialmente de diez miembros, aumentará a veinticinco miembros:', 'El art. 5.1 del Protocolo vincula la ampliación de diez a veinticinco miembros a la quincuagésima ratificación o adhesión. Sus miembros se eligen por cuatro años y pueden ser reelegidos una vez (art. 9).', 'pn_27_derechos_humanos', (select id from public.topics where slug = 'pn-27-derechos-humanos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Art. 5.1 Protocolo facultativo', '1. El Subcomité para la Prevención estará compuesto de diez miembros. Una vez que se haya registrado la quincuagésima ratificación del presente Protocolo o adhesión a él, el número de miembros del Subcomité para la Prevención aumentará a veinticinco.', null, '2644041717a99fd5b0197f1dd0fcdf4d1c885282c8d9864c18a2517697480327', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2644041717a99fd5b0197f1dd0fcdf4d1c885282c8d9864c18a2517697480327')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando lo acuerde la Asamblea General de las Naciones Unidas.', false), ('B', 'Una vez registrada la quincuagésima ratificación del Protocolo o adhesión a él.', true), ('C', 'Una vez transcurridos cuatro años desde la entrada en vigor del Protocolo.', false)) as v(label, body, ok)
