insert into public.topics (slug, title) values ('pn-30-etica-delitos-odio', 'Tema 30. Principios éticos de la sociedad actual, contravalores (racismo, xenofobia, intolerancia) y delitos de odio') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-30-etica-delitos-odio' on conflict do nothing;
