with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 510.1 del Código Penal, quienes públicamente fomenten, promuevan o inciten directa o indirectamente al odio, hostilidad, discriminación o violencia contra un grupo por motivos racistas serán castigados con prisión de:', 'El art. 510.1 CP castiga la incitación pública al odio con prisión de uno a cuatro años y multa de seis a doce meses. La pena de seis meses a dos años corresponde a las conductas del apartado 2 (lesión de la dignidad, enaltecimiento).', 'pn_30_etica_delitos_odio', (select id from public.topics where slug = 'pn-30-etica-delitos-odio'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 510.1.a CP', '1\. Serán castigados con una pena de prisión de uno a cuatro años y multa de seis a doce meses:', null, '2be2a063080ccf035ff7bd5b4ab8992015d00734be2b85880d2017feb909f911', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2be2a063080ccf035ff7bd5b4ab8992015d00734be2b85880d2017feb909f911')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Uno a cuatro años y multa de seis a doce meses.', true), ('B', 'Seis meses a dos años y multa de seis a doce meses.', false), ('C', 'Dos a cinco años y multa de doce a veinticuatro meses.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
