with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 15/2022, el derecho de toda persona a la igualdad de trato y no discriminación se reconoce:', 'El art. 2.1 de la Ley 15/2022 reconoce este derecho a toda persona, sin importar su nacionalidad, edad o situación de residencia.', 'pn_30_etica_delitos_odio', (select id from public.topics where slug = 'pn-30-etica-delitos-odio'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 2.1 Ley 15/2022', 'Se reconoce el derecho de toda persona a la igualdad de trato y no discriminación con independencia de su nacionalidad, de si son menores o mayores de edad o de si disfrutan o no de residencia legal.', null, '742dd75d38df531d697f0452445fc2e05b841e7c7ff79571ee0e3478b0cef2d5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '742dd75d38df531d697f0452445fc2e05b841e7c7ff79571ee0e3478b0cef2d5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Con independencia de su nacionalidad, de si son menores o mayores de edad o de si disfrutan o no de residencia legal.', true), ('B', 'Solo a los españoles y a los extranjeros con residencia legal en España.', false), ('C', 'Solo a las personas mayores de edad.', false)) as v(label, body, ok)
)
