with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 19/2007, contra la violencia, el racismo, la xenofobia y la intolerancia en el deporte, las declaraciones, gestos o insultos proferidos en los recintos deportivos que supongan un trato manifiestamente vejatorio para cualquier persona por razón de su origen racial o étnico se consideran:', 'El art. 2.2 de la Ley 19/2007 enumera los actos racistas, xenófobos o intolerantes en el deporte; su letra c) incluye las declaraciones, gestos o insultos manifiestamente vejatorios por razón del origen racial, étnico, geográfico o social, entre otros.', 'pn_30_etica_delitos_odio', (select id from public.topics where slug = 'pn-30-etica-delitos-odio'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-13408'), 'Art. 2.2.c Ley 19/2007', 'c) Las declaraciones, gestos o insultos proferidos en los recintos deportivos con motivo de la celebración de actos deportivos, en sus aledaños o en los medios de transporte públicos en los que se puedan desplazar a los mismos, que supongan un trato manifiestamente vejatorio', null, '6aea64c0876a3c9ffd0dc0c6f4cc1fec7957dac86539834d8a8845db587a8614', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6aea64c0876a3c9ffd0dc0c6f4cc1fec7957dac86539834d8a8845db587a8614')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Actos o conductas violentas en el deporte, exclusivamente.', false), ('B', 'Actos racistas, xenófobos o intolerantes en el deporte.', true), ('C', 'Infracciones de las reglas de juego, competencia de los árbitros.', false)) as v(label, body, ok)
)
