  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Atlas Didáctico del IGN, en los lugares de origen de la emigración:', 'Como los emigrantes son mayoritariamente jóvenes en edad de trabajar y de tener hijos, los lugares de origen pierden población y envejecen; los de llegada se rejuvenecen y crecen.', 'pn_31_inmigracion', (select id from public.topics where slug = 'pn-31-inmigracion'), 2, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/poblacion-bach/'), 'IGN, Atlas Didáctico: Consecuencias demográficas', 'Por ello, en los lugares de origen se reduce el número de habitantes, aumenta la población anciana y disminuye la natalidad. En consecuencia, desciende su crecimiento demográfico y la población envejece.', null, 'a0f5b5c3d29a337a82a65186be561a4c03bb17ce7046dae1cd9cb1ef3e8eb136', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a0f5b5c3d29a337a82a65186be561a4c03bb17ce7046dae1cd9cb1ef3e8eb136')
  returning id
), o as (
