  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Atlas Didáctico del IGN, el crecimiento real de una población en un periodo determinado es el resultado de sumar:', 'El crecimiento real suma el crecimiento natural (nacimientos menos defunciones) y el saldo migratorio (inmigrantes menos emigrantes); puede ser positivo o negativo.', 'pn_31_inmigracion', (select id from public.topics where slug = 'pn-31-inmigracion'), 3, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/poblacion-bach/'), 'IGN, Atlas Didáctico: Consecuencias demográficas', 'es resultado de sumar el crecimiento natural o vegetativo (diferencia entre nacimientos y defunciones) y el saldo migratorio (diferencia entre el número de inmigrantes y emigrantes) de un lugar, en un periodo de tiempo determinado.', null, '306e962d6f687c689bb8d65a6c2b2504b867d02c6ce847aca31cd38ded6f7615', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '306e962d6f687c689bb8d65a6c2b2504b867d02c6ce847aca31cd38ded6f7615')
