with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 149.1.29.ª de la Constitución, la seguridad pública es competencia exclusiva del Estado:', 'El art. 149.1.29.ª CE reserva al Estado la seguridad pública, pero permite que las Comunidades Autónomas creen policías propias según sus Estatutos y en el marco de una ley orgánica.', 'pn_33_seguridad_delincuencia', (select id from public.topics where slug = 'pn-33-seguridad-delincuencia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 149.1.29.ª CE', '29.ª Seguridad pública, sin perjuicio de la posibilidad de creación de policías por las Comunidades Autónomas en la forma que se establezca en los respectivos Estatutos en el marco de lo que disponga una ley orgánica.', null, 'c16b7ead8370b318dbb19572b5d25c7afa151fe1163f59c1fec18a06d10b7810', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c16b7ead8370b318dbb19572b5d25c7afa151fe1163f59c1fec18a06d10b7810')
  returning id
), o as (
