  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la LOPSC, el ejercicio de las potestades en materia de seguridad ciudadana se regirá, entre otros, por los principios de:', 'El art. 4.1 LOPSC enumera esos principios y somete su ejercicio al control administrativo y jurisdiccional. La unidad de acción y la anticipación son principios de la Política de Seguridad Nacional (art. 4.2 de la Ley 36/2015).', 'pn_33_seguridad_delincuencia', (select id from public.topics where slug = 'pn-33-seguridad-delincuencia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Art. 4.1 LOPSC', 'se regirá por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someterá al control administrativo y jurisdiccional.', null, '65cd2f9044d57ec5a87d789d6ac56b100a068463884fe56562cbe6f1afa81f80', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '65cd2f9044d57ec5a87d789d6ac56b100a068463884fe56562cbe6f1afa81f80')
