  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Asignar direcciones IP a los equipos de la red local.', false), ('B', 'Asegurar que todas las comunicaciones entre la red e Internet se realicen conforme a las políticas de seguridad de la organización.', true), ('C', 'Almacenar copias de seguridad de los datos de la organización.', false)) as v(label, body, ok)
)
