with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según INCIBE, en comparación con las direcciones IPv4, las direcciones IP en su versión v6 son:', 'INCIBE explica que una IPv4 es un conjunto de cuatro números del 0 al 255 separados por puntos, mientras que las IPv6 son mucho más complejas, hasta 4 veces más largas (ejemplo: 2001:0db8:3c4d:0015:0000:0000:1a2f:1a2b).', 'pn_39_redes', (select id from public.topics where slug = 'pn-39-redes'), 3, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, Dirección IP', 'En su versión v6, las direcciones IP son mucho más complejas, siendo hasta 4 veces más largas, más seguras y permitiendo un gran número de sistemas conectados a Internet.', null, 'd0c4bcd48b2ac94ec37a5c80e674105a0202d09050f80c2a84e2f6995fef19d6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd0c4bcd48b2ac94ec37a5c80e674105a0202d09050f80c2a84e2f6995fef19d6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hasta 4 veces más largas, más seguras y permiten un gran número de sistemas conectados a Internet.', true), ('B', 'Más cortas, porque solo usan números del 0 al 255.', false), ('C', 'Idénticas en longitud, pero escritas en formato hexadecimal.', false)) as v(label, body, ok)
)
