with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Estrategia Nacional de Ciberseguridad 2019, en función de la naturaleza del hecho punible, de la autoría, de su motivación o de los daños infligidos, dentro de la cibercriminalidad se podrá hablar de:', 'La Estrategia define la cibercriminalidad como el conjunto de actividades ilícitas cometidas en el ciberespacio en las que resulta determinante la utilización de herramientas tecnológicas, y distingue ciberterrorismo, ciberdelito y hacktivismo.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347'), 'Estrategia Nacional de Ciberseguridad 2019, cap. 2', 'en función de la naturaleza del hecho punible en sí, de la autoría, de su motivación, o de los daños infligidos, se podrá hablar así de ciberterrorismo, de ciberdelito, o en su caso, de hacktivismo.', null, '91e5a2e2c6c4a6079d0e4148d5f804cc7e06a8675dc549b29045de4617748cd0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '91e5a2e2c6c4a6079d0e4148d5f804cc7e06a8675dc549b29045de4617748cd0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ciberterrorismo, ciberdelito o hacktivismo.', true), ('B', 'Ciberespionaje, ciberdefensa o ciberseguridad.', false), ('C', 'Ciberacoso, ciberbullying o grooming.', false)) as v(label, body, ok)
)
