with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el glosario de ciberseguridad de INCIBE, el malware cuya funcionalidad es «secuestrar» un dispositivo o la información que contiene, de forma que si la víctima no paga el rescate no podrá acceder a ella, se denomina:', 'INCIBE define el ransomware como el malware que «secuestra» un dispositivo o su información y exige un rescate. El spyware recopila información y la envía a un tercero sin consentimiento.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 1, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, Ransomware', 'Malware cuya funcionalidad es «secuestrar» un dispositivo (en sus inicios) o la información que contiene de forma que si la víctima no paga el rescate, no podrá acceder a ella.', null, '6e4fb43078956d2d0a81ef86dd037152e1b3abef89f8e855d970cb3fe68496e4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e4fb43078956d2d0a81ef86dd037152e1b3abef89f8e855d970cb3fe68496e4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Spyware.', false), ('B', 'Adware.', false), ('C', 'Ransomware.', true)) as v(label, body, ok)
)
