  select 'Según INCIBE, las «cartas nigerianas» o estafa nigeriana consisten en:', 'INCIBE describe las cartas nigerianas como un fraude en el que el gancho es la expectativa de ganar mucho dinero mediante unas sencillas gestiones; la transferencia prometida por los estafadores nunca llega a tener lugar.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 2, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, Cartas nigerianas', 'Se trata de una comunicación inesperada mediante correo electrónico carta o mensajería instantánea en las que el remitente promete negocios muy rentables.', null, '366821e4f816f724c206eed06583740572aa76a08c3d5ee9dcc66aa9fc5f6084', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '366821e4f816f724c206eed06583740572aa76a08c3d5ee9dcc66aa9fc5f6084')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El envío masivo de mensajes SMS con enlaces que instalan un troyano bancario.', false), ('B', 'Una comunicación inesperada en la que el remitente promete negocios muy rentables para que la víctima acabe transfiriendo una fuerte cantidad de dinero.', true), ('C', 'La captura de los datos de la banda magnética de una tarjeta en un cajero manipulado.', false)) as v(label, body, ok)
)
