  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según INCIBE, ¿qué proporción del malware actual son troyanos?', 'El glosario indica que la mayor parte del malware actual son troyanos, más del 80 %; los ordenadores infectados se denominan bots o zombis y el grupo controlado por un C&C, botnet o red zombie.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 3, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, Troyano', 'La mayor parte del malware actual son Troyanos, más del 80%.', null, '44c8ce9e08eeb0b38dec58fcbd364f32e7420c402801d09f1a722ce484993b01', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '44c8ce9e08eeb0b38dec58fcbd364f32e7420c402801d09f1a722ce484993b01')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Más del 80 %.', true), ('B', 'Alrededor del 50 %.', false), ('C', 'Menos del 20 %.', false)) as v(label, body, ok)
)
