with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según INCIBE, lo que distingue a los gusanos de los troyanos es que los gusanos:', 'Los troyanos dependen de que el usuario acceda a una web maliciosa o ejecute un fichero; los gusanos se propagan solos. Infectar ficheros ejecutables o sectores de arranque es la característica de los virus.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 3, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, Gusano', 'Mientras que los troyanos dependen de que un usuario acceda a una web maliciosa o ejecute un fichero infectado, los gusanos realizan copias de sí mismos, infectan a otros ordenadores y se propagan automáticamente en una red independientemente de la acción humana.', null, 'ee092a9e17e2bb7676a41a41e6c25b85f238b33c2bd0022d253f936a752118f6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee092a9e17e2bb7676a41a41e6c25b85f238b33c2bd0022d253f936a752118f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Necesitan que el usuario acceda a una web maliciosa o ejecute un fichero infectado.', false), ('B', 'Solo infectan los sectores de arranque de los dispositivos de almacenamiento.', false), ('C', 'Realizan copias de sí mismos y se propagan automáticamente en una red independientemente de la acción humana.', true)) as v(label, body, ok)
)
