with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según INCIBE, el tipo de spoofing que consiste en falsear la tabla que relaciona una dirección MAC con la dirección IP del ordenador, de modo que lo que se envíe a un usuario sea direccionado al atacante, es el:', 'INCIBE distingue IP, ARP, DNS, web y mail spoofing. El ARP spoofing falsea la tabla ARP (Address Resolution Protocol). El DNS spoofing crea una relación falsa entre IP y nombre de dominio.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 3, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, Spoofing', 'ARP spoofing: es la suplantación de identidad por falsificación de tabla ARP. ARP (Address Resolution Protocol) es un protocolo de nivel de red que relaciona una dirección MAC con la dirección IP del ordenador.', null, 'deb5eb84ccdb6595678758f89d102d31051648b578c5afd61f4ed801c54e6749', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'deb5eb84ccdb6595678758f89d102d31051648b578c5afd61f4ed801c54e6749')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'DNS spoofing.', false), ('B', 'ARP spoofing.', true), ('C', 'Mail spoofing.', false)) as v(label, body, ok)
)
