with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según INCIBE, la amenaza avanzada persistente (APT) se caracteriza, entre otras cosas, por:', 'INCIBE describe la APT como un ataque sigiloso y prolongado en el tiempo, con diferentes formas de ataque, cuyo objetivo es vigilar, exfiltrar datos o modificar recursos de la organización.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 3, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'Glosario INCIBE, APT', 'se caracteriza por realizarse con sigilo, permaneciendo activo y oculto durante mucho tiempo, utilizando diferentes formas de ataque. Suelen estar patrocinados por compañías, mafias o un estado.', null, '6e78e9a47e36c4bbfb1b0b5de4fe9face9c7dedfa7305d7856ab4f62084a7645', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e78e9a47e36c4bbfb1b0b5de4fe9face9c7dedfa7305d7856ab4f62084a7645')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Saturar el servidor de la víctima con peticiones simultáneas durante un breve periodo.', false), ('B', 'Propagarse exclusivamente mediante dispositivos USB extraíbles.', false), ('C', 'Realizarse con sigilo, permaneciendo activa y oculta durante mucho tiempo, y estar patrocinada a menudo por compañías, mafias o un estado.', true)) as v(label, body, ok)
)
