with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento de Armas (RD 137/1993), se entiende por arma de fuego:', 'El art. 2.12 del Reglamento de Armas define el arma de fuego como arma portátil con cañón que lanza (o está concebida o puede transformarse fácilmente para lanzar) un perdigón, bala o proyectil por la acción de un combustible propulsor. Las de gas comprimido son otra clase (art. 2.9).', 'pn_42_armas', (select id from public.topics where slug = 'pn-42-armas'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Art. 2.12 Reglamento de Armas', '12. Arma de fuego: Toda arma portátil que tenga cañón y que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un perdigón, una bala o un proyectil por la acción de un combustible propulsor.', null, '05398785c0029418c6225e9ffde76296c62dad4a52d55303640261c4eee2b746', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '05398785c0029418c6225e9ffde76296c62dad4a52d55303640261c4eee2b746')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Toda arma portátil que tenga cañón y que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un perdigón, una bala o un proyectil por la acción de un combustible propulsor.', true), ('B', 'Toda arma, portátil o no, que lance un proyectil por la acción de un gas comprimido o de un combustible propulsor.', false), ('C', 'Toda arma portátil que tenga cañón rayado y lance proyectiles por la acción de la pólvora negra.', false)) as v(label, body, ok)
)
