  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento de Armas, el arma de fuego que después de cada disparo se recarga automáticamente y con la que solo es posible efectuar un disparo al accionar el disparador cada vez es el arma:', 'El art. 2.21 define así el arma semiautomática. En la automática se pueden efectuar varios disparos sucesivos mientras permanezca accionado el disparador (art. 2.5), y en la de repetición la recarga la hace un mecanismo accionado por el tirador (art. 2.15).', 'pn_42_armas', (select id from public.topics where slug = 'pn-42-armas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Art. 2.5 y 2.21 Reglamento de Armas', '21. Arma semiautomática: Arma de fuego que después de cada disparo se recarga automáticamente y con la que solo es posible efectuar un disparo al accionar el disparador cada vez.', null, 'cef2107374461be4e24deccd5e08853cf7acb986b5c4518ab82b55dac2d84121', false
