  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento de Armas, la munición comprende:', 'El art. 2.29 define la munición como el cartucho completo o sus componentes (vainas, cebos, carga propulsora, balas o proyectiles), siempre que estén autorizados en territorio nacional.', 'pn_42_armas', (select id from public.topics where slug = 'pn-42-armas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Art. 2.29 Reglamento de Armas', '29. Munición: Cartucho completo o sus componentes, incluidas las vainas, los cebos, la carga propulsora, las balas o los proyectiles utilizados en un arma de fuego, siempre que estos componentes estén autorizados en territorio nacional.', null, '11db56a5bc1945728dbd4b106af120f44d4aa8dfff5132a44ea42b833943c3be', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '11db56a5bc1945728dbd4b106af120f44d4aa8dfff5132a44ea42b833943c3be')
