), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cartucho completo o sus componentes, incluidas las vainas, los cebos, la carga propulsora, las balas o los proyectiles utilizados en un arma de fuego, siempre que estén autorizados en territorio nacional.', true), ('B', 'Únicamente el cartucho completo, nunca sus componentes por separado.', false), ('C', 'Los proyectiles y la carga propulsora, pero no las vainas ni los cebos.', false)) as v(label, body, ok)
)
