select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del Reglamento de Armas, las ballestas pertenecen a la:', 'El art. 3 incluye en la 7.ª categoría, entre otras, las armas de inyección anestésica, las ballestas, las armas para lanzar cabos, las de sistema Flobert y las de alarma y señales. La 5.ª categoría es la de las armas blancas.', 'pn_42_armas', (select id from public.topics where slug = 'pn-42-armas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Art. 3 (7.ª categoría) Reglamento de Armas', '7.ª categoría: 1. Armas de inyección anestésica capaces de lanzar proyectiles que faciliten la captura o control de animales, anestesiándolos a distancia durante algún tiempo. 2. Las ballestas.', null, 'b8e1daf50fedd1beae75ddeade89400b1c8664669331878073899441ed867efc', false
