  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento de Armas, la licencia de armas B:', 'El art. 99.6 fija para la licencia B una validez de cinco años, prohíbe poseer más de una y limita cada licencia a un arma. La licencia D autoriza hasta cinco armas de la categoría 2.ª, 2 (art. 100.2).', 'pn_42_armas', (select id from public.topics where slug = 'pn-42-armas'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Art. 99.6 Reglamento de Armas', '6. Estas licencias tendrán cinco años de validez, al cabo de los cuales, para poder usar las armas autorizadas con ellas, habrán de solicitarse nuevas licencias en la misma forma que las anteriores. Nadie podrá poseer más de una licencia B, y cada licencia no amparará más de un arma.', null, '848f89fc0d686c4b769b060d71d4a80037039e786a6a14709c975b9c367e741e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '848f89fc0d686c4b769b060d71d4a80037039e786a6a14709c975b9c367e741e')
