with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el texto refundido de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial (RDLeg 6/2015), los vehículos de servicios de urgencia:', 'El art. 44.4 de la Ley de Tráfico remite al reglamento el uso de otras señales ópticas y acústicas por los vehículos de urgencia; el RGC lo desarrolla en los arts. 68.2 y 111-113.', 'pn_43_vehiculo_prioritario', (select id from public.topics where slug = 'pn-43-vehiculo-prioritario'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722'), 'Art. 44.4 Ley de Tráfico (RDLeg 6/2015)', '4. Los vehículos de servicios de urgencia y otros vehículos especiales podrán utilizar otras señales ópticas y acústicas en los casos y en las condiciones que reglamentariamente se determinen.', null, 'd2bff576f2ca4f49bc2158890300ec9347c7e081f6626a1b5c75d8e941118bf8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd2bff576f2ca4f49bc2158890300ec9347c7e081f6626a1b5c75d8e941118bf8')
  returning id
