insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-43-vehiculo-prioritario' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento General de Circulación, tienen prioridad de paso sobre los demás vehículos y otros usuarios de la vía:', 'El art. 67.1 del RGC concede prioridad de paso a los vehículos de servicios de urgencia, públicos o privados, siempre que se hallen en servicio de tal carácter; pueden además circular por encima de los límites de velocidad en los casos y condiciones que fija el Reglamento.', 'pn_43_vehiculo_prioritario', (select id from public.topics where slug = 'pn-43-vehiculo-prioritario'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 67.1 Reglamento General de Circulación', '1. Tendrán prioridad de paso sobre los demás vehículos y otros usuarios de la vía los vehículos de servicios de urgencia, públicos o privados, cuando se hallen en servicio de tal carácter.', null, '93a528628eb484a4077578323418e2b71013c85c7b82117735d494984e2967d0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '93a528628eb484a4077578323418e2b71013c85c7b82117735d494984e2967d0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los vehículos de servicios de urgencia públicos, nunca los privados.', false), ('B', 'Los vehículos de servicios de urgencia, públicos o privados, cuando se hallen en servicio de tal carácter.', true), ('C', 'Los vehículos oficiales de las Administraciones públicas en cualquier caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
