  select 'Según el artículo 67 del Reglamento General de Circulación, los vehículos prioritarios en servicio urgente:', 'El art. 67.1 permite a los vehículos prioritarios circular por encima de los límites de velocidad y quedar exentos de otras normas o señales, pero solo en los casos y condiciones de esa sección del RGC.', 'pn_43_vehiculo_prioritario', (select id from public.topics where slug = 'pn-43-vehiculo-prioritario'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 67.1 Reglamento General de Circulación', 'Podrán circular por encima de los límites de velocidad y estarán exentos de cumplir otras normas o señales en los casos y con las condiciones que se determinan en esta sección', null, '03a4b1158e4edac77f6ce071cd396ef77d8b754f098d3adb750468a05a5d60ae', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '03a4b1158e4edac77f6ce071cd396ef77d8b754f098d3adb750468a05a5d60ae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrán circular por encima de los límites de velocidad y estarán exentos de cumplir otras normas o señales en los casos y con las condiciones que se determinan.', true), ('B', 'Deberán respetar en todo caso los límites de velocidad, aunque no la prioridad de paso.', false), ('C', 'Solo podrán superar los límites de velocidad en autopistas y autovías.', false)) as v(label, body, ok)
)
