  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los vehículos de auxilio en vías públicas (grúas).', true), ('B', 'Los vehículos de extinción de incendios.', false), ('C', 'Los vehículos de asistencia sanitaria, pública o privada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
