  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento General de Circulación, como regla general, los conductores de vehículos prioritarios advertirán de su presencia mediante:', 'El art. 68.2 exige la utilización simultánea de la señal luminosa y de las señales acústicas especiales. El avisador acústico intermitente y la luz de emergencia son lo que debe usar el vehículo no prioritario en servicio de urgencia (art. 70.1).', 'pn_43_vehiculo_prioritario', (select id from public.topics where slug = 'pn-43-vehiculo-prioritario'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 68.2 Reglamento General de Circulación', 'y cuyos conductores adviertan de su presencia mediante la utilización simultánea de la señal luminosa y del aparato emisor de señales acústicas especiales previstos en el anexo XI del Reglamento General de Vehículos.', null, '72dd96b3044c759637dd77d03695fada389cb564512743ca43c9324da3710f1e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '72dd96b3044c759637dd77d03695fada389cb564512743ca43c9324da3710f1e')
