with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento General de Circulación, el conductor de un vehículo no prioritario que, por circunstancias especialmente graves, se vea forzado a efectuar un servicio reservado a los prioritarios, procurará que los demás usuarios lo adviertan:', 'El art. 70.1 regula el vehículo no prioritario en servicio de urgencia: avisador acústico intermitente y luz de emergencia, o pañuelo o procedimiento similar. Debe respetar las normas de circulación, sobre todo en intersecciones (art. 70.2).', 'pn_43_vehiculo_prioritario', (select id from public.topics where slug = 'pn-43-vehiculo-prioritario'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 70.1 Reglamento General de Circulación', 'utilizando para ello el avisador acústico en forma intermitente y conectando la luz de emergencia, si se dispusiera de ella, o agitando un pañuelo o procedimiento similar.', null, 'f67a76b67dc9d6da8090926f8a4022af2c778d5f406455ca0f7009e5773ee529', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f67a76b67dc9d6da8090926f8a4022af2c778d5f406455ca0f7009e5773ee529')
