  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento General de Circulación, los agentes encargados de la vigilancia del tráfico y los usuarios de vehículos de policía podrán dar órdenes o indicaciones a los usuarios mientras hacen uso de la señal:', 'El art. 141.3 permite dar órdenes o indicaciones mientras se usa la señal V-1 (la de los vehículos prioritarios), por megafonía o cualquier medio claramente perceptible. La V-2 es la de obras, servicios y vehículos de auxilio (art. 113).', 'pn_43_vehiculo_prioritario', (select id from public.topics where slug = 'pn-43-vehiculo-prioritario'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 141.3 Reglamento General de Circulación', '3. Los agentes de la autoridad encargados de la vigilancia del tráfico y los usuarios de vehículos de policía, podrán dar órdenes o indicaciones a los usuarios mientras hacen uso de la señal V-1 que establece el Reglamento General de Vehículos, a través de la megafonía o por cualquier otro medio que pueda ser percibido claramente por aquellos', null, '7df75d6a9d40096becf1a51b5305674503cb3fde23962d6cc8e2439d2fd8732e', false
