insert into public.sources (title, url, kind, publisher, published_on) values ('Dirección General de Tráfico · Muévete con seguridad (ADAS, clasificación de seguridad de vehículos, cinturón, moto, seguridad vial laboral, fatiga, distracciones, conducción preventiva, frenado, coche, velocidad)', 'https://www.dgt.es/muevete-con-seguridad/', 'web_oficial'::public.source_kind, 'Dirección General de Tráfico (web oficial dgt.es)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-44-seguridad-vehiculos', 'Tema 44. La seguridad en la conducción de vehículos prioritarios: seguridad activa y pasiva') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-44-seguridad-vehiculos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Dirección General de Tráfico, el elemento más importante para la seguridad pasiva del vehículo es:', 'La DGT califica el cinturón como el elemento más importante de seguridad pasiva por ser el único freno del cuerpo en caso de impacto. El airbag es su complemento, no su sustituto, y el frenado de emergencia es un sistema de ayuda a la conducción.', 'pn_44_seguridad_vehiculos', (select id from public.topics where slug = 'pn-44-seguridad-vehiculos'), 1, 'es', true, (select id from public.sources where url = 'https://www.dgt.es/muevete-con-seguridad/'), 'DGT, «Conducir sin cinturón de seguridad»', 'El cinturón es el elemento más importante para la seguridad pasiva porque es el único freno del cuerpo en caso de impacto, tanto para el conductor como para el resto de pasajeros, tanto en los asientos delanteros como traseros.', null, '47247bc3f334c0b343a10c7b1947a0c2a178314848770d95812e3e5bb44fc39e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '47247bc3f334c0b343a10c7b1947a0c2a178314848770d95812e3e5bb44fc39e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El airbag frontal, porque sustituye al cinturón en caso de choque.', false), ('B', 'El sistema de frenado de emergencia autónomo.', false), ('C', 'El cinturón de seguridad, porque es el único freno del cuerpo en caso de impacto.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
