  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Dirección General de Tráfico, en relación con el cinturón de seguridad, el airbag es:', 'La DGT insiste en que el airbag no cumple su objetivo sin el cinturón debidamente colocado: su utilidad empieza cuando acaba la del cinturón.', 'pn_44_seguridad_vehiculos', (select id from public.topics where slug = 'pn-44-seguridad-vehiculos'), 1, 'es', true, (select id from public.sources where url = 'https://www.dgt.es/muevete-con-seguridad/'), 'DGT, «En coche» (airbag)', 'El airbag es el complemento del cinturón de seguridad, no su sustituto. De hecho, el airbag no cumple su objetivo sin el cinturón debidamente colocado.', null, 'b1874fd4c0e5ec078c05662f5fd61b1a41f91789baa6ae5cd41694016dc0b49d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b1874fd4c0e5ec078c05662f5fd61b1a41f91789baa6ae5cd41694016dc0b49d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
