with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Dirección General de Tráfico, el reposacabezas es:', 'La DGT recuerda que el reposacabezas no es un elemento de confort sino de seguridad pasiva, que bien colocado evita el efecto látigo.', 'pn_44_seguridad_vehiculos', (select id from public.topics where slug = 'pn-44-seguridad-vehiculos'), 1, 'es', true, (select id from public.sources where url = 'https://www.dgt.es/muevete-con-seguridad/'), 'DGT, «En coche» (reposacabezas)', 'El reposacabezas no es un elemento de confort, sino de seguridad pasiva que bien colocado evita el efecto látigo y minimiza las lesiones cervicales.', null, 'd0020b36517f6f50c8f697bf1e2883a0b9f59e183d8296b7680650d55d560369', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd0020b36517f6f50c8f697bf1e2883a0b9f59e183d8296b7680650d55d560369')
