insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-45-prl-seguridad-vial', 'Tema 45. Prevención de riesgos laborales en seguridad vial: factores del tráfico y riesgos en la conducción') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-45-prl-seguridad-vial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, de Prevención de Riesgos Laborales, para calificar un riesgo laboral desde el punto de vista de su gravedad se valorarán conjuntamente:', 'El art. 4.2.º de la Ley 31/1995 define el riesgo laboral como la posibilidad de que un trabajador sufra un daño derivado del trabajo y manda valorar conjuntamente la probabilidad y la severidad del daño. Se aplica también a los riesgos de la conducción en el trabajo.', 'pn_45_prl_seguridad_vial', (select id from public.topics where slug = 'pn-45-prl-seguridad-vial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.2.º Ley 31/1995', '2.º Se entenderá como «riesgo laboral» la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo. Para calificar un riesgo desde el punto de vista de su gravedad, se valorarán conjuntamente la probabilidad de que se produzca el daño y la severidad del mismo.', null, 'a2a21d19b24cf0f52c4a8bbe405bfd431fd1024dc0c086758c1f5c2da8d409e9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a2a21d19b24cf0f52c4a8bbe405bfd431fd1024dc0c086758c1f5c2da8d409e9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La probabilidad de que se produzca el daño y la severidad del mismo.', true), ('B', 'El número de trabajadores expuestos y la duración de la exposición.', false), ('C', 'El coste económico del daño y su frecuencia histórica.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, de Prevención de Riesgos Laborales, se entenderá por equipo de protección individual:', 'El art. 4.8.º define el EPI como equipo llevado o sujetado por el trabajador para protegerle, junto con sus complementos o accesorios. Las máquinas o aparatos son «equipo de trabajo» (art. 4.6.º).', 'pn_45_prl_seguridad_vial', (select id from public.topics where slug = 'pn-45-prl-seguridad-vial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.8.º Ley 31/1995', '8.º Se entenderá por «equipo de protección individual» cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud en el trabajo, así como cualquier complemento o accesorio destinado a tal fin.', null, '2a6487e5ccf82959e9fbce91e6750160a29d64ee1afec69ef95e67d752e822cb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2a6487e5ccf82959e9fbce91e6750160a29d64ee1afec69ef95e67d752e822cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cualquier máquina, aparato o instrumento utilizado en el trabajo.', false), ('B', 'Cualquier medida técnica que proteja de forma colectiva a los trabajadores.', false), ('C', 'Cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud en el trabajo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, de Prevención de Riesgos Laborales, los equipos de protección individual deberán utilizarse:', 'El art. 17.2 configura el EPI como medida subsidiaria, coherente con el principio de anteponer la protección colectiva a la individual (art. 15.1.h).', 'pn_45_prl_seguridad_vial', (select id from public.topics where slug = 'pn-45-prl-seguridad-vial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 17.2 Ley 31/1995', 'Los equipos de protección individual deberán utilizarse cuando los riesgos no se puedan evitar o no puedan limitarse suficientemente por medios técnicos de protección colectiva o mediante medidas, métodos o procedimientos de organización del trabajo.', null, '450182a8b762f624c724699ddeb4d459717d5460af6896675f823ef917945679', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '450182a8b762f624c724699ddeb4d459717d5460af6896675f823ef917945679')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre, con preferencia sobre cualquier medida de protección colectiva.', false), ('B', 'Solo cuando así lo solicite el trabajador afectado.', false), ('C', 'Cuando los riesgos no se puedan evitar o no puedan limitarse suficientemente por medios técnicos de protección colectiva o mediante medidas de organización del trabajo.', true)) as v(label, body, ok)
)
