insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 33/1986, de 10 de enero, Reglamento de Régimen Disciplinario de los Funcionarios de la Administración del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-46-regimen-disciplinario', 'IV.6 Régimen disciplinario: faltas, sanciones y procedimiento (RD 33/1986)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-46-regimen-disciplinario' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ámbito y responsabilidad disciplinaria (arts. 1-4 y 9-13 RD 33/1986)"},{"n":"2","title":"Faltas muy graves, graves y leves (arts. 5-8 RD 33/1986)"},{"n":"3","title":"Sanciones y su graduación (arts. 14-18 RD 33/1986)"},{"n":"4","title":"Extinción de la responsabilidad disciplinaria (arts. 19-22 RD 33/1986; prescripción, art. 97 TREBEP)"},{"n":"5","title":"Iniciación: información reservada, órgano competente, instructor y secretario (arts. 27-31 RD 33/1986)"},{"n":"6","title":"Abstención, recusación y medidas provisionales (arts. 32-33 RD 33/1986)"},{"n":"7","title":"Instrucción: pliego de cargos, prueba, vista y propuesta de resolución (arts. 34-44 RD 33/1986)"},{"n":"8","title":"Terminación, órganos competentes, ejecución y anotación (arts. 45-51 RD 33/1986)"}]'::jsonb, '["Art. 5 RD 33/1986: «Las faltas cometidas por los funcionarios en el ejercicio de sus cargos podrán ser muy graves, graves y leves.»","Art. 7.1.l) RD 33/1986: «l) El incumplimiento injustificado de la jornada de trabajo que acumulado suponga un mínimo de diez horas al mes.»","Art. 8 RD 33/1986: «b) La falta de asistencia injustificada de un día.»","Art. 16 RD 33/1986: «Los funcionarios sancionados con traslado con cambio de residencia, no podrán obtener nuevo destino por ningún procedimiento en la localidad desde la que fueron trasladados, durante tres años, cuando hubiere sido impuesta por falta muy grave, y durante uno cuando hubiere correspondido a la comisión de una falta grave.»","Art. 18.2 RD 33/1986: «Para la imposición de sanciones por faltas leves no será preceptiva la previa instrucción del expediente al que se refiere el apartado anterior, salvo el trámite de audiencia al inculpado que deberá evacuarse en todo caso.»","Art. 27 RD 33/1986: «El procedimiento se iniciará siempre de oficio, por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, moción razonada de los subordinados o denuncia.»","Art. 28 RD 33/1986: «El órgano competente para incoar el procedimiento podrá acordar previamente la realización de una información reservada.»","Art. 29.1 RD 33/1986: «Será competente para ordenar la incoación del expediente disciplinario, el Subsecretario del Departamento en que esté destinado el funcionario, en todo caso.»","Art. 30 RD 33/1986: «En la resolución por la que se incoe el procedimiento se nombrará Instructor, que deberá ser un funcionario público perteneciente a un cuerpo o escala de igual o superior grupo al del inculpado»","Art. 32.3 RD 33/1986: «La abstención y la recusación se plantearán ante la Autoridad que acordó el nombramiento, quien deberá resolver en el término de tres días.»","Art. 35.1 RD 33/1986: «A la vista de las actuaciones practicadas y en un plazo no superior a un mes, contados a partir de la incoación del procedimiento, el Instructor formulará el correspondiente pliego de cargos»","Art. 36 RD 33/1986: «El pliego de cargos se notificará al inculpado concediéndosele un plazo de diez días para que pueda contestarlo»","Art. 45.2 RD 33/1986: «La resolución habrá de ser motivada y en ella no se podrán aceptar hechos distintos de los que sirvieron de base al pliego de cargos y a la propuesta de resolución, sin perjuicio de su distinta valoración jurídica.»","Art. 49 RD 33/1986: «Las sanciones disciplinarias se ejecutarán según los términos de la resolución en que se imponga, y en el plazo máximo de un mes, salvo que, cuando por causas justificadas, se establezca otro distinto en dicha resolución.»","Art. 97.1 TREBEP: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216', null, null, null, 'Otras normas citadas: TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719)'
