insert into public.sources (title, url, kind, publisher, published_on) values ('Resolución de 13 de mayo de 2019, de la Dirección General de Trabajo, por la que se registra y publica el IV Convenio colectivo único para el personal laboral de la Administración General del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-48-convenio-unico', 'IV.8 El IV Convenio único para el personal laboral de la AGE: ámbito, clasificación profesional y condiciones de trabajo') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-48-convenio-unico' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ámbito de aplicación, personal excluido y vigencia (arts. 1-4 IV Convenio único)"},{"n":"2","title":"Igualdad y conciliación (arts. 5-6)"},{"n":"3","title":"Clasificación profesional: grupos, familias profesionales y especialidades (arts. 7-11)"},{"n":"4","title":"Órganos de seguimiento: Comisión Negociadora, Comisión Paritaria y Subcomisiones (arts. 12-21)"},{"n":"5","title":"Ingreso, promoción interna y período de prueba (arts. 27-33)"},{"n":"6","title":"Provisión y movilidad: concurso abierto y permanente, movilidad funcional y de distinto grupo (arts. 34-53)"},{"n":"7","title":"Jornada, vacaciones, licencias y permisos (arts. 64-75)"},{"n":"8","title":"Suspensión del contrato, excedencias y reingreso (arts. 93-98)"},{"n":"9","title":"Régimen disciplinario: faltas, sanciones, prescripción y procedimiento (arts. 99-123)"}]'::jsonb, '["Art. 1.1 IV Convenio único AGE: «El presente Convenio colectivo será de aplicación al personal laboral de la Administración General del Estado y sus organismos autónomos.»","Art. 2 IV Convenio único AGE: «Quedan excluidos del ámbito de aplicación del presente Convenio: a) El personal laboral que presta servicios en el exterior.»","Art. 7.1 IV Convenio único AGE: «El sistema de clasificación que se contempla en el presente Convenio se estructura en grupos profesionales, familias profesionales y/o especialidades»","Art. 8.1 IV Convenio único AGE: «a) Grupo profesional M3: Título clasificado en el Nivel 3 del Marco Español de Cualificaciones para la Educación Superior o equivalentes.»","Art. 8.1 IV Convenio único AGE: «d) Grupo profesional E2: Título de Bachiller o Técnico o equivalentes.»","Art. 8.1 IV Convenio único AGE: «e) Grupo profesional E1: Título de Graduado en Educación Secundaria Obligatoria o Título Profesional Básico o equivalentes.»","Art. 8.1 IV Convenio único AGE: «f) Grupo profesional E0: Sin titulación prevista en el sistema educativo.»","Art. 32.1 IV Convenio único AGE: «cuya duración será de tres meses para los grupos profesionales M3 y M2 y de un mes para los demás trabajadores o trabajadoras, excepto para el personal sin titulación, para el que será de quince días laborables.»","Art. 36.1 IV Convenio único AGE: «El concurso de traslados abierto y permanente constituye el sistema ordinario de provisión y movilidad de los puestos de trabajo vacantes y de movilidad para el personal laboral fijo.»","Art. 48.4 IV Convenio único AGE: «La atribución del desempeño de un puesto de trabajo de dicho grupo profesional no podrá ser superior a ocho meses de duración en el plazo de dos años, computados de fecha a fecha»","Art. 73.1 IV Convenio único AGE: «Las vacaciones anuales retribuidas serán de veintidós días hábiles por año completo de servicios»","Art. 75 IV Convenio único AGE: «o) Hasta seis días cada año natural, por asuntos particulares no incluidos en los puntos anteriores.»","Art. 95.1 IV Convenio único AGE: «Una vez concedida, la duración mínima de permanencia en la misma es de cuatro meses y su duración máxima será indefinida.»","Art. 105 IV Convenio único AGE: «Por la comisión de faltas disciplinarias se pueden imponer las siguientes sanciones: a) Despido disciplinario. b) Suspensión de empleo y sueldo.»","Art. 112.1 IV Convenio único AGE: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses.»","Art. 117.1 IV Convenio único AGE: «La duración del procedimiento disciplinario no excederá de seis meses, a contar desde su incoación. Vencido este plazo sin que se haya dictado y notificado la resolución se producirá su caducidad.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414', null, null, null, null
  from public.topics t where t.slug = 'age-adm-48-convenio-unico'
