insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 47/2003, de 26 de noviembre, General Presupuestaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-52-modificaciones-credito', 'V.2 Los créditos presupuestarios: clasificación económica y modificaciones de crédito') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-52-modificaciones-credito' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Créditos y programas presupuestarios (art. 35 LGP)"},{"n":"2","title":"Estructura de los estados de gastos: clasificaciones orgánica, por programas y económica (arts. 39-40 LGP)"},{"n":"3","title":"Especialidad y especificación de los créditos (arts. 42-44 LGP)"},{"n":"4","title":"Modificaciones de crédito: clases (art. 51 LGP)"},{"n":"5","title":"Transferencias y sus restricciones (art. 52 LGP)"},{"n":"6","title":"Generaciones y ampliaciones (arts. 53-54 LGP)"},{"n":"7","title":"Créditos extraordinarios y suplementos de crédito: Estado, organismos autónomos y Seguridad Social (arts. 55-57 LGP)"},{"n":"8","title":"Incorporaciones, Fondo de Contingencia y anticipos de Tesorería (arts. 50, 58-60 LGP)"},{"n":"9","title":"Competencias en materia de modificaciones (arts. 61-63 LGP)"},{"n":"10","title":"Códigos de la clasificación económica del gasto (Resolución DGP de 20/01/2014)"}]'::jsonb, '["Art. 40.1.c) Ley 47/2003: «En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital.»","Art. 40.1.c) Ley 47/2003: «Los capítulos se desglosarán en artículos y estos, a su vez, en conceptos que podrán dividirse en subconceptos.»","Art. 42 Ley 47/2003: «Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley.»","Art. 52.1 Ley 47/2003: «a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes.»","Art. 52.1 Ley 47/2003: «c) No minorarán créditos extraordinarios o créditos que se hayan suplementado o ampliado en el ejercicio.»","Art. 53.1 Ley 47/2003: «Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial.»","Art. 53.3 Ley 47/2003: «La generación sólo podrá realizarse cuando se hayan efectuado los correspondientes ingresos que la justifican.»","Art. 54.3 Ley 47/2003: «Las ampliaciones de crédito que afecten a operaciones del presupuesto del Estado se financiarán con cargo al Fondo de Contingencia, conforme a lo previsto en el artículo 50 de esta ley, o con baja en otros créditos del presupuesto no financiero.»","Art. 55.1 Ley 47/2003: «a) Si la necesidad surgiera en operaciones no financieras del presupuesto, el crédito extraordinario o suplementario se financiará mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados.»","Art. 55.3 Ley 47/2003: «El Consejo de Ministros autorizará los créditos extraordinarios y suplementos de crédito para atender obligaciones del ejercicio corriente o de ejercicios anteriores si se hubiera anulado crédito en el ejercicio de procedencia, cuando se financien con cargo al Fondo de Contingencia.»","Art. 60.1 Ley 47/2003: «Con carácter excepcional, el Gobierno, a propuesta del Ministro de Economía, podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado»","Art. 62.1 Ley 47/2003: «c) Las incorporaciones de remanentes reguladas en el artículo 58.»","Anexo IV, cap. 1 Resolución DGP 20/01/2014 (clasificación económica): «No se incluyen en este capítulo las indemnizaciones por razón del servicio.»","Anexo IV, cap. 2 Resolución DGP 20/01/2014 (clasificación económica): «Son imputables a este capítulo los gastos originados por la adquisición de bienes que reúnan algunas de las características siguientes: a) Ser bienes fungibles b) Tener una duración previsiblemente inferior al ejercicio presupuestario c) No ser susceptibles de inclusión en inventario d) Ser, previsiblemente, gastos reiterativos»","Anexo IV, concepto 227 Resolución DGP 20/01/2014 (clasificación económica): «Se incluirán aquellos gastos que correspondan a actividades que siendo de la competencia de los organismos públicos se ejecuten mediante contrato con empresas externas o profesionales independientes.»","Anexo IV, cap. 6 Resolución DGP 20/01/2014 (clasificación económica): «Un gasto se considerará amortizable cuando contribuya al mantenimiento de la actividad del sujeto que lo realiza en ejercicios futuros.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: Resolución DGP 20/01/2014 (clasificación económica) (https://www.boe.es/buscar/act.php?id=BOE-A-2014-879)'
