insert into public.sources (title, url, kind, publisher, published_on) values ('Resolución de 28 de octubre de 2005, de la Secretaría de Estado de Justicia, por la que se publica el Acuerdo del Consejo de Ministros de 21 de octubre de 2005 por el que se aprueba el Plan de Transparencia Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-17951', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
