insert into public.sources (title, url, kind, publisher, published_on) values ('Convención contra la tortura y otros tratos o penas crueles, inhumanos o degradantes (Nueva York, 10 de diciembre de 1984). Instrumento de ratificación, BOE núm. 268, de 9 de noviembre de 1987', 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053', 'web_oficial'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado (BOE-A-1987-25053)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-27-derechos-humanos', 'Tema 27. Derechos Humanos: DUDH, CEDH, Convenio contra la Tortura, Protocolo facultativo y Mecanismo Nacional de Prevención de la Tortura') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-27-derechos-humanos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Declaración Universal de los Derechos Humanos (ONU, 1948)"},{"n":"2","title":"Convenio Europeo de Derechos Humanos: derechos y Tribunal Europeo de Derechos Humanos"},{"n":"3","title":"Convención de la ONU contra la tortura: definición, prohibición absoluta y Comité"},{"n":"4","title":"Protocolo facultativo: Subcomité para la Prevención y mecanismos nacionales"},{"n":"5","title":"El Defensor del Pueblo como Mecanismo Nacional de Prevención de la Tortura y su Consejo Asesor"}]'::jsonb, '["Introducción DUDH DUDH: «la Declaración fue proclamada por la Asamblea General de las Naciones Unidas en París, el 10 de diciembre de 1948 en su (Resolución 217 A (III)) como un ideal común para todos los pueblos y naciones.»","Art. 1 DUDH: «Todos los seres humanos nacen libres e iguales en dignidad y derechos y, dotados como están de razón y conciencia, deben comportarse fraternalmente los unos con los otros.»","Art. 9 DUDH: «Nadie podrá ser arbitrariamente detenido, preso ni desterrado.»","Art. 3 CEDH: «Artículo 3. Prohibición de la tortura. Nadie podrá ser sometido a tortura ni a penas o tratos inhumanos o degradantes.»","Art. 19 CEDH: «se instituye un Tribunal Europeo de Derechos Humanos, en lo sucesivo denominado «el Tribunal». Funcionará de manera permanente.»","Disp. final única LODP LO 3/1981: «Primero. El Defensor del Pueblo ejercerá las funciones del Mecanismo Nacional de Prevención de la Tortura de conformidad con la Constitución, la presente Ley y el Protocolo facultativo de la Convención contra la tortura»","Art. 1 Convención contra la tortura: «CUANDO DICHOS DOLORES O SUFRIMIENTOS SEAN INFLIGIDOS POR UN FUNCIONARIO PUBLICO U OTRA PERSONA EN EL EJERCICIO DE FUNCIONES PUBLICAS, A INSTIGACION SUYA, O CON SU CONSENTIMIENTO O AQUIESCENCIA.»","Art. 1 Convención contra la tortura: «NO SE CONSIDERARAN TORTURAS LOS DOLORES O SUFRIMIENTOS QUE SEAN CONSECUENCIA UNICAMENTE DE SANCIONES LEGITIMAS, O QUE SEAN INHERENTES O INCIDENTALES A ESTAS.»","Art. 2.3 Convención contra la tortura: «3. NO PODRA INVOCARSE UNA ORDEN DE UN FUNCIONARIO SUPERIOR O DE UNA AUTORIDAD PUBLICA COMO JUSTIFICACION DE LA TORTURA.»","Art. 3.1 Convención contra la tortura: «1. NINGUN ESTADO PARTE PROCEDERA A LA EXPULSION, DEVOLUCION O EXTRADICION DE UNA PERSONA A OTRO ESTADO CUANDO HAYA RAZONES FUNDADAS PARA CREER QUE ESTARIA EN PELIGRO DE SER SOMETIDA A TORTURA.»","Art. 15 Convención contra la tortura: «NINGUNA DECLARACION QUE SE DEMUESTRE QUE HA SIDO HECHA COMO RESULTADO DE TORTURA PUEDA SER INVOCADA COMO PRUEBA EN NINGUN PROCEDIMIENTO, SALVO EN CONTRA DE UNA PERSONA ACUSADA DE TORTURA COMO PRUEBA DE QUE SE HA FORMULADO LA DECLARACION.»","Art. 17.1 Convención contra la tortura: «EL COMITE ESTARA COMPUESTO DE DIEZ EXPERTOS DE GRAN INTEGRIDAD MORAL Y RECONOCIDA COMPETENCIA EN MATERIA DE DERECHOS HUMANOS, QUE EJERCERAN SUS FUNCIONES A TITULO PERSONAL.»","Art. 1 Protocolo facultativo de la Convención contra la tortura: «El objetivo del presente Protocolo es establecer un sistema de visitas periódicas a cargo de órganos internacionales y nacionales independientes a los lugares en que se encuentren personas privadas de su libertad, con el fin de prevenir la tortura»","Art. 3 Protocolo facultativo de la Convención contra la tortura: «Cada Estado Parte establecerá, designará o mantendrá, a nivel nacional, uno o varios órganos de visitas para la prevención de la tortura y otros tratos o penas crueles, inhumanos o degradantes (en adelante denominado el mecanismo nacional de prevención).»","Art. 2.2 CEDH: «b) Para detener a una persona conforme a derecho o para impedir la evasión de un preso o detenido legalmente.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053', null, null, null, 'Otras normas citadas: DUDH (https://www.un.org/es/about-us/universal-declaration-of-human-rights), CEDH (https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148), LO 3/1981 (https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325), Protocolo facultativo de la Convención contra la tortura (https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128)'
