insert into public.sources (title, url, kind, publisher, published_on) values ('Instituto Geográfico Nacional · Glosario del Atlas Didáctico (términos de geografía de la población, urbana, económica y medio ambiente)', 'https://educativo.ign.es/atlas-didactico/glosario/index.html', 'web_oficial'::public.source_kind, 'Instituto Geográfico Nacional (IGN-CNIG), recurso educativo oficial (CC BY 4.0)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-32-geografia-demografia', 'Tema 32. Geografía humana: la ciudad, la población y la demografía; contaminación y protección del medio ambiente') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-32-geografia-demografia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La población: densidad, natalidad, mortalidad y crecimiento"},{"n":"2","title":"Estructura de la población: pirámides y envejecimiento"},{"n":"3","title":"Transición demográfica y fuentes (padrón, censo)"},{"n":"4","title":"La ciudad: concepto, criterios, morfología y planos urbanos"},{"n":"5","title":"Procesos urbanos: éxodo rural, conurbación, ciudad dormitorio, tasa de urbanización"},{"n":"6","title":"Contaminación y medio ambiente: efecto invernadero y lluvia ácida"}]'::jsonb, '["IGN, Glosario: Densidad de población IGN, Glosario del Atlas Didáctico: «Relación entre la población total de un área y su superficie (d = P/S), expresada normalmente en habitantes por km2 (hab./km2).»","IGN, Glosario: Crecimiento natural o vegetativo IGN, Glosario del Atlas Didáctico: «Variación positiva o negativa de la población de un lugar debido a su movimiento natural (natalidad y mortalidad).»","IGN, Atlas Didáctico: Pirámides de población IGN, Atlas Didáctico (población, migraciones y ciudades): «La forma de representar la estructura por edades es la pirámide de población, donde los grupos de edad más jóvenes están en la base, y los grupos de edad mayores están en el vértice.»","IGN, Atlas Didáctico: Tipos de planos urbanos IGN, Atlas Didáctico (población, migraciones y ciudades): «En damero, ortogonal o en cuadrícula Las calles se cortan de manera perpendicular. Por ejemplo, se corresponde con la mayoría de los ensanches de las ciudades españolas.»","IGN, Glosario: Éxodo rural IGN, Glosario del Atlas Didáctico: «Desplazamiento masivo de la población residente en el medio rural hacia las ciudades.»","IGN, Glosario: Padrón IGN, Glosario del Atlas Didáctico: «Registro administrativo donde constan los vecinos del municipio y sus características básicas (edad, sexo, actividad profesional, domicilio...). Sus datos constituyen prueba de residencia en el municipio y del domicilio habitual en el mismo.»","IGN, Glosario: Tasa bruta de natalidad IGN, Glosario del Atlas Didáctico: «Se calcula dividiendo el número de nacimientos ocurridos durante un periodo determinado entre la población total de ese mismo periodo. El resultado se multiplica por mil.»","IGN, Glosario: Transición demográfica IGN, Glosario del Atlas Didáctico: «Proceso demográfico histórico por el que se pasa de un régimen demográfico antiguo caracterizado por unas altas tasas de natalidad y mortalidad, a un régimen demográfico moderno, con valores muy bajos de ambas tasas.»","IGN, Glosario: Envejecimiento de la población IGN, Glosario del Atlas Didáctico: «Proceso que tiene lugar en un país cuando el porcentaje de población con 65 años o más es superior al 12% de la población total.»","IGN, Glosario: Conurbación IGN, Glosario del Atlas Didáctico: «Conjunto de ciudades independientes que crecen espacialmente y se unen formando un continuo urbano mediante la unión física de sus periferias.»","IGN, Glosario: Ciudad dormitorio IGN, Glosario del Atlas Didáctico: «Núcleo urbano ubicado en las proximidades de una ciudad central, en el que buena parte de su población trabaja en otra ciudad más o menos próxima, generando importantes movimientos pendulares.»","IGN, Atlas Didáctico: Criterios para definir una ciudad IGN, Atlas Didáctico (población, migraciones y ciudades): «muestra la población en municipios de más de 10 000 habitantes (límite numérico a partir del cual un municipio se considera urbano en España).»","IGN, Atlas Didáctico: La morfología urbana IGN, Atlas Didáctico (población, migraciones y ciudades): «La morfología urbana es el aspecto externo, es decir, la forma que presenta la ciudad.»","IGN, Glosario: Lluvia ácida IGN, Glosario del Atlas Didáctico: «Está provocada por las emisiones de óxidos de nitrógeno y de azufre de fábricas, centrales térmicas y vehículos»","IGN, Glosario: Efecto invernadero IGN, Glosario del Atlas Didáctico: «Es un fenómeno natural, sin el que la vida sobre la tierra no sería posible tal y como la conocemos, pues sin él la temperatura media de la superficie sería de –18ºC.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/glosario/index.html'), 'https://educativo.ign.es/atlas-didactico/glosario/index.html', null, null, null, 'Otras normas citadas: IGN, Atlas Didáctico (población, migraciones y ciudades) (https://educativo.ign.es/atlas-didactico/poblacion-bach/)'
