insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-33-seguridad-delincuencia', 'Tema 33. La seguridad: concepto, seguridad pública y privada, seguridad nacional') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-33-seguridad-delincuencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La seguridad en la Constitución (arts. 104 y 149.1.29.ª CE)"},{"n":"2","title":"Seguridad pública (LOFCS)"},{"n":"3","title":"Seguridad ciudadana: objeto, fines y principios (LO 4/2015)"},{"n":"4","title":"Seguridad privada: concepto, fines y actividades (Ley 5/2014)"},{"n":"5","title":"Seguridad Nacional: concepto, principios, componentes y ámbitos (Ley 36/2015)"}]'::jsonb, '["Art. 104.1 CE: «1\\. Las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.»","Art. 1.1 LO 2/1986: «1\\. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.»","Art. 1.1 LO 4/2015: «1\\. La seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado»","Art. 3 Ley 36/2015: «A los efectos de esta ley se entenderá por Seguridad Nacional la acción del Estado dirigida a proteger la libertad, los derechos y bienestar de los ciudadanos»","Art. 9.1 Ley 36/2015: «1\\. Se consideran componentes fundamentales de la Seguridad Nacional a los efectos de esta ley la Defensa Nacional, la Seguridad Pública y la Acción Exterior»","Art. 1.1 Ley 5/2014: «Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública.»","Art. 149.1.29.ª CE: «29.ª Seguridad pública, sin perjuicio de la posibilidad de creación de policías por las Comunidades Autónomas en la forma que se establezca en los respectivos Estatutos en el marco de lo que disponga una ley orgánica.»","Art. 1.4 LO 2/1986: «4\\. El mantenimiento de la Seguridad Pública se ejercerá por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad.»","Art. 1.2 LO 4/2015: «orientadas a la tutela de la seguridad ciudadana, mediante la protección de personas y bienes y el mantenimiento de la tranquilidad de los ciudadanos.»","Art. 3 LO 4/2015: «c) La preservación de la seguridad y la convivencia ciudadanas.»","Art. 4.1 LO 4/2015: «se regirá por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someterá al control administrativo y jurisdiccional.»","Art. 4.3 LO 4/2015: «3\\. La actividad de intervención se justifica por la existencia de una amenaza concreta o de un comportamiento objetivamente peligroso que, razonablemente, sea susceptible de provocar un perjuicio real para la seguridad ciudadana»","Art. 4.2 Ley 36/2015: «2\\. Los principios básicos que orientarán la política de Seguridad Nacional son la unidad de acción, anticipación, prevención, eficiencia, sostenibilidad en el uso de los recursos, capacidad de resistencia y recuperación, coordinación y colaboración.»","Art. 2.1 Ley 5/2014: «realizadas o prestados por empresas de seguridad, despachos de detectives privados y personal de seguridad privada para hacer frente a actos deliberados o riesgos accidentales»","Art. 4.c Ley 5/2014: «c) Complementar el monopolio de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229), LO 2/1986 (https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859), Ley 36/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389), Ley 5/2014 (https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649)'
  from public.topics t where t.slug = 'pn-33-seguridad-delincuencia'
