insert into public.sources (title, url, kind, publisher, published_on) values ('Delegación del Gobierno para el Plan Nacional sobre Drogas · Información sobre drogas y otras conductas adictivas', 'https://pnsd.sanidad.gob.es/ciudadanos/informacion/home.htm', 'web_oficial'::public.source_kind, 'Ministerio de Sanidad · Delegación del Gobierno para el Plan Nacional sobre Drogas', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-34-drogodependencias', 'Tema 34. Drogodependencias: drogas, clasificación, consumo y últimas tendencias') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-34-drogodependencias' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Drogas y sus efectos: estimulantes, depresoras y alucinógenas (PNSD)"},{"n":"2","title":"Tabaco, alcohol y cannabis"},{"n":"3","title":"Cocaína y drogas de síntesis"},{"n":"4","title":"Otras conductas adictivas: ludopatía; bebidas energéticas"},{"n":"5","title":"Tendencias de consumo: encuesta EDADES 2024"},{"n":"6","title":"Tráfico de drogas en el Código Penal (art. 368)"}]'::jsonb, '["PNSD, Alcohol PNSD, «Información sobre drogas»: «El alcohol es una droga depresora del Sistema Nervioso Central que inhibe progresivamente las funciones cerebrales. Afecta a la capacidad de autocontrol, produciendo inicialmente euforia y desinhibición, por lo que puede confundirse con un estimulante.»","PNSD, Tabaco PNSD, «Información sobre drogas»: «Uno de sus componentes, la nicotina, posee una enorme capacidad adictiva, y es la causa por la que su consumo produce dependencia.»","PNSD, Cannabis PNSD, «Información sobre drogas»: «Sus efectos sobre el cerebro son debidos principalmente a uno de sus principios activos, el Tetrahidrocannabinol o THC»","PNSD, Cocaína PNSD, «Información sobre drogas»: «La cocaína es un potente estimulante del sistema nervioso central y una de las drogas más adictivas y peligrosas.»","EDADES 2024, Principales resultados EDADES 2024 (resumen ejecutivo): «las drogas con mayor prevalencia de consumo, en los últimos 12 meses, son el alcohol (76,5%), el tabaco (36,8%) y el cannabis (12,6%)»","PNSD, Tabaco PNSD, «Información sobre drogas»: «El tabaco es una droga estimulante del sistema nervioso central.»","Art. 368 Código Penal: «serán castigados con las penas de prisión de tres a seis años y multa del tanto al triplo del valor de la droga objeto del delito si se tratare de sustancias o productos que causen grave daño a la salud»","Art. 368 Código Penal: «los tribunales podrán imponer la pena inferior en grado a las señaladas en atención a la escasa entidad del hecho y a las circunstancias personales del culpable.»","PNSD, Drogas de síntesis PNSD, «Información sobre drogas»: «El éxtasis (3-4 metilendioximetanfetamina, abreviado como MDMA) es una droga de síntesis. Tiene efectos estimulantes y alucinógenos a la vez.»","PNSD, Drogas de síntesis PNSD, «Información sobre drogas»: «La fabricación en laboratorios clandestinos y el desconocimiento de su composición final, las convierte en especialmente peligrosas, pues los consumidores nunca saben exactamente qué están ingiriendo»","PNSD, Cocaína PNSD, «Información sobre drogas»: «Basuko o pasta de coca: Es sulfato de cocaína y se fuma mezclado con tabaco o marihuana.»","PNSD, Cannabis PNSD, «Información sobre drogas»: «Hachís: elaborado a partir de la resina almacenada en las flores de la planta hembra.»","EDADES 2024, Edad de inicio EDADES 2024 (resumen ejecutivo): «El inicio más precoz es para el alcohol (16,4 años) y el tabaco (16,6 años).»","EDADES 2024, Cannabis EDADES 2024 (resumen ejecutivo): «El cannabis es la sustancia ilegal con mayor prevalencia de consumo en España entre la población de 15 a 64 años.»","EDADES 2024, Policonsumo EDADES 2024 (resumen ejecutivo): «el 39,0% declara policonsumo (dos o más sustancias).»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://pnsd.sanidad.gob.es/ciudadanos/informacion/home.htm'), 'https://pnsd.sanidad.gob.es/ciudadanos/informacion/home.htm', null, null, null, 'Otras normas citadas: EDADES 2024 (resumen ejecutivo) (https://pnsd.sanidad.gob.es/profesionales/sistemasInformacion/sistemaInformacion/pdf/2024_Informe_Ejecutivo_EDADES_es.pdf), Código Penal (https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444)'
