insert into public.sources (title, url, kind, publisher, published_on) values ('Microsoft Learn · Modelo OSI, direccionamiento TCP/IP y subredes, DHCP, DNS, IPv6 y Firewall de Windows', 'https://learn.microsoft.com/es-es/windows-hardware/drivers/network/windows-network-architecture-and-the-osi-model', 'web_oficial'::public.source_kind, 'Microsoft (documentación técnica oficial, learn.microsoft.com)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-39-redes', 'Tema 39. Redes informáticas: modelo OSI, TCP/IP, dispositivos de red y direccionamiento IP') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-39-redes' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El modelo OSI y sus capas"},{"n":"2","title":"TCP/IP: dirección IP, octetos y máscara de subred"},{"n":"3","title":"Clases de direcciones IP y subredes; IPv4 e IPv6"},{"n":"4","title":"Dispositivos de red: router, puerta de enlace, proxy y cortafuegos"},{"n":"5","title":"Servicios de red: DHCP y DNS"},{"n":"6","title":"Redes LAN y WAN; dirección MAC"}]'::jsonb, '["Microsoft Learn, Arquitectura de red de Windows y el modelo OSI Microsoft Learn (redes): «Los sistemas operativos Microsoft Windows usan una arquitectura de red basada en el modelo de redes de siete capas desarrollado por la Organización Internacional de Normalización (ISO) en 1978.»","Microsoft Learn, Direccionamiento TCP/IP Microsoft Learn (redes): «Una dirección IP es un número de 32 bits. Identifica de forma única un host (equipo u otro dispositivo, como una impresora o enrutador) en una red TCP/IP.»","Microsoft Learn, DHCP Microsoft Learn (redes): «El Protocolo de configuración dinámica de host (DHCP) es un protocolo cliente-servidor que proporciona automáticamente un host de protocolo de Internet (IP) con su dirección IP y otra información de configuración relacionada, como la máscara de subred y la puerta de enlace de predeterminada.»","Microsoft Learn, DNS Microsoft Learn (redes): «DNS es un protocolo estándar del sector que asigna nombres de dominio a direcciones IP, lo que permite la resolución de nombres para computadoras y usuarios.»","Glosario INCIBE, LAN Glosario INCIBE: «Una LAN (del inglés Local Area Network) o Red de Área Local es una red informática de pequeña amplitud geográfica, que suele limitarse a espacios como una oficina, una vivienda o un edificio.»","Glosario INCIBE, Router Glosario INCIBE: «Es un dispositivo que distribuye tráfico de red entre dos o más diferentes redes.»","Microsoft Learn, Clases de red Microsoft Learn (redes): «Las redes de clase B usan una máscara de subred predeterminada de 255.255.0.0 y tienen de 128 a 191 como su primer octeto. La dirección 172.16.52.63 es una dirección de clase B.»","Microsoft Learn, Clases de red Microsoft Learn (redes): «Las redes de clase C usan una máscara de subred predeterminada de 255.255.255.0 y tienen de 192 a 223 como su primer octeto.»","Microsoft Learn, Máscara de subred Microsoft Learn (redes): «El protocolo TCP/IP usa la máscara de subred para determinar si un host está en la subred local o en una red remota.»","Microsoft Learn, Puerta de enlace predeterminada Microsoft Learn (redes): «Desde el punto de vista de TCP/IP, un enrutador especificado en un host, que vincula la subred del host con otras redes, se denomina puerta de enlace predeterminada.»","Microsoft Learn, Modelo OSI: capa física Microsoft Learn (redes): «La capa física es la capa más baja del modelo OSI. Esta capa administra la recepción y transmisión de la secuencia de bits sin procesar no estructurada a través de un medio físico.»","Glosario INCIBE, Dirección MAC Glosario INCIBE: «Una dirección MAC, también conocida como dirección física, es un valor de 48 bits único e irrepetible que identifica todo dispositivo conectado a una red.»","Glosario INCIBE, Proxy Glosario INCIBE: «El proxy es tanto el equipo, como el software encargado de dar el servicio, que hacen de intermediario en las peticiones de los equipos de la redes LAN hacia Internet.»","Glosario INCIBE, Cortafuegos Glosario INCIBE: «La funcionalidad básica de un cortafuego es asegurar que todas las comunicaciones entre la red e Internet se realicen conforme a las políticas de seguridad de la organización o corporación.»","Glosario INCIBE, TCP/IP Glosario INCIBE: «el protocolo TCP (Transfer Control Protocol), que se ocupa de garantizar que la transferencia se lleve a cabo de forma correcta y confiable.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://learn.microsoft.com/es-es/windows-hardware/drivers/network/windows-network-architecture-and-the-osi-model'), 'https://learn.microsoft.com/es-es/windows-hardware/drivers/network/windows-network-architecture-and-the-osi-model', null, null, null, 'Otras normas citadas: Glosario INCIBE (https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf)'
  from public.topics t where t.slug = 'pn-39-redes'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Centro Nacional de Inteligencia · La Inteligencia (el ciclo de Inteligencia)', 'https://www.cni.es/la-inteligencia', 'web_oficial'::public.source_kind, 'Centro Nacional de Inteligencia (web oficial cni.es)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-40-inteligencia-osint', 'Tema 40. Inteligencia: ciclo de inteligencia, fuentes (OSINT) y el Centro Nacional de Inteligencia') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-40-inteligencia-osint' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La Inteligencia y el ciclo de Inteligencia (CNI)"},{"n":"2","title":"Fases: dirección, planificación, obtención, elaboración y difusión"},{"n":"3","title":"Fuentes de obtención: HUMINT, OSINT, SIGINT y GEOINT"},{"n":"4","title":"El Centro Nacional de Inteligencia: naturaleza, principios y funciones (Ley 11/2002)"},{"n":"5","title":"Directiva de Inteligencia, Comisión Delegada y Secretario de Estado Director"}]'::jsonb, '["CNI, La Inteligencia: Obtención CNI, «La Inteligencia»: «OSINT Información procedente de fuentes abiertas»","CNI, La Inteligencia: Obtención CNI, «La Inteligencia»: «HUMINT Información procedente de fuentes humanas»","CNI, La Inteligencia: Difusión CNI, «La Inteligencia»: «Difusión Es el final del ciclo, resultado de todo el proceso. En esta fase, la Inteligencia se distribuye a sus destinatarios: las autoridades responsables de adoptar decisiones.»","Art. 7.1 Ley 11/2002: «1\\. El Centro Nacional de Inteligencia se adscribe orgánicamente al Ministerio de Defensa.»","Art. 3 Ley 11/2002: «El Gobierno determinará y aprobará anualmente los objetivos del Centro Nacional de Inteligencia mediante la Directiva de Inteligencia, que tendrá carácter secreto.»","Art. 9.1 Ley 11/2002: «El mandato será de cinco años, sin perjuicio de la facultad del Consejo de Ministros de proceder a su sustitución en cualquier momento.»","CNI, La Inteligencia CNI, «La Inteligencia»: «El resultado final del trabajo del CNI es la Inteligencia que entrega a las autoridades para facilitar la toma de decisiones y que se elabora siguiendo un proceso con fases bien definidas, denominado ciclo de Inteligencia.»","CNI, La Inteligencia: Dirección CNI, «La Inteligencia»: «El ciclo de Inteligencia se inicia con la aprobación anual de la Directiva de Inteligencia por parte de la Comisión Delegada del Gobierno para Asuntos de Inteligencia y del presidente del Gobierno.»","CNI, La Inteligencia: Planificación CNI, «La Inteligencia»: «Una vez aprobada la Directiva de Inteligencia, el CNI realiza un proceso de planificación y organización de los recursos disponibles para obtener la información necesaria»","CNI, La Inteligencia: Elaboración CNI, «La Inteligencia»: «Valoración Se analiza la calidad y origen de la información»","CNI, La Inteligencia: Obtención CNI, «La Inteligencia»: «GEOINT Información procedente de la explotación y análisis de imágenes e información geográfica.»","Art. 1 Ley 11/2002: «El Centro Nacional de Inteligencia es el Organismo público responsable de facilitar al Presidente del Gobierno y al Gobierno de la Nación las informaciones, análisis, estudios o propuestas»","Art. 2.3 Ley 11/2002: «3\\. En el desarrollo de sus funciones, el Centro Nacional de Inteligencia actuará bajo los principios de eficacia, especialización y coordinación, de acuerdo con los objetivos de inteligencia definidos por el Gobierno.»","Art. 6.1 Ley 11/2002: «1\\. La Comisión Delegada del Gobierno para Asuntos de Inteligencia velará por la adecuada coordinación de todos los servicios de información e inteligencia del Estado para la formación de una comunidad de inteligencia.»","Art. 5.4 Ley 11/2002: «4\\. Los miembros del Centro Nacional de Inteligencia no tendrán la consideración de agentes de la autoridad, con excepción de aquellos que desempeñen cometidos profesionales relacionados con la protección del personal del Centro y de las instalaciones del mismo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.cni.es/la-inteligencia'), 'https://www.cni.es/la-inteligencia', null, null, null, 'Otras normas citadas: Ley 11/2002 (https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628)'
  from public.topics t where t.slug = 'pn-40-inteligencia-osint'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
