insert into public.sources (title, url, kind, publisher, published_on) values ('INCIBE · Glosario de términos de ciberseguridad: una guía de aproximación para el empresario (2021)', 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf', 'web_oficial'::public.source_kind, 'Instituto Nacional de Ciberseguridad (INCIBE)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-41-ciberdelincuencia', 'Tema 41. Ciberdelincuencia y agentes de la amenaza') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-41-ciberdelincuencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Malware: virus, gusanos, troyanos, ransomware y spyware"},{"n":"2","title":"Ingeniería social: phishing, spear phishing, fraude del CEO, cartas nigerianas"},{"n":"3","title":"Ataques técnicos: DoS/DDoS, botnets, pharming, spoofing, inyección SQL, XSS, zero-day"},{"n":"4","title":"Agentes de la amenaza: hacktivistas, insiders, APT"},{"n":"5","title":"Cibercriminalidad en la Estrategia Nacional de Ciberseguridad 2019"}]'::jsonb, '["Glosario INCIBE, Ransomware Glosario INCIBE: «Malware cuya funcionalidad es «secuestrar» un dispositivo (en sus inicios) o la información que contiene de forma que si la víctima no paga el rescate, no podrá acceder a ella.»","Glosario INCIBE, Phishing Glosario INCIBE: «Técnica o tipo de ataque en el que alguien suplanta a una entidad/servicio mediante un correo electrónico o mensaje instantáneo para conseguir las credenciales o información de la tarjeta de crédito de un usuario.»","Glosario INCIBE, Botnet Glosario INCIBE: «Una botnet es un conjunto de ordenadores (denominados bots) controlados remotamente por un atacante que pueden ser utilizados en conjunto para realizar actividades maliciosas como envío de spam, ataques de DDoS, etc.»","Glosario INCIBE, Denegación de servicio Glosario INCIBE: «Ataque a un sistema, aplicación o dispositivo para dejarlo fuera de servicio debido a una saturación de peticiones.»","Glosario INCIBE, Spyware Glosario INCIBE: «Es un malware que recopila información de un ordenador y después la envía a una entidad remota sin el conocimiento o el consentimiento del propietario del ordenador.»","Glosario INCIBE, Insider Glosario INCIBE: «Persona perteneciente a una organización o empresa que divulga información sensible sobre dicha empresa de forma intencionada.»","Glosario INCIBE, Pharming Glosario INCIBE: «Ataque informático que aprovecha una vulnerabilidad del software de los servidores DNS y que consiste en modificar o sustituir el archivo del servidor de nombres de dominio cambiando la dirección IP legítima de una entidad»","Glosario INCIBE, Spear phishing Glosario INCIBE: «Modalidad de phishing dirigido contra un usuario u organización en concreto en la que los atacantes intentan mediante un correo electrónico, que aparenta ser de un amigo o de empresa conocida, conseguir información confidencial.»","Glosario INCIBE, Fraude del CEO Glosario INCIBE: «Ataque de ingeniería social, variante del spear phishing, que se caracteriza porque el fraude está dirigido a miembros concretos de la organización, principalmente ejecutivos de alto nivel»","Glosario INCIBE, Ingeniería social Glosario INCIBE: «Conjunto de técnicas que los delincuentes usan para engañar a los usuarios de sistemas/servicios TIC para que les faciliten datos que les aporten valor, ya sean credenciales, información sobre los sistemas, servicios instalados etc.»","Glosario INCIBE, Inyección SQL Glosario INCIBE: «Es un tipo de ataque que se aprovecha de una vulnerabilidad en la validación de los contenidos introducidos en un formulario web y que puede permitir la obtención de forma ilegítima de los datos almacenados en la base de datos del sitio web, entre ellos las credenciales de acceso.»","Glosario INCIBE, XSS Glosario INCIBE: «XSS viene del acrónimo en inglés de Secuencias de comandos en sitios cruzados (Cross-site Scripting).»","Glosario INCIBE, Zero-day Glosario INCIBE: «Son aquellas vulnerabilidades en sistemas o programas informáticos que son únicamente conocidas por determinados atacantes y son desconocidas por los fabricantes y usuarios. Al ser desconocidas por los fabricantes, no existe un parche de seguridad para solucionarlas.»","Glosario INCIBE, Hacktivista Glosario INCIBE: «Ciberdelincuente que haciendo uso de sus conocimientos en materia informática y herramientas digitales los usa para promover su ideología política.»","Glosario INCIBE, Cartas nigerianas Glosario INCIBE: «Se trata de una comunicación inesperada mediante correo electrónico carta o mensajería instantánea en las que el remitente promete negocios muy rentables.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf', null, null, null, null
  from public.topics t where t.slug = 'pn-41-ciberdelincuencia'
