insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 137/1993, de 29 de enero, Reglamento de Armas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-42-armas', 'Tema 42. Armas de fuego: definición, clasificación y categorías, armas prohibidas y documentación (Reglamento de Armas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-42-armas' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Definiciones del Reglamento de Armas (art. 2)"},{"n":"2","title":"Categorías de armas (art. 3)"},{"n":"3","title":"Armas prohibidas (arts. 4 y 5)"},{"n":"4","title":"Armas de guerra (art. 6)"},{"n":"5","title":"Licencias y documentación de armas"}]'::jsonb, '["Art. 2.12 Reglamento de Armas: «12. Arma de fuego: Toda arma portátil que tenga cañón y que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un perdigón, una bala o un proyectil por la acción de un combustible propulsor.»","Art. 2.13 Reglamento de Armas: «13. Arma de fuego corta: Arma de fuego cuyo cañón no exceda de 30 cm o cuya longitud total no exceda de 60 cm.»","Art. 2.5 y 2.21 Reglamento de Armas: «21. Arma semiautomática: Arma de fuego que después de cada disparo se recarga automáticamente y con la que solo es posible efectuar un disparo al accionar el disparador cada vez.»","Art. 2.2 Reglamento de Armas: «2. Arma antigua: Arma de fuego cuyo modelo o cuyo año de fabricación es anterior al 1 de enero de 1890.»","Art. 2.29 Reglamento de Armas: «29. Munición: Cartucho completo o sus componentes, incluidas las vainas, los cebos, la carga propulsora, las balas o los proyectiles utilizados en un arma de fuego, siempre que estos componentes estén autorizados en territorio nacional.»","Art. 3 Reglamento de Armas: «1.ª categoría: Armas de fuego cortas: Comprende las pistolas y revólveres.»","Art. 3 Reglamento de Armas: «3. Armas accionadas por aire u otro gas comprimido, sean lisas o rayadas, siempre que la energía cinética del proyectil en boca exceda de 24,2 julios.»","Art. 3 Reglamento de Armas: «7.ª categoría: 1. Armas de inyección anestésica capaces de lanzar proyectiles que faciliten la captura o control de animales, anestesiándolos a distancia durante algún tiempo. 2. Las ballestas.»","Art. 3 Reglamento de Armas: «8.ª categoría: Armas acústicas y de salvas. 9.ª categoría: Armas inutilizadas.»","Art. 4.1.f) Reglamento de Armas: «f) Los bastones-estoque, los puñales de cualquier clase y las navajas llamadas automáticas. Se considerarán puñales a estos efectos las armas blancas de hoja menor de 11 centímetros, de dos filos y puntiaguda.»","Art. 4.1.c) Reglamento de Armas: «c) Las pistolas y revólveres que lleven adaptado un culatín.»","Art. 5.1.k) y m) Reglamento de Armas: «k) Los silenciadores adaptables a armas de fuego.»","Art. 5.1.j) Reglamento de Armas: «1. Queda prohibida la publicidad, compraventa, tenencia y uso, salvo por funcionarios especialmente habilitados, y de acuerdo con lo que dispongan las respectivas normas reglamentarias de: […] j) Las defensas eléctricas, las defensas de goma o extensibles, y las tonfas o similares.»","Art. 6.1 Reglamento de Armas: «a) Armas de fuego o sistemas de armas de fuego de calibre igual o superior a 20 milímetros.»","Art. 96.3 Reglamento de Armas: «3. La licencia de armas A, con la eficacia de las licencias B, D y E, reguladas en los artículos 99 a 104 de este Reglamento, documentará las armas de las categorías 1.ª, 2.ª y 3.ª de propiedad privada del personal de los Cuerpos Específicos de los Ejércitos, de los Cuerpos Comunes de las Fuerzas Armadas, de las Fuerzas y Cuerpos de Seguridad y del Servicio de Vigilancia Aduanera.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202', null, null, null, null
  from public.topics t where t.slug = 'pn-42-armas'
on conflict (topic_id, locale) do update
