insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 1428/2003, de 21 de noviembre, Reglamento General de Circulación (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-43-vehiculo-prioritario', 'Tema 43. El vehículo prioritario: facultades de sus conductores, comportamiento de los demás y señales de emergencia') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-43-vehiculo-prioritario' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto de vehículo prioritario y servicios de urgencia"},{"n":"2","title":"Facultades de los conductores de vehículos prioritarios (arts. 67 y 68 RGC)"},{"n":"3","title":"Comportamiento de los demás conductores (art. 69 RGC)"},{"n":"4","title":"Señales de los vehículos prioritarios (LSV y RGC)"}]'::jsonb, '["Art. 67.1 Reglamento General de Circulación: «1. Tendrán prioridad de paso sobre los demás vehículos y otros usuarios de la vía los vehículos de servicios de urgencia, públicos o privados, cuando se hallen en servicio de tal carácter.»","Art. 67.1 Reglamento General de Circulación: «Podrán circular por encima de los límites de velocidad y estarán exentos de cumplir otras normas o señales en los casos y con las condiciones que se determinan en esta sección»","Art. 67.2 Reglamento General de Circulación: «2. Los conductores de los vehículos destinados a los referidos servicios harán uso ponderado de su régimen especial únicamente cuando circulen en prestación de un servicio urgente»","Art. 67.3 Reglamento General de Circulación: «3. La instalación de aparatos emisores de luces y señales acústicas especiales en vehículos prioritarios requerirá autorización de la Jefatura Provincial de Tráfico correspondiente»","Art. 68.1 Reglamento General de Circulación: «podrán dejar de cumplir bajo su exclusiva responsabilidad las normas de los títulos II, III y IV, salvo las órdenes y señales de los agentes, que son siempre de obligado cumplimiento.»","Art. 68.1 Reglamento General de Circulación: «dar media vuelta o marcha atrás, circular en sentido contrario al correspondiente a la calzada, siempre que lo hagan por el arcén, o penetrar en la mediana o en los pasos transversales de ésta.»","Art. 68.2 Reglamento General de Circulación: «2. Tendrán el carácter de prioritarios los vehículos de los servicios de policía, extinción de incendios, protección civil y salvamento, y de asistencia sanitaria, pública o privada, que circulen en servicio urgente»","Art. 68.2 Reglamento General de Circulación: «y cuyos conductores adviertan de su presencia mediante la utilización simultánea de la señal luminosa y del aparato emisor de señales acústicas especiales previstos en el anexo XI del Reglamento General de Vehículos.»","Art. 68.2 Reglamento General de Circulación: «Por excepción de lo dispuesto en el párrafo anterior, los conductores de los vehículos prioritarios deberán utilizar la señal luminosa aisladamente cuando la omisión de las señales acústicas especiales no entrañe peligro alguno para los demás usuarios.»","Art. 68.3 Reglamento General de Circulación: «3. Las infracciones a las normas de este precepto tendrán la consideración de graves»","Art. 69 Reglamento General de Circulación: «los demás conductores adoptarán las medidas adecuadas, según las circunstancias del momento y lugar, para facilitarles el paso, apartándose normalmente a su derecha o deteniéndose si fuera preciso, o actuando conforme a lo dispuesto en el artículo 32.»","Art. 69 Reglamento General de Circulación: «el conductor de este deberá detenerlo con las debidas precauciones en el lado derecho, delante del vehículo policial, en un lugar donde no genere mayores riesgos o molestias para el resto de los usuarios, y permanecerá en su interior.»","Art. 32.1 Reglamento General de Circulación: «En las autopistas y autovías que tengan dos carriles en el mismo sentido, el carril de emergencia deberá formarse en el centro de la vía, entre esos dos carriles.»","Art. 32.1 Reglamento General de Circulación: «En las autopistas y autovías que tengan tres o más carriles en el mismo sentido, el carril de emergencia deberá formarse entre el carril situado más a la izquierda y el carril contiguo a él.»","Art. 70.1 Reglamento General de Circulación: «utilizando para ello el avisador acústico en forma intermitente y conectando la luz de emergencia, si se dispusiera de ella, o agitando un pañuelo o procedimiento similar.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514', null, null, null, null
  from public.topics t where t.slug = 'pn-43-vehiculo-prioritario'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
