insert into public.topics (slug, title) values ('pn-45-prl-seguridad-vial', 'Tema 45. Prevención de riesgos laborales en seguridad vial: factores del tráfico y riesgos en la conducción') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-45-prl-seguridad-vial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La seguridad vial laboral y los accidentes in itinere y en misión"},{"n":"2","title":"Factores del tráfico: humano, vehículo y vía"},{"n":"3","title":"Riesgos en la conducción: fatiga, distracciones y velocidad"},{"n":"4","title":"Distancias de seguridad y de detención"},{"n":"5","title":"Prevención de riesgos laborales: principios y equipos de protección (Ley 31/1995)"}]'::jsonb, '["DGT, «Seguridad vial laboral» DGT, «Muévete con seguridad»: «Tanto los trayectos que se realizan durante la jornada laboral como los desplazamientos de ida y vuelta al puesto de trabajo (in itinere), pueden conllevar riesgos importantes que no deben subestimarse.»","DGT, «Seguridad vial laboral» DGT, «Muévete con seguridad»: «La seguridad vial en entornos laborales comprende el conjunto de acciones, políticas y medidas orientadas a prevenir los siniestros viales ocurridos en el entorno de trabajo.»","DGT, «Marco normativo y estratégico» DGT, «Muévete con seguridad»: «Adoptando el enfoque del Sistema Seguro, esta Estrategia promueve intervenciones integradas que abordan todos los factores que influyen en la seguridad vial: personas, vehículos, infraestructuras, velocidad, normativa y atención post-siniestro.»","DGT, «Conducir con fatiga» DGT, «Muévete con seguridad»: «La fatiga se relaciona con el 20-30% de los accidentes de tráfico. Su principal causa es conducir sin descanso durante demasiado tiempo.»","DGT, «Conducir con fatiga» DGT, «Muévete con seguridad»: «Factores del vehículo Ver más Una mala ventilación o una temperatura elevada en el interior del vehículo pueden hacer más incómoda la conducción o incluso alterar el estado del conductor»","DGT, «Conducir con fatiga» DGT, «Muévete con seguridad»: «Factores externos: la vía y el entorno Ver más Circular por una vía con una elevada densidad de tráfico, en la que te ves sometido a frecuentes retenciones y paradas, requiere aumentar la atención y la concentración necesaria para circular, lo que puede potenciar la fatiga.»","DGT, «Conducir con fatiga» DGT, «Muévete con seguridad»: «Los conductores noveles, al no haber automatizado todavía muchos de los procesos implicados en la conducción, han de concentrarse de manera más elevada en ellos y se fatigan con mayor facilidad.»","DGT, «Distracciones al volante» DGT, «Muévete con seguridad»: «Pero las distracciones al volante son la causa de más del 30% de los accidentes.»","DGT, «Distracciones al volante» DGT, «Muévete con seguridad»: «Su manejo debe realizarse siempre antes de comenzar el viaje y siempre con el vehículo parado.»","DGT, «Conducción preventiva» DGT, «Muévete con seguridad»: «Para evitar un alcance son necesarios, al menos, dos segundos de diferencia entre vehículos»","DGT, «Conducción preventiva» DGT, «Muévete con seguridad»: «Dentro de un túnel, por ejemplo, la distancia de seguridad deberá ampliarse, al menos a 100 metros o 4 segundos de intervalo cuando no se pretenda adelantar.»","DGT, «Conducción preventiva» DGT, «Muévete con seguridad»: «Las cinco distracciones más habituales y que tenemos que evitar son: Cansancio, móvil, radio, acompañantes, GPS.»","DGT, «Conducir con exceso de velocidad» DGT, «Muévete con seguridad»: «La distancia de detención es igual a la suma de la distancia de reacción (espacio que recorres antes de pisar el freno) más la distancia de frenado (espacio que recorres durante la frenada).»","DGT, «Conducir con exceso de velocidad» DGT, «Muévete con seguridad»: «Se suele considerar normal un tiempo de reacción de 0,75 segundos, durante los cuales recorrerás más o menos metros dependiendo de la velocidad a la que circules.»","DGT, «Conducir con exceso de velocidad» DGT, «Muévete con seguridad»: «Uno de cada cinco accidentes de tráfico con víctimas se puede relacionar directamente con el exceso de velocidad.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.dgt.es/muevete-con-seguridad/'), 'https://www.dgt.es/muevete-con-seguridad/', null, null, null, null
  from public.topics t where t.slug = 'pn-45-prl-seguridad-vial'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
